INSERT INTO `course` (`id`, `title`, `short_description`, `description`, `outcomes`, `faqs`, `language`, `category_id`, `sub_category_id`, `section`, `requirements`, `price`, `discount_flag`, `discounted_price`, `level`, `user_id`, `thumbnail`, `video_url`, `date_added`, `last_modified`, `course_type`, `is_top_course`, `is_admin`, `status`, `course_overview_provider`, `meta_keywords`, `meta_description`, `is_free_course`, `multi_instructor`, `enable_drip_content`, `creator`, `expiry_period`, `upcoming_image_thumbnail`, `publish_date`) VALUES
(1, 'Front Office Fundamentals', 'How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.', 'How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to. The course is built around the procedure as it is actually carried out on shift, with a written standard, the common mistakes, and a checklist to work through.', '[\"Carry out the procedure to the written standard without supervision.\",\"Recognise the common failures in this task and correct them.\",\"Complete the associated checklist and record the result.\",\"Know when the situation must be escalated to a supervisor.\"]', '{\"How long does this course take?\":\"About 180 minutes of study, which can be split across shifts.\",\"Is a certificate issued?\":\"Yes. A certificate with a verification code is issued once the course and its assessment are passed.\",\"Is the course available in Arabic?\":\"Yes. Every lesson exists in English and Arabic, and the Arabic version is laid out right to left.\"}', 'English', 1, 10, '[3257,3258,3259,3260]', '[\"No prior study is required. Access to the relevant work area is useful for the practice checklist.\"]', 0, 0, 0, 'beginner', '4', 'uploads/academy/front-office.webp', '', 1789564727, 1790232762, 'general', 1, 1, 'active', NULL, 'ha:fo-fundamentals', 'How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.', 1, 0, 0, 4, 0, NULL, '1790232612'),
(2, 'Reception Operations', 'Running the desk hour by hour: queue management, shift handover, cash float, key control and the daily reports.', 'Running the desk hour by hour: queue management, shift handover, cash float, key control and the daily reports. The course is built around the procedure as it is actually carried out on shift, with a written standard, the common mistakes, and a checklist to work through.', '[\"Carry out the procedure to the written standard without supervision.\",\"Recognise the common failures in this task and correct them.\",\"Complete the associated checklist and record the result.\",\"Know when the situation must be escalated to a supervisor.\"]', '{\"How long does this course take?\":\"About 150 minutes of study, which can be split across shifts.\",\"Is a certificate issued?\":\"Yes. A certificate with a verification code is issued once the course and its assessment are passed.\",\"Is the course available in Arabic?\":\"Yes. Every lesson exists in English and Arabic, and the Arabic version is laid out right to left.\"}', 'English', 1, 10, '[3261,3262,3263,3264]', '[\"No prior study is required. Access to the relevant work area is useful for the practice checklist.\"]', 0, 0, 0, 'beginner', '4', 'uploads/academy/front-office.webp', '', 1789564727, 1790232762, 'general', 0, 1, 'active', NULL, 'ha:fo-reception-operations', 'Running the desk hour by hour: queue management, shift handover, cash float, key control and the daily reports.', 1, 0, 0, 4, 0, NULL, '1790232612'),
(3, 'Guest Check-in', 'The arrival sequence from greeting to room handover, including identity verification and Saudi registration requirements.', 'The arrival sequence from greeting to room handover, including identity verification and Saudi registration requirements. The course is built around the procedure as it is actually carried out on shift, with a written standard, the common mistakes, and a checklist to work through.', '[\"Carry out the procedure to the written standard without supervision.\",\"Recognise the common failures in this task and correct them.\",\"Complete the associated checklist and record the result.\",\"Know when the situation must be escalated to a supervisor.\"]', '{\"How long does this course take?\":\"About 90 minutes of study, which can be split across shifts.\",\"Is a certificate issued?\":\"Yes. A certificate with a verification code is issued once the course and its assessment are passed.\",\"Is the course available in Arabic?\":\"Yes. Every lesson exists in English and Arabic, and the Arabic version is laid out right to left.\"}', 'English', 1, 10, '[3265,3266,3267,3268]', '[\"No prior study is required. Access to the relevant work area is useful for the practice checklist.\"]', 0, 0, 0, 'beginner', '4', 'uploads/academy/front-office.webp', '', 1789564727, 1790232762, 'general', 1, 1, 'active', NULL, 'ha:fo-check-in', 'The arrival sequence from greeting to room handover, including identity verification and Saudi registration requirements.', 1, 0, 0, 4, 0, NULL, '1790232612'),
