INSERT INTO `ha_competitor` (`id`, `name`, `slug`, `website`, `country`, `target_audience`, `languages`, `content_type`, `pricing_model`, `pricing_evidence_url`, `content_frequency`, `strengths`, `gaps`, `evidence_url`, `last_checked_at`, `checked_by`, `notes`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Typsy', 'typsy', 'https://www.typsy.com/', 'Australia', 'Hotels, restaurants and hospitality operators', 'English', 'Short video lessons, certificates, mobile learning, custom SOP content, performance reporting', 'Subscription', 'https://www.typsy.com/', NULL, 'Positions itself as a hospitality-specific learning platform combining video lessons, certificates, mobile access, custom SOP content and performance-oriented reporting.', 'Publicly presented material is English-first; no Arabic or right-to-left interface is evidenced on the cited page.', 'https://www.typsy.com/', '2026-09-24', 2, 'Recorded from the cited public page only. Anything not stated there is marked unknown.', 'active', '2026-09-16 11:38:52', '2026-09-24 07:04:50'),
(2, 'Saudi Tourism Authority learning service', 'saudi-tourism-authority-learning', 'https://my.gov.sa/en/services/2706562', 'Saudi Arabia', 'Tourism sector businesses and their employees', 'Arabic, English', 'Electronic learning courses for the tourism sector, with attendance certificates on qualifying courses', 'Government service', 'https://my.gov.sa/en/services/2706562', NULL, 'A government-provided electronic learning service for the tourism sector, listed on the national services portal, with certificates of attendance available for qualifying courses.', 'Scope is tourism-sector learning as a public service rather than a hotel workforce compliance and SOP platform.', 'https://my.gov.sa/en/services/2706562', '2026-09-24', 2, 'Recorded from the cited public page only. Anything not stated there is marked unknown.', 'active', '2026-09-16 11:38:52', '2026-09-24 07:04:50'),
(3, 'Future Skills Institute (FSI)', 'fsi', 'https://fsi.edu.sa/en/free-courses', 'Saudi Arabia', 'Hospitality, hotel, restaurant and cafe sector workers', 'Arabic, English', 'Free hospitality workforce training tracks covering hotel, restaurant and cafe sectors', 'Free on listed programmes', 'https://fsi.edu.sa/en/free-courses', NULL, 'Advertises free hospitality workforce training tracks across hotel, restaurant and cafe sectors, and states that accredited certificates with verification codes are available on qualifying programmes.', 'Delivery is programme-based training rather than an ongoing workforce compliance and SOP management platform for an operator.', 'https://fsi.edu.sa/en/free-courses', '2026-09-24', 2, 'Recorded from the cited public page only. Anything not stated there is marked unknown.', 'active', '2026-09-16 11:38:52', '2026-09-24 07:04:50');
