INSERT INTO `ha_lesson_translation` (`id`, `lesson_id`, `locale`, `title`, `objective`, `body`, `transcript`, `captions_url`) VALUES
(11989, 5995, 'en', 'Why this matters: Front Office Fundamentals', 'Where this work sits in the hotel day and what depends on it being done correctly.', '<p>Where this work sits in the hotel day and what depends on it being done correctly.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(11990, 5995, 'ar', 'لماذا يهم هذا الدرس: أساسيات مكتب الاستقبال', 'أين يقع هذا العمل في يوم الفندق وما الذي يعتمد على تنفيذه بشكل صحيح.', '<p>أين يقع هذا العمل في يوم الفندق وما الذي يعتمد على تنفيذه بشكل صحيح.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(11991, 5996, 'en', 'What you will be able to do: Front Office Fundamentals', 'The specific tasks you should be able to carry out unaided after this course.', '<p>The specific tasks you should be able to carry out unaided after this course.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(11992, 5996, 'ar', 'ما ستكون قادراً على فعله: أساسيات مكتب الاستقبال', 'المهام المحددة التي ينبغي أن تؤديها دون مساعدة بعد هذه الدورة.', '<p>المهام المحددة التي ينبغي أن تؤديها دون مساعدة بعد هذه الدورة.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(11993, 5997, 'en', 'The procedure demonstrated: Front Office Fundamentals', 'A walkthrough of the procedure as it is carried out on shift, step by step.', '<p>A walkthrough of the procedure as it is carried out on shift, step by step.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(11994, 5997, 'ar', 'عرض الإجراء عملياً: أساسيات مكتب الاستقبال', 'شرح عملي للإجراء كما يُنفذ أثناء الوردية، خطوة بخطوة.', '<p>شرح عملي للإجراء كما يُنفذ أثناء الوردية، خطوة بخطوة.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(11995, 5998, 'en', 'The written standard: Front Office Fundamentals', 'The standard in writing, with the points an inspection or audit will look at.', '<p>The standard in writing, with the points an inspection or audit will look at.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(11996, 5998, 'ar', 'المعيار المكتوب: أساسيات مكتب الاستقبال', 'المعيار مكتوباً مع النقاط التي سينظر إليها التفتيش أو التدقيق.', '<p>المعيار مكتوباً مع النقاط التي سينظر إليها التفتيش أو التدقيق.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(11997, 5999, 'en', 'Reference sheet: Front Office Fundamentals', 'A one page summary to keep at the workstation.', '<p>A one page summary to keep at the workstation.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(11998, 5999, 'ar', 'ورقة مرجعية: أساسيات مكتب الاستقبال', 'ملخص من صفحة واحدة للاحتفاظ به في موقع العمل.', '<p>ملخص من صفحة واحدة للاحتفاظ به في موقع العمل.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(11999, 6000, 'en', 'Common mistakes: Front Office Fundamentals', 'The errors that appear most often in this task and what causes each one.', '<p>The errors that appear most often in this task and what causes each one.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(12000, 6000, 'ar', 'الأخطاء الشائعة: أساسيات مكتب الاستقبال', 'الأخطاء الأكثر تكراراً في هذه المهمة وسبب كل منها.', '<p>الأخطاء الأكثر تكراراً في هذه المهمة وسبب كل منها.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(12001, 6001, 'en', 'Working under pressure: Front Office Fundamentals', 'How to keep the standard when the operation is busy, short staffed or running late.', '<p>How to keep the standard when the operation is busy, short staffed or running late.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(12002, 6001, 'ar', 'العمل تحت الضغط: أساسيات مكتب الاستقبال', 'كيف تحافظ على المعيار عندما يكون التشغيل مزدحماً أو ناقص الطاقم أو متأخراً.', '<p>كيف تحافظ على المعيار عندما يكون التشغيل مزدحماً أو ناقص الطاقم أو متأخراً.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(12003, 6002, 'en', 'Practice checklist: Front Office Fundamentals', 'Work through the task against the checklist and confirm each point.', '<p>Work through the task against the checklist and confirm each point.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(12004, 6002, 'ar', 'قائمة التحقق التطبيقية: أساسيات مكتب الاستقبال', 'نفّذ المهمة وفق قائمة التحقق وأكد كل بند.', '<p>نفّذ المهمة وفق قائمة التحقق وأكد كل بند.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(12005, 6003, 'en', 'Review before the quiz: Front Office Fundamentals', 'A short recap of the points the assessment covers.', '<p>A short recap of the points the assessment covers.</p><p>How the front desk fits into a hotel day, the shift structure, the systems in use and the standards every agent works to.</p>', NULL, NULL),
(12006, 6003, 'ar', 'مراجعة قبل الاختبار: أساسيات مكتب الاستقبال', 'مراجعة موجزة للنقاط التي يغطيها التقييم.', '<p>مراجعة موجزة للنقاط التي يغطيها التقييم.</p><p>كيف يندمج مكتب الاستقبال في يوم الفندق، وهيكل الورديات، والأنظمة المستخدمة، والمعايير التي يعمل بها كل موظف.</p>', NULL, NULL),
(12007, 6004, 'en', 'Why this matters: Reception Operations', 'Where this work sits in the hotel day and what depends on it being done correctly.', '<p>Where this work sits in the hotel day and what depends on it being done correctly.</p><p>Running the desk hour by hour: queue management, shift handover, cash float, key control and the daily reports.</p>', NULL, NULL),
(12008, 6004, 'ar', 'لماذا يهم هذا الدرس: عمليات الاستقبال', 'أين يقع هذا العمل في يوم الفندق وما الذي يعتمد على تنفيذه بشكل صحيح.', '<p>أين يقع هذا العمل في يوم الفندق وما الذي يعتمد على تنفيذه بشكل صحيح.</p><p>إدارة المكتب ساعة بساعة: تنظيم الطابور وتسليم الوردية وصندوق النقد والتحكم بالمفاتيح والتقارير اليومية.</p>', NULL, NULL),
(12009, 6005, 'en', 'What you will be able to do: Reception Operations', 'The specific tasks you should be able to carry out unaided after this course.', '<p>The specific tasks you should be able to carry out unaided after this course.</p><p>Running the desk hour by hour: queue management, shift handover, cash float, key control and the daily reports.</p>', NULL, NULL),
