INSERT INTO `ha_program_translation` (`id`, `program_id`, `locale`, `title`, `short_description`, `description`, `outcomes`, `prerequisites`) VALUES
(1, 1, 'en', 'Hotel Front Office Professional', 'A complete front office qualification covering arrival, departure, guest handling, upselling and the night audit.', 'A complete front office qualification covering arrival, departure, guest handling, upselling and the night audit.', NULL, NULL),
(2, 1, 'ar', 'محترف مكتب الاستقبال الفندقي', 'مؤهل متكامل لمكتب الاستقبال يغطي الوصول والمغادرة والتعامل مع الضيوف والبيع الإضافي والتدقيق الليلي.', 'مؤهل متكامل لمكتب الاستقبال يغطي الوصول والمغادرة والتعامل مع الضيوف والبيع الإضافي والتدقيق الليلي.', NULL, NULL),
(3, 2, 'en', 'Housekeeping Professional', 'Room standards from the first clean to inspection, including chemical safety, laundry and productivity.', 'Room standards from the first clean to inspection, including chemical safety, laundry and productivity.', NULL, NULL),
(4, 2, 'ar', 'محترف التدبير الفندقي', 'معايير الغرف من أول تنظيف حتى التفتيش، بما في ذلك سلامة المواد والمغسلة والإنتاجية.', 'معايير الغرف من أول تنظيف حتى التفتيش، بما في ذلك سلامة المواد والمغسلة والإنتاجية.', NULL, NULL),
(5, 3, 'en', 'Food Safety Certified', 'Food safety for kitchen and service teams, covering temperature control, storage, allergens and HACCP basics.', 'Food safety for kitchen and service teams, covering temperature control, storage, allergens and HACCP basics.', NULL, NULL),
(6, 3, 'ar', 'معتمد في سلامة الغذاء', 'سلامة الغذاء لفرق المطبخ والخدمة، وتغطي ضبط الحرارة والتخزين ومسببات الحساسية وأساسيات الهاسب.', 'سلامة الغذاء لفرق المطبخ والخدمة، وتغطي ضبط الحرارة والتخزين ومسببات الحساسية وأساسيات الهاسب.', NULL, NULL),
(7, 4, 'en', 'Hospitality Supervisor', 'The step from doing the work to leading it: standards, briefings, rosters, feedback and quality auditing.', 'The step from doing the work to leading it: standards, briefings, rosters, feedback and quality auditing.', NULL, NULL),
(8, 4, 'ar', 'مشرف الضيافة', 'الانتقال من التنفيذ إلى القيادة: المعايير والاجتماعات والجداول والملاحظات وتدقيق الجودة.', 'الانتقال من التنفيذ إلى القيادة: المعايير والاجتماعات والجداول والملاحظات وتدقيق الجودة.', NULL, NULL),
(9, 5, 'en', 'Revenue and Distribution', 'Commercial control of a property: pricing, channels, direct booking and the analytics behind the decisions.', 'Commercial control of a property: pricing, channels, direct booking and the analytics behind the decisions.', NULL, NULL),
(10, 5, 'ar', 'الإيرادات والتوزيع', 'التحكم التجاري في الفندق: التسعير والقنوات والحجز المباشر والتحليلات خلف القرارات.', 'التحكم التجاري في الفندق: التسعير والقنوات والحجز المباشر والتحليلات خلف القرارات.', NULL, NULL),
(11, 6, 'en', 'Hotel Safety Essentials', 'The safety training every hotel employee needs regardless of department.', 'The safety training every hotel employee needs regardless of department.', NULL, NULL),
(12, 6, 'ar', 'أساسيات السلامة الفندقية', 'تدريب السلامة الذي يحتاجه كل موظف في الفندق بغض النظر عن قسمه.', 'تدريب السلامة الذي يحتاجه كل موظف في الفندق بغض النظر عن قسمه.', NULL, NULL);
