INSERT INTO `ha_role` (`id`, `code`, `name_en`, `name_ar`, `description_en`, `description_ar`, `scope`, `is_system`, `created_at`, `updated_at`) VALUES
(1, 'super_admin', 'Super Admin', 'مدير النظام', 'Unrestricted control of the entire platform.', 'تحكم كامل في جميع أجزاء المنصة.', 'system', 1, '2026-09-16 11:01:23', '2026-09-24 07:04:41'),
(2, 'academy_admin', 'Academy Admin', 'مدير الأكاديمية', 'Runs the academy: programs, courses, instructors, certification and content approvals.', 'يدير الأكاديمية: البرامج والدورات والمدربين والشهادات واعتماد المحتوى.', 'system', 1, '2026-09-16 11:01:23', '2026-09-24 07:04:41'),
(3, 'instructor', 'Instructor', 'مدرب', 'Builds and delivers assigned courses, grades work and answers learners.', 'ينشئ الدورات المسندة إليه ويصححها ويجيب المتدربين.', 'self', 1, '2026-09-16 11:01:23', '2026-09-24 07:04:41'),
(4, 'org_admin', 'Organization Admin', 'مدير المنشأة', 'Manages one organization: its properties, employees and training compliance.', 'يدير منشأة واحدة: فنادقها وموظفيها والتزامها التدريبي.', 'organization', 1, '2026-09-16 11:01:23', '2026-09-24 07:04:41'),
(5, 'property_manager', 'Property Manager', 'مدير الفندق', 'Runs training for one property and its departments.', 'يدير التدريب لفندق واحد وأقسامه.', 'property', 1, '2026-09-16 11:01:23', '2026-09-24 07:04:41'),
(6, 'department_manager', 'Department Manager', 'مدير القسم', 'Sees their own team, assigns training and verifies SOP acknowledgement.', 'يتابع فريقه ويكلفه بالتدريب ويتحقق من إقرار الإجراءات.', 'department', 1, '2026-09-16 11:01:23', '2026-09-24 07:04:41'),
(7, 'learner', 'Learner', 'متدرب', 'Takes assigned training, sits assessments, collects certificates and acknowledges SOPs.', 'يكمل التدريب المسند إليه ويجتاز الاختبارات ويحصل على الشهادات ويقر بالإجراءات.', 'self', 1, '2026-09-16 11:01:23', '2026-09-24 07:04:41'),
(8, 'auditor', 'Auditor', 'مدقق', 'Read-only access to compliance, certificates, audit trails and reports.', 'اطلاع فقط على الالتزام والشهادات وسجلات التدقيق والتقارير.', 'organization', 1, '2026-09-16 11:01:23', '2026-09-24 07:04:41');
