INSERT INTO `ha_seo_metadata` (`id`, `entity_type`, `entity_id`, `route_key`, `locale`, `meta_title`, `meta_description`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `twitter_card`, `schema_json`, `focus_keyword`, `secondary_keywords`, `related_keywords`, `internal_link_targets`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'page', 1, NULL, 'en', 'Hospitality Academy — Learn. Certify. Standardize. Perform.', 'Role-based hotel training, standard operating procedures and workforce certification for hospitality teams in Saudi Arabia, in Arabic and English.', NULL, 'index,follow', 'Hospitality Academy — Learn. Certify. Standardize. Perform.', 'Role-based hotel training, standard operating procedures and workforce certification for hospitality teams in Saudi Arabia, in Arabic and English.', 'uploads/academy/page-home.webp', 'summary_large_image', '{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"EducationalOrganization\",\"name\":\"Hospitality Academy\",\"url\":\"http://localhost/atlas-lms/Academy-LMS\",\"areaServed\":{\"@type\":\"Country\",\"name\":\"Saudi Arabia\"},\"availableLanguage\":[\"ar\",\"en\"]},{\"@type\":\"WebSite\",\"name\":\"Hospitality Academy\",\"url\":\"http://localhost/atlas-lms/Academy-LMS\",\"inLanguage\":\"en\"},{\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"What is Hospitality Academy?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Hospitality Academy is a hotel training and standard operating procedure platform. It provides role-based courses for hotel departments, a versioned SOP library, assessments, and certificates that can be verified publicly. Courses are available in Arabic and English.\"}},{\"@type\":\"Question\",\"name\":\"Are the courses available in Arabic?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes. Every course, lesson, procedure and public page exists in Arabic and English as separately written content, and the Arabic interface uses a genuine right-to-left layout rather than a mirrored English one.\"}},{\"@type\":\"Question\",\"name\":\"How do I verify a Hospitality Academy certificate?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Enter the verification code printed on the certificate on the public verification page. The page returns one of four results directly: valid, expired, revoked, or not found. No account is needed to check a certificate.\"}},{\"@type\":\"Question\",\"name\":\"How long does a hotel training course take?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Most courses take between forty five minutes and three hours of study, and can be split across shifts. Each course page states its own duration, and progress is saved so a learner can stop and resume.\"}},{\"@type\":\"Question\",\"name\":\"Can a hotel assign training to a whole department at once?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes. A training assignment can target an individual, a department, a property, a job role or the whole organization, with a start date, a due date, reminders before the deadline and escalation to the line manager when an item becomes overdue.\"}},{\"@type\":\"Question\",\"name\":\"What is a hotel SOP?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A hotel SOP, or standard operating procedure, is a written document that sets out exactly how a task is performed: its purpose, scope, responsibilities, required tools, numbered steps, checklist, safety notes, quality standard and escalation route. It carries a version number so a hotel can prove which version was in force at any date.\"}},{\"@type\":\"Question\",\"name\":\"Does the academy publish pass rates or success statistics?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"No. The academy does not publish pass rates, employer endorsements or accreditation claims, because those would be claims it cannot evidence to a visitor. A certificate states only what it records: who completed what, when, with what score, and whether it is still valid.\"}},{\"@type\":\"Question\",\"name\":\"Which training is mandatory for every hotel employee?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Fire safety, emergency response and the property induction are assigned to every employee regardless of department, usually with a seven day due date from their start date. Chemical safety, food safety and knife safety are mandatory for the roles that handle those hazards.\"}}]},{\"@type\":\"WebPage\",\"name\":\"Hospitality Academy — Learn. Certify. Standardize. Perform.\",\"description\":\"Role-based hotel training, standard operating procedures and workforce certification for hospitality teams in Saudi Arabia, in Arabic and English.\",\"inLanguage\":\"en\"}]}', NULL, NULL, NULL, NULL, NULL, '2026-09-16 11:38:52', '2026-09-24 07:04:50'),
(2, 'page', 1, NULL, 'ar', 'أكاديمية الضيافة — تعلّم، اعتمد، وحّد المعايير، وطوّر الأداء', 'تدريب فندقي قائم على الدور الوظيفي، وإجراءات تشغيل قياسية، واعتماد للكوادر في السعودية، بالعربية والإنجليزية.', NULL, 'index,follow', 'أكاديمية الضيافة — تعلّم، اعتمد، وحّد المعايير، وطوّر الأداء', 'تدريب فندقي قائم على الدور الوظيفي، وإجراءات تشغيل قياسية، واعتماد للكوادر في السعودية، بالعربية والإنجليزية.', 'uploads/academy/page-home.webp', 'summary_large_image', '{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"EducationalOrganization\",\"name\":\"أكاديمية الضيافة\",\"url\":\"http://localhost/atlas-lms/Academy-LMS\",\"areaServed\":{\"@type\":\"Country\",\"name\":\"Saudi Arabia\"},\"availableLanguage\":[\"ar\",\"en\"]},{\"@type\":\"WebSite\",\"name\":\"أكاديمية الضيافة\",\"url\":\"http://localhost/atlas-lms/Academy-LMS\",\"inLanguage\":\"ar\"},{\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"ما هي أكاديمية الضيافة؟\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"أكاديمية الضيافة منصة تدريب فندقي وإجراءات تشغيل قياسية. توفر دورات قائمة على الدور الوظيفي لأقسام الفنادق، ومكتبة إجراءات لها إصدارات، وتقييمات، وشهادات يمكن التحقق منها علناً. والدورات متاحة بالعربية والإنجليزية.\"}},{\"@type\":\"Question\",\"name\":\"هل الدورات متاحة بالعربية؟\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"نعم. كل دورة ودرس وإجراء وصفحة عامة موجودة بالعربية والإنجليزية كمحتوى مكتوب بشكل منفصل، والواجهة العربية تستخدم تخطيطاً حقيقياً من اليمين إلى اليسار لا واجهة إنجليزية معكوسة.\"}},{\"@type\":\"Question\",\"name\":\"كيف أتحقق من شهادة أكاديمية الضيافة؟\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"أدخل رمز التحقق المطبوع على الشهادة في صفحة التحقق العامة. تعيد الصفحة إحدى أربع نتائج مباشرة: سارية أو منتهية أو ملغاة أو غير موجودة. ولا يلزم حساب للتحقق من شهادة.\"}},{\"@type\":\"Question\",\"name\":\"كم تستغرق الدورة التدريبية الفندقية؟\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"تستغرق معظم الدورات بين خمس وأربعين دقيقة وثلاث ساعات من الدراسة، ويمكن تقسيمها على عدة ورديات. وتذكر كل صفحة دورة مدتها، ويُحفظ التقدم بحيث يستطيع المتدرب التوقف والاستئناف.\"}},{\"@type\":\"Question\",\"name\":\"هل يستطيع الفندق إسناد التدريب لقسم كامل دفعة واحدة؟\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"نعم. يمكن أن يستهدف التكليف التدريبي موظفاً أو قسماً أو فندقاً أو مسمى وظيفياً أو المنشأة بأكملها، بتاريخ بدء وتاريخ استحقاق وتذكيرات قبل الموعد وتصعيد إلى المدير المباشر عند تأخر البند.\"}},{\"@type\":\"Question\",\"name\":\"ما هو إجراء التشغيل القياسي الفندقي؟\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"إجراء التشغيل القياسي الفندقي وثيقة مكتوبة تحدد بدقة كيفية أداء المهمة: غرضها ونطاقها والمسؤوليات والأدوات المطلوبة والخطوات المرقمة وقائمة التحقق وملاحظات السلامة ومعيار الجودة ومسار التصعيد. ويحمل رقم إصدار ليتمكن الفندق من إثبات الإصدار الساري في أي تاريخ.\"}},{\"@type\":\"Question\",\"name\":\"هل تنشر الأكاديمية نسب النجاح أو إحصاءات التحصيل؟\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"لا. لا تنشر الأكاديمية نسب نجاح أو توصيات من جهات توظيف أو ادعاءات اعتماد، لأنها ادعاءات لا تستطيع إثباتها للزائر. والشهادة تذكر ما توثقه فقط: من أكمل ماذا، ومتى، وبأي درجة، وهل ما زالت سارية.\"}},{\"@type\":\"Question\",\"name\":\"ما التدريب الإلزامي لكل موظف فندقي؟\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"تُسنَد السلامة من الحريق والاستجابة للطوارئ وتعريف الفندق لكل موظف مهما كان قسمه، عادةً بتاريخ استحقاق سبعة أيام من تاريخ المباشرة. وسلامة المواد الكيميائية وسلامة الغذاء وسلامة السكاكين إلزامية للأدوار التي تتعامل مع تلك المخاطر.\"}}]},{\"@type\":\"WebPage\",\"name\":\"أكاديمية الضيافة — تعلّم، اعتمد، وحّد المعايير، وطوّر الأداء\",\"description\":\"تدريب فندقي قائم على الدور الوظيفي، وإجراءات تشغيل قياسية، واعتماد للكوادر في السعودية، بالعربية والإنجليزية.\",\"inLanguage\":\"ar\"}]}', NULL, NULL, NULL, NULL, NULL, '2026-09-16 11:38:52', '2026-09-24 07:04:50'),
(3, 'page', 2, NULL, 'en', 'About Hospitality Academy', 'Who writes the training, how it is reviewed, and what the academy will and will not claim.', NULL, 'index,follow', 'About Hospitality Academy', 'Who writes the training, how it is reviewed, and what the academy will and will not claim.', 'uploads/academy/page-home.webp', 'summary_large_image', '{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"EducationalOrganization\",\"name\":\"Hospitality Academy\",\"url\":\"http://localhost/atlas-lms/Academy-LMS\",\"areaServed\":{\"@type\":\"Country\",\"name\":\"Saudi Arabia\"},\"availableLanguage\":[\"ar\",\"en\"]},{\"@type\":\"WebPage\",\"name\":\"About Hospitality Academy\",\"description\":\"Who writes the training, how it is reviewed, and what the academy will and will not claim.\",\"inLanguage\":\"en\"}]}', NULL, NULL, NULL, NULL, NULL, '2026-09-16 11:38:52', '2026-09-24 07:04:50'),
