INSERT INTO `question` (`id`, `quiz_id`, `title`, `type`, `number_of_options`, `options`, `correct_answers`, `order`) VALUES
(1481, 5699, 'A guest arrives at 11:00 and the room is not ready. What does the agent do first?', 'single_choice', 4, '[\"Tell the guest to come back at check-in time\",\"Acknowledge it, offer luggage storage and give a specific time the room will be ready\",\"Upgrade the guest to a suite at no charge\",\"Check the guest in anyway and let them wait in the corridor\"]', '[\"2\"]', 1),
(1482, 5699, 'What does the front office hand over at shift change?', 'single_choice', 4, '[\"Only the cash float\",\"Pending arrivals, guest requests still open, out-of-order rooms and anything unresolved\",\"Nothing, the system holds all of it\",\"Only complaints\"]', '[\"2\"]', 2),
(1483, 5699, 'Which department does the front desk depend on most to sell a clean room?', 'single_choice', 4, '[\"Engineering\",\"Housekeeping\",\"Finance\",\"Sales\"]', '[\"2\"]', 3),
(1484, 5699, 'A guest asks a question the agent cannot answer. The correct response is to', 'single_choice', 4, '[\"Guess, so the guest is not kept waiting\",\"Say it is not your department\",\"Say you will find out, give a time, and come back with the answer\",\"Refer them to the website\"]', '[\"3\"]', 4),
(1485, 5700, 'A walk-in guest arrives when the hotel is full. The agent should', 'single_choice', 4, '[\"Turn them away\",\"Check for cancellations, then help them find a room nearby if there is genuinely nothing\",\"Put them in an out-of-order room\",\"Ask them to wait indefinitely\"]', '[\"2\"]', 1),
(1486, 5700, 'The arrivals list is checked at the start of a shift to', 'single_choice', 4, '[\"Count staff\",\"Know who is coming, what they have asked for and which rooms are committed\",\"Set room rates\",\"Order breakfast\"]', '[\"2\"]', 2),
(1487, 5700, 'A reservation taken by phone must be read back because', 'single_choice', 4, '[\"It is polite\",\"It catches errors in dates, room type and spelling before they become a problem at arrival\",\"The system requires it\",\"It is not read back\"]', '[\"2\"]', 3),
(1488, 5700, 'Which of these is a front desk responsibility at every shift?', 'single_choice', 4, '[\"Counting and signing for the cash float\",\"Cleaning guest rooms\",\"Cooking breakfast\",\"Fixing air conditioning\"]', '[\"1\"]', 4),
(1489, 5701, 'What must be verified before a room key is issued?', 'single_choice', 4, '[\"The guest\'s identity against the reservation\",\"The guest\'s social media\",\"Nothing, the booking is enough\",\"Only the payment card\"]', '[\"1\"]', 1),
(1490, 5701, 'A guest booked a twin room and arrives expecting a double. What is the correct step?', 'single_choice', 4, '[\"Insist the booking is correct and move on\",\"Check availability for a double, explain the options and confirm before moving them\",\"Move them without telling them\",\"Charge a change fee first\"]', '[\"2\"]', 2),
(1491, 5701, 'Rooming a guest means', 'single_choice', 4, '[\"Leaving them to find the room themselves\",\"Escorting them and showing how the room works, then confirming they have what they need\",\"Sending a bellman with the luggage only\",\"Calling the room after ten minutes\"]', '[\"2\"]', 3),
(1492, 5701, 'When should the guest be told the checkout time?', 'single_choice', 4, '[\"Never, it is on the door\",\"At check-in, along with breakfast times and Wi-Fi\",\"Only if they ask\",\"On the morning of departure\"]', '[\"2\"]', 4),
(1493, 5702, 'A guest disputes a minibar charge at checkout. What is the first step?', 'single_choice', 4, '[\"Remove it immediately without checking\",\"Insist the charge stands\",\"Check the posting with housekeeping before deciding, and keep the guest informed\",\"Ask the guest to email the hotel later\"]', '[\"3\"]', 1),
(1494, 5702, 'What should be offered at the end of every checkout?', 'single_choice', 4, '[\"A discount voucher\",\"An itemised folio and help with onward travel or luggage\",\"A review request only\",\"Nothing\"]', '[\"2\"]', 2),
(1495, 5702, 'A late checkout request should be answered by', 'single_choice', 4, '[\"Refusing automatically\",\"Checking the arrivals for that room type before committing\",\"Always agreeing\",\"Charging a full extra night in every case\"]', '[\"2\"]', 3),
(1496, 5702, 'Why does the folio need to be accurate before the guest leaves?', 'single_choice', 4, '[\"It is easier to correct in person than after departure\",\"It is a legal requirement in every country\",\"It changes the room rate\",\"It is not important\"]', '[\"1\"]', 4),
(1497, 5703, 'The guest folio is', 'single_choice', 4, '[\"The room key record\",\"The running account of every charge and payment for that stay\",\"The housekeeping report\",\"The reservation confirmation\"]', '[\"2\"]', 1),
(1498, 5703, 'Which details must be captured at registration in Saudi Arabia?', 'single_choice', 4, '[\"Name only\",\"Identity document details as required by law, plus contact and payment\",\"Nothing, the booking suffices\",\"Social media handle\"]', '[\"2\"]', 2),
(1499, 5703, 'A registration card signed by the guest establishes', 'single_choice', 4, '[\"The guest\'s agreement to the rate and the hotel\'s terms\",\"The housekeeping schedule\",\"The loyalty tier\",\"Nothing legally\"]', '[\"1\"]', 3),
(1500, 5703, 'Where a guest declines to give required identity details, the agent should', 'single_choice', 4, '[\"Check them in anyway\",\"Explain that it is a legal requirement and involve the duty manager if it is refused\",\"Refuse service without explanation\",\"Copy details from a previous stay\"]', '[\"2\"]', 4),
(1501, 5704, 'Which guest should be prioritised when assigning the best available room?', 'single_choice', 4, '[\"The latest booker\",\"Guests with an accessibility requirement, then VIP and repeat guests\",\"Whoever complains most\",\"The cheapest rate\"]', '[\"2\"]', 1),
(1502, 5704, 'An accessible room should be held for', 'single_choice', 4, '[\"Anyone, it is a normal room\",\"A guest who has requested one, until it is clear none is needed\",\"Staff use\",\"Group bookings\"]', '[\"2\"]', 2),
(1503, 5704, 'A room marked out of order should be', 'single_choice', 4, '[\"Sold at a discount\",\"Kept out of inventory until engineering releases it\",\"Assigned to a late arrival\",\"Cleaned and sold\"]', '[\"2\"]', 3),
(1504, 5704, 'Why are connecting rooms held back during a family-heavy arrival day?', 'single_choice', 4, '[\"They are harder to clean\",\"They are the only option for families travelling with children and are quickly exhausted\",\"They cost more\",\"They are not held back\"]', '[\"2\"]', 4),
(1505, 5705, 'A guest asks for a restaurant recommendation. The best answer', 'single_choice', 4, '[\"Names the hotel restaurant only\",\"Asks what they are in the mood for, then gives two or three options with reasons\",\"Hands them a directory\",\"Names the most expensive option\"]', '[\"2\"]', 1),
(1506, 5705, 'The bell desk is responsible for', 'single_choice', 4, '[\"Room cleaning\",\"Luggage handling, storage and delivery, and assisting arrivals and departures\",\"Billing\",\"Reservations\"]', '[\"2\"]', 2),
(1507, 5705, 'When storing luggage, the item must be', 'single_choice', 4, '[\"Left in the lobby\",\"Tagged with a receipt given to the guest, and stored securely\",\"Kept behind the desk untagged\",\"Taken to the guest room\"]', '[\"2\"]', 3),
(1508, 5705, 'A concierge who cannot arrange a request should', 'single_choice', 4, '[\"Say it is impossible\",\"Offer the nearest alternative and be clear about what can and cannot be done\",\"Promise and then not deliver\",\"Refer the guest to reception\"]', '[\"2\"]', 4),
(1509, 5706, 'A guest is angry about noise from the room above. What comes first?', 'single_choice', 4, '[\"Explain the hotel policy\",\"Listen without interrupting, acknowledge the problem and apologise for the effect on them\",\"Offer a free night\",\"Ask them to put it in writing\"]', '[\"2\"]', 1),
(1510, 5706, 'What does LEARN stand for in complaint handling?', 'single_choice', 4, '[\"Listen, Empathise, Apologise, React, Notify\",\"Leave, Escalate, Argue, Refuse, Note\",\"Log, Email, Assign, Review, Notify\",\"Listen, Explain, Argue, Refund, Note\"]', '[\"1\"]', 2),
(1511, 5706, 'When a complaint cannot be resolved by the agent, the correct action is', 'single_choice', 4, '[\"Tell the guest nothing can be done\",\"Escalate to the duty manager with the facts, and tell the guest who will contact them and when\",\"Give the guest the manager\'s mobile number\",\"Wait until the next shift\"]', '[\"2\"]', 3),
(1512, 5706, 'Why is every complaint logged, even one resolved on the spot?', 'single_choice', 4, '[\"To justify refusing a refund later\",\"So repeat causes can be found and fixed\",\"It is not logged if resolved\",\"To record which staff member was at fault\"]', '[\"2\"]', 4),
(1513, 5707, 'A returning guest\'s preferences should be', 'single_choice', 4, '[\"Asked again every stay as if new\",\"Held on the profile and acted on before arrival\",\"Guessed\",\"Ignored\"]', '[\"2\"]', 1),
(1514, 5707, 'A VIP arrival is prepared by', 'single_choice', 4, '[\"Doing nothing different\",\"Checking the room personally, confirming amenities are placed and briefing the team who will meet them\",\"Assigning any available room\",\"Upgrading automatically\"]', '[\"2\"]', 2),
(1515, 5707, 'Recognising a repeat guest by name at arrival matters because', 'single_choice', 4, '[\"It is required by law\",\"It is the clearest signal that the hotel remembers them, and it costs nothing\",\"It speeds up check-in\",\"It does not matter\"]', '[\"2\"]', 3),
(1516, 5707, 'A VIP complaint should be handled', 'single_choice', 4, '[\"The same as any other, with the duty manager informed early\",\"By giving whatever is asked for\",\"By ignoring the normal process\",\"By the general manager only\"]', '[\"1\"]', 4),
(1517, 5708, 'Within how many rings should an internal call be answered as a standard?', 'single_choice', 4, '[\"Three\",\"Eight\",\"Fifteen\",\"It does not matter\"]', '[\"1\"]', 1),
(1518, 5708, 'The correct greeting on answering an external call includes', 'single_choice', 4, '[\"Just \\\"hello\\\"\",\"The hotel name, the department, your name and an offer of help\",\"Only your name\",\"The room number\"]', '[\"2\"]', 2),
(1519, 5708, 'Before placing a caller on hold you should', 'single_choice', 4, '[\"Put them on hold immediately\",\"Ask permission, explain why, and thank them when you return\",\"Transfer them instead\",\"Tell them to call back\"]', '[\"2\"]', 3),
(1520, 5708, 'A caller asks to be put through to a guest room. The agent should', 'single_choice', 4, '[\"Connect without confirming anything\",\"Ask for the guest name, and connect without revealing the room number\",\"Give the room number so the caller can dial direct\",\"Refuse all such calls\"]', '[\"2\"]', 4),
(1521, 5709, 'The best moment to offer a room upgrade is', 'single_choice', 4, '[\"After the guest has paid and left the desk\",\"At check-in, once you know what the guest is here for\",\"By email a week later\",\"At checkout\"]', '[\"2\"]', 1),
(1522, 5709, 'An effective upsell is based on', 'single_choice', 4, '[\"The highest priced room\",\"A benefit that matches what the guest said they need\",\"Pressure\",\"A script read word for word\"]', '[\"2\"]', 2),
(1523, 5709, 'A guest declines the upgrade. The agent should', 'single_choice', 4, '[\"Ask again immediately\",\"Accept it gracefully and continue the check-in normally\",\"Note them as difficult\",\"Offer a discount on the same room\"]', '[\"2\"]', 3),
(1524, 5709, 'Why does upselling fail when the guest is tired and late?', 'single_choice', 4, '[\"It does not fail\",\"The guest wants the room, not a decision, and pressing reads as an obstacle\",\"The system blocks it\",\"Rates change at night\"]', '[\"2\"]', 4),
(1525, 5710, 'The night audit exists to', 'single_choice', 4, '[\"Clean the lobby\",\"Close the financial day, post room and tax charges and reconcile the day\'s revenue\",\"Prepare breakfast\",\"Reset the key system\"]', '[\"2\"]', 1),
(1526, 5710, 'A discrepancy found during the audit should be', 'single_choice', 4, '[\"Corrected silently\",\"Documented with the correction and passed to the accounts team\",\"Left for the morning shift\",\"Ignored if it is small\"]', '[\"2\"]', 2),
(1527, 5710, 'Rooms still showing as occupied after the expected departure should be', 'single_choice', 4, '[\"Charged automatically\",\"Checked against housekeeping status before any charge is raised\",\"Released without checking\",\"Reported to the police\"]', '[\"2\"]', 3),
(1528, 5710, 'Why is the audit run at night?', 'single_choice', 4, '[\"Staff are cheaper\",\"It is the quietest point of the trading day, so the books can be closed against a stable position\",\"It is a legal requirement\",\"The system is faster\"]', '[\"2\"]', 4),
(1529, 5711, 'A caller asks whether a named guest is staying at the hotel. The correct answer is', 'single_choice', 4, '[\"Confirm and put the call through\",\"Neither confirm nor deny that the guest is in house\",\"Confirm but refuse to connect\",\"Give the room number only\"]', '[\"2\"]', 1),
(1530, 5711, 'Under the Saudi Personal Data Protection Law, guest data may be used', 'single_choice', 4, '[\"For any purpose the hotel chooses\",\"Only for the purpose it was collected for, unless the guest consents to more\",\"Freely once the guest has checked out\",\"For marketing by default\"]', '[\"2\"]', 2),
(1531, 5711, 'A printed arrivals list left on the desk is a problem because', 'single_choice', 4, '[\"It wastes paper\",\"It exposes guest names and room numbers to anyone passing\",\"It is out of date quickly\",\"It is not a problem\"]', '[\"2\"]', 3),
(1532, 5711, 'A guest asks what data the hotel holds about them. The correct response is', 'single_choice', 4, '[\"Refuse, it is internal\",\"Follow the hotel\'s data request procedure, which gives the guest a right to know\",\"Read it out from the screen immediately\",\"Tell them no data is held\"]', '[\"2\"]', 4),
(1533, 5712, 'What does a room attendant do before entering a guest room?', 'single_choice', 4, '[\"Enter using the key immediately\",\"Knock, announce \\\"housekeeping\\\", wait, repeat, then enter announcing again\",\"Call the guest from reception\",\"Wait for the guest to leave the floor\"]', '[\"2\"]', 1),
(1534, 5712, 'The housekeeping control desk is responsible for', 'single_choice', 4, '[\"Cooking\",\"Coordinating room status, assignments, keys and guest requests across the floors\",\"Billing guests\",\"Checking guests in\"]', '[\"2\"]', 2),
(1535, 5712, 'A room reported as \"clean\" but not inspected should be', 'single_choice', 4, '[\"Sold immediately\",\"Held until inspected, if the standard requires inspection before release\",\"Reported as out of order\",\"Cleaned again\"]', '[\"2\"]', 3),
(1536, 5712, 'Why is the cleaning sequence fixed rather than left to preference?', 'single_choice', 4, '[\"It is faster to supervise\",\"A fixed order prevents steps being missed and stops clean surfaces being recontaminated\",\"It is not fixed\",\"It saves chemicals\"]', '[\"2\"]', 4),
(1537, 5713, 'In what order should a guest room be cleaned?', 'single_choice', 4, '[\"Bathroom first, then bedroom, then floor\",\"Top to bottom and clean to dirty, finishing with the floor\",\"Floor first\",\"Whatever is quickest\"]', '[\"2\"]', 1),
(1538, 5713, 'Cloths are colour coded so that', 'single_choice', 4, '[\"They look tidy\",\"A cloth used in the toilet is never used on a surface a guest touches\",\"They match the uniform\",\"They are easier to count\"]', '[\"2\"]', 2),
(1539, 5713, 'A guest\'s personal belongings found during cleaning should be', 'single_choice', 4, '[\"Moved to a drawer\",\"Left where they are, tidied around but not handled or moved unnecessarily\",\"Put in lost and found\",\"Photographed\"]', '[\"2\"]', 3),
(1540, 5713, 'A departure room differs from a stayover room mainly because', 'single_choice', 4, '[\"It takes less time\",\"Everything is stripped and replaced, and the room is reset to a sellable standard\",\"Only the bed is made\",\"It needs no inspection\"]', '[\"2\"]', 4),
(1541, 5714, 'Linen should be changed on a stayover', 'single_choice', 4, '[\"Never\",\"According to the hotel standard, and always on request or when soiled\",\"Only at departure\",\"Every third day regardless\"]', '[\"2\"]', 1),
(1542, 5714, 'Stripped linen should be', 'single_choice', 4, '[\"Placed on the floor\",\"Placed directly into the linen bag on the trolley, never on the floor or furniture\",\"Left on the chair\",\"Shaken out in the room\"]', '[\"2\"]', 2),
(1543, 5714, 'Why is bed linen not shaken out in a guest room?', 'single_choice', 4, '[\"It creases\",\"It disperses dust and any contamination into the air the guest will breathe\",\"It takes longer\",\"It is allowed\"]', '[\"2\"]', 3),
(1544, 5714, 'A mattress protector is checked at every departure because', 'single_choice', 4, '[\"It is decorative\",\"A soiled protector means the mattress may be affected and must be dealt with before the room is sold\",\"It is not checked\",\"Guests ask about it\"]', '[\"2\"]', 4),
(1545, 5715, 'Which is cleaned last in a bathroom?', 'single_choice', 4, '[\"The mirror\",\"The toilet\",\"The basin\",\"The shower\"]', '[\"2\"]', 1),
(1546, 5715, 'A cloth used on the toilet may then be used on', 'single_choice', 4, '[\"The basin\",\"The mirror\",\"Nothing else, it is removed from service\",\"The bath\"]', '[\"3\"]', 2),
(1547, 5715, 'Contact time for a disinfectant means', 'single_choice', 4, '[\"How long it takes to apply\",\"The time the surface must stay wet for the product to work\",\"How long the bottle lasts\",\"The drying time\"]', '[\"2\"]', 3),
(1548, 5715, 'Bathroom amenities are replenished', 'single_choice', 4, '[\"Only at departure\",\"To the standard set for the room type, at every service\",\"When the guest asks\",\"Never\"]', '[\"2\"]', 4),
(1549, 5716, 'Room inspection exists to', 'single_choice', 4, '[\"Catch staff out\",\"Confirm the room meets the standard before it is sold, and find what training is needed\",\"Slow the release of rooms\",\"Satisfy the guest\"]', '[\"2\"]', 1),
(1550, 5716, 'An inspector finding a repeated fault across several rooms should', 'single_choice', 4, '[\"Fix it quietly\",\"Record it and raise it as a training or process issue, not just a room issue\",\"Ignore it\",\"Report the attendant\"]', '[\"2\"]', 2),
(1551, 5716, 'A room failing inspection is', 'single_choice', 4, '[\"Sold anyway\",\"Returned for correction and re-inspected before release\",\"Marked out of order\",\"Released with a note\"]', '[\"2\"]', 3),
(1552, 5716, 'Which is checked in an inspection but easily missed in cleaning?', 'single_choice', 4, '[\"The bed\",\"High and low surfaces, behind doors, and the underside of fittings\",\"The floor\",\"The towels\"]', '[\"2\"]', 4),
(1553, 5717, 'An item found in a departed room must be', 'single_choice', 4, '[\"Kept by the finder\",\"Logged with the room, date and finder, and stored securely\",\"Left in the room\",\"Thrown away\"]', '[\"2\"]', 1),
(1554, 5717, 'A guest calls about an item left behind. The correct step is', 'single_choice', 4, '[\"Say nothing was found\",\"Check the log, and arrange return at the guest\'s cost if it is there\",\"Post it immediately without checking\",\"Ask them to return\"]', '[\"2\"]', 2),
(1555, 5717, 'High-value items such as passports and jewellery should be', 'single_choice', 4, '[\"Stored with everything else\",\"Stored in the safe and reported to the duty manager the same day\",\"Returned to the room\",\"Held by the attendant\"]', '[\"2\"]', 3),
(1556, 5717, 'Unclaimed items are disposed of', 'single_choice', 4, '[\"Immediately\",\"After the retention period set by hotel policy, with the disposal recorded\",\"Never\",\"By the finder\"]', '[\"2\"]', 4),
(1557, 5718, 'Clean and soiled linen must be', 'single_choice', 4, '[\"Transported together to save time\",\"Kept separate at every stage, including transport and storage\",\"Stored in the same room\",\"Sorted by the guest\"]', '[\"2\"]', 1),
(1558, 5718, 'Linen stained with blood or bodily fluid is', 'single_choice', 4, '[\"Washed with the normal load\",\"Handled as infectious, bagged separately and washed to the required temperature\",\"Discarded\",\"Soaked in the room\"]', '[\"2\"]', 2),
(1559, 5718, 'Par stock for linen means', 'single_choice', 4, '[\"The cheapest supplier\",\"The quantity needed to keep every bed supplied while other sets are in circulation\",\"The stock in the laundry\",\"One set per bed\"]', '[\"2\"]', 3),
(1560, 5718, 'Overloading a washing machine results in', 'single_choice', 4, '[\"Faster cycles\",\"Linen that is not properly cleaned or rinsed, and more rewashing\",\"Lower cost\",\"No effect\"]', '[\"2\"]', 4),
(1561, 5719, 'A wet floor in a public area requires', 'single_choice', 4, '[\"No action if it is small\",\"A warning sign in place for as long as the floor is wet\",\"Closing the area\",\"Only a verbal warning\"]', '[\"2\"]', 1),
(1562, 5719, 'Public areas are cleaned on a frequency based on', 'single_choice', 4, '[\"Convenience\",\"Traffic and visibility, with high-touch points done most often\",\"Cost\",\"Guest complaints only\"]', '[\"2\"]', 2),
(1563, 5719, 'High-touch points in a lobby include', 'single_choice', 4, '[\"The ceiling\",\"Door handles, lift buttons, handrails and counter edges\",\"The carpet centre\",\"Artwork\"]', '[\"2\"]', 3),
(1564, 5719, 'Cleaning a public area during peak hours should', 'single_choice', 4, '[\"Proceed as normal\",\"Be limited to what can be done without obstructing guests, with the rest rescheduled\",\"Be skipped entirely\",\"Close the area\"]', '[\"2\"]', 4),
(1565, 5720, 'Deep cleaning differs from daily cleaning because it', 'single_choice', 4, '[\"Is faster\",\"Addresses what daily cleaning cannot reach, on a planned cycle\",\"Uses no chemicals\",\"Is done by the front desk\"]', '[\"2\"]', 1),
(1566, 5720, 'A room scheduled for deep cleaning should be', 'single_choice', 4, '[\"Sold as normal\",\"Blocked from sale for the time the work needs\",\"Cleaned around the guest\",\"Left until it is quiet\"]', '[\"2\"]', 2),
(1567, 5720, 'Deep cleaning is planned on a cycle because', 'single_choice', 4, '[\"It is cheaper\",\"Condition declines predictably, and planned work is cheaper than replacement\",\"Guests request it\",\"It is not planned\"]', '[\"2\"]', 3),
(1568, 5720, 'Which is a deep cleaning task rather than a daily one?', 'single_choice', 4, '[\"Making the bed\",\"Shampooing carpet and cleaning behind and under furniture\",\"Emptying the bin\",\"Replacing towels\"]', '[\"2\"]', 4),
(1569, 5721, 'Two cleaning chemicals should never be mixed because', 'single_choice', 4, '[\"It wastes product\",\"Some combinations, such as bleach and acid cleaners, release toxic gas\",\"It changes the colour\",\"It is allowed if diluted\"]', '[\"2\"]', 1),
(1570, 5721, 'Dilution rates are taken from', 'single_choice', 4, '[\"Experience\",\"The manufacturer\'s instructions and the product data sheet\",\"The strongest that works\",\"The supervisor\'s preference\"]', '[\"2\"]', 2),
(1571, 5721, 'A chemical decanted into a second container must be', 'single_choice', 4, '[\"Left unlabelled\",\"Labelled with the product name and its hazards\",\"Marked only with a colour\",\"Used the same day\"]', '[\"2\"]', 3),
(1572, 5721, 'The safety data sheet for a product tells you', 'single_choice', 4, '[\"The price\",\"The hazards, the protective equipment needed and what to do in an exposure\",\"The supplier address only\",\"Nothing useful\"]', '[\"2\"]', 4),
(1573, 5722, 'Room turnaround time is measured from', 'single_choice', 4, '[\"The guest\'s departure to the room being sellable again\",\"Check-in to checkout\",\"The start to the end of a shift\",\"The booking to the arrival\"]', '[\"1\"]', 1),
(1574, 5722, 'The biggest cause of slow turnaround on a busy departure day is usually', 'single_choice', 4, '[\"Slow attendants\",\"Rooms not being reported as vacant promptly, so cleaning starts late\",\"Too much linen\",\"Guests checking out early\"]', '[\"2\"]', 2),
(1575, 5722, 'Priority rooms in the turnaround queue are', 'single_choice', 4, '[\"The nearest to the linen room\",\"Those with a confirmed early arrival or a guest waiting\",\"The largest rooms\",\"The cheapest rooms\"]', '[\"2\"]', 3),
(1576, 5722, 'Rushing a turnaround typically costs the hotel more because', 'single_choice', 4, '[\"It uses more chemicals\",\"A room released below standard generates a complaint, a move and a refund\",\"It does not cost more\",\"Staff work overtime\"]', '[\"2\"]', 4),
(1577, 5723, 'A trolley is stocked before the shift so that', 'single_choice', 4, '[\"It looks tidy\",\"The attendant does not lose time returning to the store mid-room\",\"It is easier to push\",\"The supervisor can check it\"]', '[\"2\"]', 1),
(1578, 5723, 'Productivity in housekeeping is measured against', 'single_choice', 4, '[\"Rooms per hour alone\",\"Rooms cleaned to standard per hour, since a fast room that fails inspection is not done\",\"Chemicals used\",\"Hours worked\"]', '[\"2\"]', 2),
(1579, 5723, 'Which change most reliably improves productivity?', 'single_choice', 4, '[\"Working faster\",\"Removing interruptions and having the right supplies to hand\",\"Shorter breaks\",\"More staff\"]', '[\"2\"]', 3),
(1580, 5723, 'A room attendant consistently over time should first be', 'single_choice', 4, '[\"Disciplined\",\"Observed, to find whether the cause is method, supplies or the rooms assigned\",\"Reassigned\",\"Given fewer rooms\"]', '[\"2\"]', 4),
(1581, 5724, 'From which side is a plated dish normally served?', 'single_choice', 4, '[\"The guest\'s left, and cleared from the right\",\"The guest\'s right always\",\"Whichever is convenient\",\"Over the guest\'s shoulder\"]', '[\"1\"]', 1),
(1582, 5724, 'A guest at the table has not received their dish while others are eating. The server should', 'single_choice', 4, '[\"Say nothing\",\"Acknowledge it at once, check with the kitchen and give the guest a time\",\"Offer a free dessert\",\"Remove the other plates\"]', '[\"2\"]', 2),
(1583, 5724, 'Plates are cleared when', 'single_choice', 4, '[\"The first guest finishes\",\"Everyone at the table has finished\",\"The kitchen asks\",\"After thirty minutes\"]', '[\"2\"]', 3),
(1584, 5724, 'Carrying a tray, the server should', 'single_choice', 4, '[\"Hold it at chest height across the body\",\"Balance it on the flat palm and forearm, away from the body, loaded heaviest in the centre\",\"Carry it with both hands in front\",\"Rest it on the hip\"]', '[\"2\"]', 4),
(1585, 5725, 'A guest arriving without a reservation at a full restaurant should be', 'single_choice', 4, '[\"Turned away\",\"Given a realistic wait time and the option to wait or book another time\",\"Seated at a reserved table\",\"Asked to come back\"]', '[\"2\"]', 1),
(1586, 5725, 'Within how long should an arriving guest be acknowledged?', 'single_choice', 4, '[\"Thirty seconds, even if the host cannot seat them yet\",\"Five minutes\",\"When a table is free\",\"It does not matter\"]', '[\"1\"]', 2),
(1587, 5725, 'Seating a guest includes', 'single_choice', 4, '[\"Pointing to a table\",\"Escorting them, presenting the menu and telling them who will serve them\",\"Nothing more than showing the table\",\"Taking the order\"]', '[\"2\"]', 3),
(1588, 5725, 'A guest with a mobility aid should be seated', 'single_choice', 4, '[\"Wherever is free\",\"Where they can reach the table without obstruction, asked rather than assumed\",\"Near the door always\",\"At the back\"]', '[\"2\"]', 4),
(1589, 5726, 'In American style service, the food is', 'single_choice', 4, '[\"Carved at the table\",\"Plated in the kitchen and brought to the guest\",\"Served from a platter to the guest\'s plate\",\"Placed in the centre to share\"]', '[\"2\"]', 1),
(1590, 5726, 'Silver service differs in that the server', 'single_choice', 4, '[\"Plates in the kitchen\",\"Transfers food from a platter to the guest\'s plate at the table\",\"Leaves the platter with the guest\",\"Does not serve at all\"]', '[\"2\"]', 2),
(1591, 5726, 'Cutlery is laid', 'single_choice', 4, '[\"In any order\",\"From the outside in, in the order the courses will be eaten\",\"All on the right\",\"After the guest sits\"]', '[\"2\"]', 3),
(1592, 5726, 'The cover is checked before service to confirm', 'single_choice', 4, '[\"The bill is ready\",\"Everything is clean, matched, correctly spaced and free of marks\",\"The guest has arrived\",\"The menu is printed\"]', '[\"2\"]', 4),
(1593, 5727, 'Hot food held for service must be kept at or above', 'single_choice', 4, '[\"50°C\",\"60°C\",\"45°C\",\"37°C\"]', '[\"2\"]', 1),
(1594, 5727, 'A server notices a dish has been on the pass for twenty minutes. They should', 'single_choice', 4, '[\"Serve it quickly\",\"Not serve it, and tell the kitchen so it is replaced\",\"Reheat it under the lamp\",\"Serve it with an apology\"]', '[\"2\"]', 2),
(1595, 5727, 'A guest declares a nut allergy. The server must', 'single_choice', 4, '[\"Suggest dishes they think are safe\",\"Inform the kitchen, confirm with them, and not guess about any ingredient\",\"Say all food is safe\",\"Ask the guest to choose carefully\"]', '[\"2\"]', 3),
(1596, 5727, 'Cross-contamination in the service area most often happens through', 'single_choice', 4, '[\"The menu\",\"Hands, cloths and shared utensils moving between raw and ready-to-eat items\",\"The floor\",\"The till\"]', '[\"2\"]', 4),
(1597, 5728, 'HACCP stands for', 'single_choice', 4, '[\"Hotel and Catering Cleaning Procedure\",\"Hazard Analysis and Critical Control Points\",\"Health and Catering Control Plan\",\"Hygiene Assessment of Cooking and Chilling Practice\"]', '[\"2\"]', 1),
(1598, 5728, 'A critical control point is', 'single_choice', 4, '[\"Any step in the process\",\"A step where control is essential to prevent or eliminate a hazard\",\"The final inspection\",\"The delivery point\"]', '[\"2\"]', 2),
(1599, 5728, 'A critical limit is', 'single_choice', 4, '[\"The maximum number of guests\",\"The measurable boundary, such as a temperature, that separates safe from unsafe\",\"The budget\",\"The shelf life\"]', '[\"2\"]', 3),
(1600, 5728, 'When monitoring shows a critical limit has been breached,', 'single_choice', 4, '[\"Note it and continue\",\"Take the corrective action set out in the plan and record what was done\",\"Discard the record\",\"Inform the guest\"]', '[\"2\"]', 4),
(1601, 5729, 'Hands must be washed', 'single_choice', 4, '[\"At the start of the shift only\",\"After any task that could contaminate them, and between handling different foods\",\"Once an hour\",\"Only after the toilet\"]', '[\"2\"]', 1),
(1602, 5729, 'A server with vomiting or diarrhoea must', 'single_choice', 4, '[\"Work with gloves\",\"Report it and stay away from food handling until clear for the required period\",\"Work away from the kitchen\",\"Take medication and continue\"]', '[\"2\"]', 2),
(1603, 5729, 'A cut on the hand must be', 'single_choice', 4, '[\"Left uncovered\",\"Covered with a coloured waterproof dressing, and a glove worn over it\",\"Covered with any plaster\",\"Reason to go home\"]', '[\"2\"]', 3),
(1604, 5729, 'Jewellery is restricted in food areas because', 'single_choice', 4, '[\"It looks unprofessional\",\"It harbours bacteria and can fall into food\",\"It is expensive\",\"It is not restricted\"]', '[\"2\"]', 4),
(1605, 5730, 'Beverages are served', 'single_choice', 4, '[\"Before the guest orders\",\"From the guest\'s right, without reaching across\",\"From the left always\",\"By placing the tray on the table\"]', '[\"2\"]', 1),
(1606, 5730, 'A guest orders an alcoholic drink in a venue that does not serve alcohol. The server should', 'single_choice', 4, '[\"Argue\",\"Explain politely that it is not served and offer the alternatives available\",\"Ignore the request\",\"Send them elsewhere\"]', '[\"2\"]', 2),
(1607, 5730, 'Glassware is handled', 'single_choice', 4, '[\"By the rim\",\"By the stem or the base, never the rim\",\"With a cloth over the top\",\"However is fastest\"]', '[\"2\"]', 3),
(1608, 5730, 'A drink is checked before it leaves the bar for', 'single_choice', 4, '[\"Price\",\"Correct glass, correct garnish, correct level and a clean exterior\",\"Temperature only\",\"Nothing\"]', '[\"2\"]', 4),
(1609, 5731, 'The banquet event order exists to', 'single_choice', 4, '[\"Price the event\",\"Tell every department exactly what is required, when and where\",\"Record complaints\",\"Book the room\"]', '[\"2\"]', 1),
(1610, 5731, 'A last-minute increase in guest numbers should be', 'single_choice', 4, '[\"Refused\",\"Confirmed in writing and communicated to kitchen, service and stewarding at once\",\"Handled on the day\",\"Accepted verbally only\"]', '[\"2\"]', 2),
(1611, 5731, 'In buffet service, food safety depends most on', 'single_choice', 4, '[\"Presentation\",\"Holding temperature and the time food has been on display\",\"The number of dishes\",\"Staff numbers\"]', '[\"2\"]', 3),
(1612, 5731, 'Room set-up should be completed', 'single_choice', 4, '[\"As guests arrive\",\"Before the agreed time, allowing for a final check\",\"Whenever the room is free\",\"By the client\"]', '[\"2\"]', 4),
(1613, 5732, 'An order entered incorrectly into the point of sale should be', 'single_choice', 4, '[\"Left and corrected on the bill\",\"Voided following the authorisation rule, with the reason recorded\",\"Deleted quietly\",\"Ignored if small\"]', '[\"2\"]', 1),
(1614, 5732, 'Voids and discounts are authorised because', 'single_choice', 4, '[\"It slows service\",\"They are the most common route for revenue loss and must be traceable\",\"The system requires it\",\"Guests expect it\"]', '[\"2\"]', 2),
(1615, 5732, 'Splitting a bill should be offered', 'single_choice', 4, '[\"Never\",\"When the table asks, and handled before payment begins\",\"Only for large groups\",\"After payment\"]', '[\"2\"]', 3),
(1616, 5732, 'The till is reconciled at the end of a shift to', 'single_choice', 4, '[\"Count staff\",\"Match takings against recorded sales and find differences while they can still be traced\",\"Set prices\",\"Order stock\"]', '[\"2\"]', 4),
(1617, 5733, 'An effective suggestion at the table is', 'single_choice', 4, '[\"The most expensive item\",\"A specific item that fits what the guest has already chosen\",\"Everything on the menu\",\"A discount\"]', '[\"2\"]', 1),
(1618, 5733, 'Order taking should begin with', 'single_choice', 4, '[\"The nearest guest\",\"A logical order the table can follow, noting seat positions so dishes reach the right person\",\"Whoever speaks first\",\"The host only\"]', '[\"2\"]', 2),
(1619, 5733, 'Repeating the order back to the table', 'single_choice', 4, '[\"Wastes time\",\"Catches errors before they reach the kitchen\",\"Is only for large tables\",\"Is unnecessary with a handheld device\"]', '[\"2\"]', 3),
(1620, 5733, 'Suggesting a dessert works best', 'single_choice', 4, '[\"With the main course order\",\"When the main plates are cleared and the guest is deciding whether to stay\",\"At arrival\",\"With the bill\"]', '[\"2\"]', 4),
(1621, 5734, 'Mise en place means', 'single_choice', 4, '[\"Cleaning down\",\"Everything prepared and in position before service begins\",\"The menu order\",\"The kitchen brigade\"]', '[\"2\"]', 1),
(1622, 5734, 'The brigade system exists to', 'single_choice', 4, '[\"Create hierarchy\",\"Divide the kitchen into sections with clear responsibility so service flows\",\"Reduce staff\",\"Set pay grades\"]', '[\"2\"]', 2),
(1623, 5734, 'A recipe specification is followed exactly because', 'single_choice', 4, '[\"The chef says so\",\"It controls cost, portion and consistency, which the guest and the margin both depend on\",\"It is faster\",\"It is not followed exactly\"]', '[\"2\"]', 3),
(1624, 5734, 'The pass is where', 'single_choice', 4, '[\"Deliveries arrive\",\"Finished dishes are checked before they leave the kitchen\",\"Waste is sorted\",\"Staff eat\"]', '[\"2\"]', 4),
(1625, 5735, 'The temperature danger zone is', 'single_choice', 4, '[\"0°C to 4°C\",\"5°C to 63°C\",\"63°C to 100°C\",\"Below 0°C\"]', '[\"2\"]', 1),
(1626, 5735, 'Cooked food to be cooled must pass through the danger zone', 'single_choice', 4, '[\"Slowly, at room temperature\",\"As quickly as possible, within the time the standard allows\",\"Overnight\",\"It does not matter\"]', '[\"2\"]', 2),
(1627, 5735, 'Raw meat is stored', 'single_choice', 4, '[\"Above ready-to-eat food\",\"Below ready-to-eat food, to prevent drips contaminating it\",\"Anywhere in the fridge\",\"At room temperature\"]', '[\"2\"]', 3),
(1628, 5735, 'Reheated food must reach a core temperature of at least', 'single_choice', 4, '[\"63°C\",\"75°C\",\"50°C\",\"100°C\"]', '[\"2\"]', 4),
(1629, 5736, 'A chef changes their apron', 'single_choice', 4, '[\"Once a week\",\"Whenever it is soiled, and between raw and ready-to-eat work\",\"At the end of the shift\",\"Never\"]', '[\"2\"]', 1),
(1630, 5736, 'Colour-coded boards are used so that', 'single_choice', 4, '[\"They look organised\",\"Raw and ready-to-eat foods never share a preparation surface\",\"They are easier to replace\",\"Chefs can find them\"]', '[\"2\"]', 2),
(1631, 5736, 'Hand contact with ready-to-eat food should be', 'single_choice', 4, '[\"Normal practice\",\"Minimised by using tongs, utensils or single-use gloves\",\"Avoided by washing hands only\",\"Unrestricted with gloves\"]', '[\"2\"]', 3),
(1632, 5736, 'A damaged chopping board must be', 'single_choice', 4, '[\"Cleaned more often\",\"Taken out of service, because cuts and cracks hold bacteria that cannot be cleaned out\",\"Turned over\",\"Sanded down\"]', '[\"2\"]', 4),
(1633, 5737, 'A sharp knife is safer than a blunt one because', 'single_choice', 4, '[\"It cuts less deeply\",\"It needs less force, so it is less likely to slip\",\"It is lighter\",\"It is not safer\"]', '[\"2\"]', 1),
(1634, 5737, 'A knife should be carried', 'single_choice', 4, '[\"Point up\",\"Point down, close to the body, blade turned away\",\"On a tray\",\"In a pocket\"]', '[\"2\"]', 2),
(1635, 5737, 'A falling knife should be', 'single_choice', 4, '[\"Caught\",\"Allowed to fall, with feet moved clear\",\"Kicked aside\",\"Caught by the handle\"]', '[\"2\"]', 3),
(1636, 5737, 'Knives are cleaned', 'single_choice', 4, '[\"In the dishwasher\",\"By hand, immediately, and never left in a sink of water\",\"At the end of service\",\"With the pans\"]', '[\"2\"]', 4),
(1637, 5738, 'FIFO means', 'single_choice', 4, '[\"Fresh In, Frozen Out\",\"First In, First Out, so older stock is used first\",\"Food Inspection For Operations\",\"Fast In, Fast Out\"]', '[\"2\"]', 1),
(1638, 5738, 'Dry goods are stored', 'single_choice', 4, '[\"On the floor\",\"Off the floor on shelving, in sealed containers, away from damp\",\"In the walkway\",\"Next to chemicals\"]', '[\"2\"]', 2),
(1639, 5738, 'An opened product must be', 'single_choice', 4, '[\"Used the same day\",\"Labelled with the date it was opened and its use-by date\",\"Returned to the supplier\",\"Left as delivered\"]', '[\"2\"]', 3),
(1640, 5738, 'Chemicals are stored', 'single_choice', 4, '[\"With the food\",\"In a separate, marked area away from all food\",\"Above the preparation surface\",\"In the fridge\"]', '[\"2\"]', 4),
(1641, 5739, 'A chilled delivery should be checked for temperature', 'single_choice', 4, '[\"After it is put away\",\"On arrival, before it is accepted\",\"The next day\",\"Only if it looks warm\"]', '[\"2\"]', 1),
(1642, 5739, 'A delivery that fails the check should be', 'single_choice', 4, '[\"Accepted and used quickly\",\"Rejected and recorded, with the supplier informed\",\"Accepted and frozen\",\"Accepted at a discount\"]', '[\"2\"]', 2),
(1643, 5739, 'Goods are checked against', 'single_choice', 4, '[\"Memory\",\"The purchase order and the delivery note, for quantity, quality and price\",\"The invoice only\",\"Nothing\"]', '[\"2\"]', 3),
(1644, 5739, 'Damaged packaging matters because', 'single_choice', 4, '[\"It looks poor\",\"The contents may be contaminated and the seal can no longer be relied on\",\"It is harder to store\",\"It does not matter\"]', '[\"2\"]', 4),
(1645, 5740, 'A fridge should run at', 'single_choice', 4, '[\"0°C to 5°C\",\"8°C to 12°C\",\"−18°C\",\"10°C\"]', '[\"1\"]', 1),
(1646, 5740, 'A freezer should run at or below', 'single_choice', 4, '[\"0°C\",\"−18°C\",\"−5°C\",\"4°C\"]', '[\"2\"]', 2),
(1647, 5740, 'Temperature checks are recorded because', 'single_choice', 4, '[\"It is a habit\",\"The record is the evidence that control was maintained, and shows trends before a failure\",\"The supplier asks\",\"They are not recorded\"]', '[\"2\"]', 3),
(1648, 5740, 'A probe thermometer is sanitised', 'single_choice', 4, '[\"Once a day\",\"Before and after every use, and between different foods\",\"Weekly\",\"Never\"]', '[\"2\"]', 4),
(1649, 5741, 'A guest asks whether a dish contains sesame. The correct response is', 'single_choice', 4, '[\"Say you think not\",\"Check the recipe specification and allergen record, and answer from that\",\"Say all dishes are safe\",\"Suggest they avoid it\"]', '[\"2\"]', 1),
(1650, 5741, 'The safest way to prepare an allergen-free dish is', 'single_choice', 4, '[\"Remove the ingredient at the end\",\"Prepare it separately with clean equipment and clean hands\",\"Cook it hotter\",\"Serve it first\"]', '[\"2\"]', 2),
(1651, 5741, 'Allergen information must be', 'single_choice', 4, '[\"Given only if asked\",\"Available and accurate for every dish served\",\"Kept in the office\",\"Estimated\"]', '[\"2\"]', 3),
(1652, 5741, 'A recipe change affecting allergens must be', 'single_choice', 4, '[\"Made quietly\",\"Recorded and communicated to service before the dish is sold\",\"Made only by the head chef\",\"Tested on staff first\"]', '[\"2\"]', 4),
(1653, 5742, 'Food waste is separated because', 'single_choice', 4, '[\"It is required by the landlord\",\"It can be measured and reduced, and it must be disposed of correctly\",\"It smells\",\"It is not separated\"]', '[\"2\"]', 1),
(1654, 5742, 'The largest avoidable source of kitchen waste is usually', 'single_choice', 4, '[\"Trimmings\",\"Over-production and spoilage from poor stock rotation\",\"Packaging\",\"Guest plates\"]', '[\"2\"]', 2),
(1655, 5742, 'Waste oil must be', 'single_choice', 4, '[\"Poured down the drain\",\"Collected and removed by an approved contractor\",\"Mixed with food waste\",\"Reused indefinitely\"]', '[\"2\"]', 3),
(1656, 5742, 'Recording waste is useful because', 'single_choice', 4, '[\"It satisfies the auditor\",\"It shows where product and money are actually being lost, so it can be fixed\",\"It is not useful\",\"It reduces cost directly\"]', '[\"2\"]', 4),
(1657, 5743, 'A cleaning schedule sets out', 'single_choice', 4, '[\"Who is on shift\",\"What is cleaned, how, how often, with what, and by whom\",\"The menu\",\"Delivery times\"]', '[\"2\"]', 1),
(1658, 5743, 'Clean as you go matters because', 'single_choice', 4, '[\"It looks better\",\"It stops contamination building up and keeps the workspace safe during service\",\"It saves chemicals\",\"It is not required\"]', '[\"2\"]', 2),
(1659, 5743, 'Equipment is dismantled for cleaning when', 'single_choice', 4, '[\"It is broken\",\"The manufacturer\'s instructions require it to reach food contact surfaces\",\"Once a year\",\"Never\"]', '[\"2\"]', 3),
(1660, 5743, 'Cleaning is signed off so that', 'single_choice', 4, '[\"Staff can be blamed\",\"There is a record that the task was done, by whom and when\",\"It takes longer\",\"The schedule is met\"]', '[\"2\"]', 4),
(1661, 5744, 'Engineering\'s main contribution to revenue is', 'single_choice', 4, '[\"Reducing the electricity bill\",\"Keeping rooms sellable, because an out-of-order room earns nothing\",\"Buying equipment cheaply\",\"Staffing levels\"]', '[\"2\"]', 1),
(1662, 5744, 'A fault reported by housekeeping should be', 'single_choice', 4, '[\"Fixed when convenient\",\"Logged as a work order, prioritised and tracked to completion\",\"Reported to the guest\",\"Fixed without record\"]', '[\"2\"]', 2),
(1663, 5744, 'Planned maintenance is preferred to reactive repair because', 'single_choice', 4, '[\"It is more interesting\",\"It is cheaper, and it fails at a time you choose rather than during a full house\",\"It uses fewer parts\",\"It is required by law\"]', '[\"2\"]', 3),
(1664, 5744, 'Which record tells you whether a recurring fault is really fixed?', 'single_choice', 4, '[\"The invoice\",\"The work order history for that asset\",\"The guest comment\",\"The duty log\"]', '[\"2\"]', 4),
(1665, 5745, 'Preventive maintenance is scheduled by', 'single_choice', 4, '[\"When something breaks\",\"Time or usage intervals set for each asset\",\"Guest complaints\",\"Budget availability\"]', '[\"2\"]', 1),
(1666, 5745, 'The cost of preventive maintenance is justified by', 'single_choice', 4, '[\"Longer asset life and fewer out-of-order rooms\",\"A lower headcount\",\"Cheaper parts\",\"Insurance discounts\"]', '[\"1\"]', 2),
(1667, 5745, 'A preventive task that is repeatedly skipped should be', 'single_choice', 4, '[\"Removed from the schedule\",\"Investigated, since either the interval is wrong or the resource is not there\",\"Done twice next time\",\"Ignored\"]', '[\"2\"]', 3),
(1668, 5745, 'Asset history is kept so that', 'single_choice', 4, '[\"The auditor is satisfied\",\"Replace-or-repair decisions are made on evidence rather than impression\",\"Staff can be assessed\",\"Warranty is valid\"]', '[\"2\"]', 4),
(1669, 5746, 'A guest reports the room will not cool. The first check is', 'single_choice', 4, '[\"Replace the unit\",\"The set point, the filter and whether a window or balcony door is open\",\"The chiller plant\",\"The thermostat wiring\"]', '[\"2\"]', 1),
(1670, 5746, 'Dirty air filters cause', 'single_choice', 4, '[\"Better filtration\",\"Reduced airflow, higher energy use and poorer cooling\",\"No change\",\"Lower running cost\"]', '[\"2\"]', 2),
(1671, 5746, 'Legionella risk in a building system is managed mainly by', 'single_choice', 4, '[\"Cleaning the ducts\",\"Controlling water temperature and avoiding stagnation\",\"Changing filters\",\"Running the system harder\"]', '[\"2\"]', 3),
(1672, 5746, 'Condensate drains are checked because', 'single_choice', 4, '[\"They are noisy\",\"A blocked drain causes water damage to ceilings and rooms below\",\"They affect temperature\",\"They do not need checking\"]', '[\"2\"]', 4),
(1673, 5747, 'Work on live electrical equipment is', 'single_choice', 4, '[\"Normal for small jobs\",\"Done only by a competent person, with the circuit isolated wherever possible\",\"Allowed with gloves\",\"Done by any technician\"]', '[\"2\"]', 1),
(1674, 5747, 'Lock-out tag-out exists to', 'single_choice', 4, '[\"Record who did the work\",\"Make sure isolated equipment cannot be re-energised while someone is working on it\",\"Prevent theft\",\"Satisfy the insurer\"]', '[\"2\"]', 2),
(1675, 5747, 'A damaged power cable in a guest room should be', 'single_choice', 4, '[\"Taped up\",\"Taken out of service immediately and the item replaced or repaired\",\"Left if it still works\",\"Reported next week\"]', '[\"2\"]', 3),
(1676, 5747, 'Portable appliance testing is done to', 'single_choice', 4, '[\"Extend warranty\",\"Confirm equipment is still electrically safe to use, on a set frequency\",\"Increase efficiency\",\"Track assets\"]', '[\"2\"]', 4),
(1677, 5748, 'The first action on a burst pipe in an occupied floor is', 'single_choice', 4, '[\"Call a contractor\",\"Isolate the water supply to that section\",\"Mop the floor\",\"Move the guest\"]', '[\"2\"]', 1),
(1678, 5748, 'A slow draining shower is most often caused by', 'single_choice', 4, '[\"Low water pressure\",\"A blockage of hair and soap in the trap\",\"A faulty valve\",\"Air in the system\"]', '[\"2\"]', 2),
(1679, 5748, 'Backflow prevention protects', 'single_choice', 4, '[\"The drains\",\"The drinking water supply from contamination\",\"The boiler\",\"The pump\"]', '[\"2\"]', 3),
(1680, 5748, 'Hot water delivered to a guest outlet must be', 'single_choice', 4, '[\"As hot as the system allows\",\"Controlled to prevent scalding, while stored hot enough to control bacteria\",\"Below 40°C in storage\",\"Unregulated\"]', '[\"2\"]', 4),
(1681, 5749, 'On discovering a fire, the first action is', 'single_choice', 4, '[\"Fight the fire\",\"Raise the alarm\",\"Open windows to clear smoke\",\"Find the fire marshal\"]', '[\"2\"]', 1),
(1682, 5749, 'A fire door must never be', 'single_choice', 4, '[\"Closed\",\"Wedged or propped open\",\"Signed\",\"Painted\"]', '[\"2\"]', 2),
(1683, 5749, 'A CO2 extinguisher is used on', 'single_choice', 4, '[\"Cooking oil fires\",\"Electrical fires\",\"Paper and wood\",\"Metal fires\"]', '[\"2\"]', 3),
(1684, 5749, 'The assembly point is where', 'single_choice', 4, '[\"Staff wait for instructions to return\",\"Everyone is accounted for after evacuation\",\"The fire panel is\",\"Guests collect belongings\"]', '[\"2\"]', 4),
(1685, 5750, 'A work order should record', 'single_choice', 4, '[\"Only the fault\",\"The asset, the fault, the priority, who did what and when it was closed\",\"The cost only\",\"The reporter\'s name\"]', '[\"2\"]', 1),
(1686, 5750, 'Priority on a work order is set by', 'single_choice', 4, '[\"Who reported it\",\"Impact on guest safety and on sellable rooms\",\"Ease of repair\",\"Age of the asset\"]', '[\"2\"]', 2),
(1687, 5750, 'A work order is closed when', 'single_choice', 4, '[\"The technician leaves\",\"The fault is fixed and verified, with the work recorded\",\"The part is ordered\",\"The shift ends\"]', '[\"2\"]', 3),
(1688, 5750, 'Open work orders are reviewed daily because', 'single_choice', 4, '[\"It fills the morning meeting\",\"Ageing jobs are the ones that become guest complaints and out-of-order rooms\",\"The system requires it\",\"They are not reviewed\"]', '[\"2\"]', 4),
(1689, 5751, 'An asset inspection checks', 'single_choice', 4, '[\"Only whether it runs\",\"Condition, safety, performance against its standard and what needs planning\",\"The purchase price\",\"The warranty\"]', '[\"2\"]', 1);
INSERT INTO `question` (`id`, `quiz_id`, `title`, `type`, `number_of_options`, `options`, `correct_answers`, `order`) VALUES
(1690, 5751, 'A defect found during inspection is', 'single_choice', 4, '[\"Fixed on the spot if possible, otherwise raised as a work order\",\"Noted for the annual review\",\"Reported verbally\",\"Ignored if minor\"]', '[\"1\"]', 2),
(1691, 5751, 'Inspection frequency is based on', 'single_choice', 4, '[\"Convenience\",\"Criticality, usage and manufacturer guidance\",\"Age alone\",\"Budget\"]', '[\"2\"]', 3),
(1692, 5751, 'Photographs on an inspection record help because', 'single_choice', 4, '[\"They look professional\",\"They show condition at a point in time, which makes deterioration visible\",\"They are required\",\"They speed up the inspection\"]', '[\"2\"]', 4),
(1693, 5752, 'In a power failure, the first priority is', 'single_choice', 4, '[\"Restoring the lifts\",\"Life safety systems and emergency lighting, and accounting for anyone trapped\",\"Restarting the kitchen\",\"Informing guests\"]', '[\"2\"]', 1),
(1694, 5752, 'A guest trapped in a lift should be', 'single_choice', 4, '[\"Told to wait quietly\",\"Kept in contact and reassured while trained release is arranged\",\"Released by any available staff member\",\"Left until the engineer arrives\"]', '[\"2\"]', 2),
(1695, 5752, 'Emergency contact lists are checked regularly because', 'single_choice', 4, '[\"Staff change and an out-of-date number costs time in the one moment it matters\",\"It is an audit point\",\"The list is long\",\"They are not checked\"]', '[\"1\"]', 3),
(1696, 5752, 'After any emergency, the hotel should', 'single_choice', 4, '[\"Return to normal quietly\",\"Review what happened, record it and change what did not work\",\"Report only if a guest was hurt\",\"Wait for the insurer\"]', '[\"2\"]', 4),
(1697, 5753, 'A hotel general manager\'s first responsibility is', 'single_choice', 4, '[\"Occupancy\",\"The safety of guests and staff\",\"Profit\",\"Guest satisfaction scores\"]', '[\"2\"]', 1),
(1698, 5753, 'Departments conflict most often over', 'single_choice', 4, '[\"Budget alone\",\"Room readiness, where housekeeping, engineering and front office share one deadline\",\"Staffing\",\"Menus\"]', '[\"2\"]', 2),
(1699, 5753, 'A daily operations meeting exists to', 'single_choice', 4, '[\"Review the previous year\",\"Align departments on today\'s arrivals, events, issues and constraints\",\"Set strategy\",\"Discuss payroll\"]', '[\"2\"]', 3),
(1700, 5753, 'Standard operating procedures matter most when', 'single_choice', 4, '[\"The hotel is quiet\",\"The hotel is busy or short staffed, and judgement alone will not hold the standard\",\"An auditor visits\",\"New staff join\"]', '[\"2\"]', 4),
(1701, 5754, 'A supervisor who only corrects mistakes will usually', 'single_choice', 4, '[\"Raise standards fastest\",\"Lose the team\'s willingness to raise problems early\",\"Be respected\",\"Reduce turnover\"]', '[\"2\"]', 1),
(1702, 5754, 'Delegation means', 'single_choice', 4, '[\"Giving away the difficult work\",\"Assigning responsibility with the authority and information to carry it out\",\"Avoiding accountability\",\"Reducing your workload\"]', '[\"2\"]', 2),
(1703, 5754, 'Feedback is most effective when it is', 'single_choice', 4, '[\"Given in the annual review\",\"Specific, timely and about the work rather than the person\",\"Given publicly\",\"Written only\"]', '[\"2\"]', 3),
(1704, 5754, 'High turnover in a hospitality team is most often driven by', 'single_choice', 4, '[\"Pay alone\",\"The immediate supervisor and the daily working conditions\",\"Guest behaviour\",\"Shift length\"]', '[\"2\"]', 4),
(1705, 5755, 'A rota should be built around', 'single_choice', 4, '[\"Staff preference alone\",\"Forecast demand, with skill mix covered on every shift\",\"Equal hours for everyone\",\"Seniority\"]', '[\"2\"]', 1),
(1706, 5755, 'A new starter\'s first week should include', 'single_choice', 4, '[\"Full independent shifts\",\"Safety, the standards they will be held to, and supervised practice\",\"Only paperwork\",\"Whatever the shift allows\"]', '[\"2\"]', 2),
(1707, 5755, 'Performance problems should be addressed', 'single_choice', 4, '[\"At the annual review\",\"Early and directly, with clear expectations and support\",\"By reassignment\",\"By the HR department only\"]', '[\"2\"]', 3),
(1708, 5755, 'Cross-training helps the operation because', 'single_choice', 4, '[\"It reduces pay\",\"It covers absence and peaks without adding headcount\",\"It simplifies the rota\",\"It reduces training cost\"]', '[\"2\"]', 4),
(1709, 5756, 'In the uniform system of accounts, departmental profit is', 'single_choice', 4, '[\"Revenue less all hotel costs\",\"Departmental revenue less the direct costs of that department\",\"Revenue less payroll\",\"Gross operating profit\"]', '[\"2\"]', 1),
(1710, 5756, 'A flow-through analysis shows', 'single_choice', 4, '[\"Cash movement\",\"How much of a change in revenue reaches profit\",\"Guest numbers\",\"Debt cover\"]', '[\"2\"]', 2),
(1711, 5756, 'Fixed costs in a hotel', 'single_choice', 4, '[\"Vary with occupancy\",\"Continue whether or not rooms are sold\",\"Are only payroll\",\"Are avoidable\"]', '[\"2\"]', 3),
(1712, 5756, 'A budget variance should be explained by', 'single_choice', 4, '[\"The finance team alone\",\"The department head who owns the line, with the reason and the action\",\"The auditor\",\"Nobody, if it is small\"]', '[\"2\"]', 4),
(1713, 5757, 'Revenue management is the practice of selling', 'single_choice', 4, '[\"The most rooms possible\",\"The right room to the right guest at the right time and price\",\"Rooms at the highest rate\",\"Through the most channels\"]', '[\"2\"]', 1),
(1714, 5757, 'Displacement analysis asks', 'single_choice', 4, '[\"How many guests moved rooms\",\"Whether accepting a group displaces higher-value transient business\",\"Which channel performed best\",\"How many cancelled\"]', '[\"2\"]', 2),
(1715, 5757, 'A rate parity failure means', 'single_choice', 4, '[\"Rates differ between room types\",\"The same room is offered at different rates across channels, undermining direct sales\",\"The rate is too low\",\"Rates changed overnight\"]', '[\"2\"]', 3),
(1716, 5757, 'Forecasting accuracy matters most because', 'single_choice', 4, '[\"It satisfies the owner\",\"Staffing, purchasing and pricing decisions are all made from it\",\"It sets the budget\",\"It is reported weekly\"]', '[\"2\"]', 4),
(1717, 5758, 'Cost control means', 'single_choice', 4, '[\"Spending less on everything\",\"Spending to a standard, and finding where spend does not produce value\",\"Cutting payroll\",\"Buying the cheapest option\"]', '[\"2\"]', 1),
(1718, 5758, 'Payroll is best controlled by', 'single_choice', 4, '[\"Cutting hours across the board\",\"Matching rostered hours to forecast demand\",\"Reducing pay rates\",\"Using agency staff\"]', '[\"2\"]', 2),
(1719, 5758, 'Purchasing through agreed suppliers helps because', 'single_choice', 4, '[\"It is faster\",\"It fixes specification and price, which makes variance visible\",\"It reduces paperwork\",\"It is required\"]', '[\"2\"]', 3),
(1720, 5758, 'A stock take that is consistently over should prompt', 'single_choice', 4, '[\"A change of supplier\",\"A check of recording, portioning and waste before assuming theft\",\"Reduced ordering\",\"No action\"]', '[\"2\"]', 4),
(1721, 5759, 'The guest experience is shaped most by', 'single_choice', 4, '[\"The building\",\"The moments where something goes wrong and how they are handled\",\"The rate\",\"The location\"]', '[\"2\"]', 1),
(1722, 5759, 'Service recovery done well often results in', 'single_choice', 4, '[\"A worse impression than if nothing had gone wrong\",\"Loyalty higher than if nothing had gone wrong\",\"No change\",\"A refund request\"]', '[\"2\"]', 2),
(1723, 5759, 'Guest feedback is most useful when', 'single_choice', 4, '[\"It is positive\",\"It is specific enough to act on and is routed to the team who can act\",\"It is anonymous\",\"It is public\"]', '[\"2\"]', 3),
(1724, 5759, 'A guest journey map is used to', 'single_choice', 4, '[\"Plan the building layout\",\"Find the points where the guest\'s experience is decided, and design those\",\"Track room moves\",\"Schedule staff\"]', '[\"2\"]', 4),
(1725, 5760, 'A quality standard is useful only if', 'single_choice', 4, '[\"It is written down\",\"It is measurable, and someone actually checks against it\",\"It is ambitious\",\"It matches competitors\"]', '[\"2\"]', 1),
(1726, 5760, 'Root cause analysis asks', 'single_choice', 4, '[\"Who was responsible\",\"Why the failure was possible, repeatedly, until the underlying cause is reached\",\"How much it cost\",\"When it happened\"]', '[\"2\"]', 2),
(1727, 5760, 'A mystery guest audit is most valuable when', 'single_choice', 4, '[\"The score is high\",\"The findings are acted on and re-checked\",\"It is announced\",\"It is frequent\"]', '[\"2\"]', 3),
(1728, 5760, 'Recurring complaints about the same issue indicate', 'single_choice', 4, '[\"Difficult guests\",\"A process problem rather than an individual one\",\"Bad luck\",\"A training need only\"]', '[\"2\"]', 4),
(1729, 5761, 'The first minutes of a crisis should be spent', 'single_choice', 4, '[\"Drafting a statement\",\"Making people safe and establishing who is in charge\",\"Informing the owner\",\"Investigating the cause\"]', '[\"2\"]', 1),
(1730, 5761, 'A single spokesperson is nominated so that', 'single_choice', 4, '[\"Others can avoid responsibility\",\"The hotel speaks with one accurate voice\",\"It is faster\",\"It is legally required\"]', '[\"2\"]', 2),
(1731, 5761, 'A crisis plan is tested because', 'single_choice', 4, '[\"Regulators require it\",\"An untested plan fails at the point of use, and the gaps are only visible in rehearsal\",\"It reassures staff\",\"It is cheap\"]', '[\"2\"]', 3),
(1732, 5761, 'After a crisis, guests and staff should receive', 'single_choice', 4, '[\"No further contact\",\"Follow-up and, where needed, support, since the effect outlasts the event\",\"A discount\",\"A survey\"]', '[\"2\"]', 4),
(1733, 5762, 'RevPAR is', 'single_choice', 4, '[\"Revenue per available room\",\"Revenue per arriving reservation\",\"Rate per available room\",\"Rooms per available rate\"]', '[\"1\"]', 1),
(1734, 5762, 'ADR measures', 'single_choice', 4, '[\"Total revenue divided by rooms available\",\"Room revenue divided by rooms sold\",\"Occupancy times rate\",\"Revenue per guest\"]', '[\"2\"]', 2),
(1735, 5762, 'A hotel with high occupancy and falling RevPAR is likely', 'single_choice', 4, '[\"Performing well\",\"Discounting too heavily to fill rooms\",\"Losing market share\",\"Understaffed\"]', '[\"2\"]', 3),
(1736, 5762, 'GOPPAR is more useful than RevPAR because it', 'single_choice', 4, '[\"Is easier to calculate\",\"Accounts for the cost of earning the revenue, not just the revenue\",\"Excludes departments\",\"Is reported daily\"]', '[\"2\"]', 4),
(1737, 5763, 'A property management system holds', 'single_choice', 4, '[\"Only room rates\",\"Reservations, guest profiles, room status, folios and the night audit\",\"Only housekeeping schedules\",\"Only the booking engine\"]', '[\"2\"]', 1),
(1738, 5763, 'Room status in the PMS should be updated by housekeeping because', 'single_choice', 4, '[\"The front desk cannot sell a room it believes is dirty\",\"It is a legal requirement\",\"It changes the rate\",\"It is not updated\"]', '[\"1\"]', 2),
(1739, 5763, 'A guest profile merged in error causes', 'single_choice', 4, '[\"No problem\",\"Charges and preferences attached to the wrong person, which is both a service and a data protection failure\",\"Faster check-in\",\"A rate change\"]', '[\"2\"]', 3),
(1740, 5763, 'Before overriding a PMS rate, an agent should', 'single_choice', 4, '[\"Override freely\",\"Follow the authorisation rule, because rate overrides are auditable\",\"Ask the guest\",\"Change it back afterwards\"]', '[\"2\"]', 4),
(1741, 5764, 'A channel manager exists to', 'single_choice', 4, '[\"Choose which OTAs to use\",\"Keep rates and availability consistent across every connected channel\",\"Negotiate commission\",\"Handle guest messages\"]', '[\"2\"]', 1),
(1742, 5764, 'Overbooking most often results from', 'single_choice', 4, '[\"Guest error\",\"Inventory not syncing between channels in time\",\"Rate changes\",\"Cancellations\"]', '[\"2\"]', 2),
(1743, 5764, 'Channel mix should be reviewed because', 'single_choice', 4, '[\"Contracts expire\",\"Each channel has a different cost of acquisition, and the mix decides net revenue\",\"OTAs require it\",\"It changes rarely\"]', '[\"2\"]', 3),
(1744, 5764, 'Closing a channel at short notice risks', 'single_choice', 4, '[\"Nothing\",\"Penalties and loss of ranking, so it is a planned decision rather than a reaction\",\"Lower rates\",\"Higher commission\"]', '[\"2\"]', 4),
(1745, 5765, 'The booking engine\'s main commercial purpose is', 'single_choice', 4, '[\"Displaying photographs\",\"Converting a visitor into a direct booking without commission\",\"Managing inventory\",\"Collecting reviews\"]', '[\"2\"]', 1),
(1746, 5765, 'The most common cause of booking abandonment is', 'single_choice', 4, '[\"Room photographs\",\"Unexpected cost or friction appearing late in the flow\",\"Too few room types\",\"Slow email\"]', '[\"2\"]', 2),
(1747, 5765, 'Mobile conversion matters because', 'single_choice', 4, '[\"It is fashionable\",\"A large share of hotel searches happen on a phone, and a poor mobile flow loses them\",\"Desktop is declining\",\"It affects SEO only\"]', '[\"2\"]', 3),
(1748, 5765, 'Rate parity with OTAs should be maintained so that', 'single_choice', 4, '[\"OTAs rank the hotel higher\",\"The direct channel is never more expensive than the commissioned one\",\"The rate is simple\",\"It is legally required everywhere\"]', '[\"2\"]', 4),
(1749, 5766, 'The strongest reason a guest books direct is usually', 'single_choice', 4, '[\"Loyalty points\",\"Confidence that the direct channel gives the best price and terms\",\"Website design\",\"Email offers\"]', '[\"2\"]', 1),
(1750, 5766, 'A direct booking strategy should begin with', 'single_choice', 4, '[\"Discounting below the OTA rate\",\"Making the direct channel at least as good, then making that visible\",\"Closing OTA channels\",\"Paid search only\"]', '[\"2\"]', 2),
(1751, 5766, 'Undercutting OTA rates publicly usually', 'single_choice', 4, '[\"Increases direct share safely\",\"Breaches parity agreements and can cost ranking or the contract\",\"Has no downside\",\"Is the standard approach\"]', '[\"2\"]', 3),
(1752, 5766, 'Direct booking value is measured by', 'single_choice', 4, '[\"Volume alone\",\"Net revenue after acquisition cost, compared with the same booking through an OTA\",\"Conversion rate\",\"Page views\"]', '[\"2\"]', 4),
(1753, 5767, 'OTA commission is best understood as', 'single_choice', 4, '[\"A marketing cost with a measurable return\",\"An unavoidable tax\",\"A fixed fee\",\"A discount to the guest\"]', '[\"1\"]', 1),
(1754, 5767, 'Content on an OTA listing should be', 'single_choice', 4, '[\"Minimal\",\"Complete and accurate, because it drives both ranking and guest expectation\",\"Copied from competitors\",\"Updated annually\"]', '[\"2\"]', 2),
(1755, 5767, 'A poor OTA review should be', 'single_choice', 4, '[\"Ignored\",\"Answered publicly, factually and without argument\",\"Disputed with the OTA\",\"Removed\"]', '[\"2\"]', 3),
(1756, 5767, 'The billboard effect describes', 'single_choice', 4, '[\"OTA advertising spend\",\"Guests finding a hotel on an OTA and then booking direct\",\"Roadside signage\",\"Rate parity\"]', '[\"2\"]', 4),
(1757, 5768, 'A useful metric is one that', 'single_choice', 4, '[\"Is easy to collect\",\"Changes a decision\",\"Looks good in a report\",\"Is tracked by competitors\"]', '[\"2\"]', 1),
(1758, 5768, 'Comparing this month to last month alone is misleading because', 'single_choice', 4, '[\"Months differ in length\",\"Hotel demand is seasonal, so the right comparison is the same period last year\",\"The data is late\",\"It is not misleading\"]', '[\"2\"]', 2),
(1759, 5768, 'Pace reporting shows', 'single_choice', 4, '[\"How fast the website loads\",\"How bookings for a future date are building compared with the same point last year\",\"Staff productivity\",\"Channel cost\"]', '[\"2\"]', 3),
(1760, 5768, 'A dashboard with fifty metrics usually', 'single_choice', 4, '[\"Gives the fullest picture\",\"Hides the few numbers that actually drive action\",\"Is best practice\",\"Is easier to read\"]', '[\"2\"]', 4),
(1761, 5769, 'Hotel marketing spend should be judged on', 'single_choice', 4, '[\"Impressions\",\"Revenue generated against cost, by channel\",\"Follower growth\",\"Click volume\"]', '[\"2\"]', 1),
(1762, 5769, 'The most valuable owned channel for a hotel is usually', 'single_choice', 4, '[\"Social media\",\"The guest email list, because it is direct and costs nothing per send\",\"Paid search\",\"Display advertising\"]', '[\"2\"]', 2),
(1763, 5769, 'Photography matters commercially because', 'single_choice', 4, '[\"It fills the website\",\"It is the single biggest driver of whether a listing converts\",\"It is cheap\",\"It supports SEO\"]', '[\"2\"]', 3),
(1764, 5769, 'Marketing to past guests works because', 'single_choice', 4, '[\"They are easy to reach\",\"They convert at a far higher rate and cost less to reach than new prospects\",\"They expect discounts\",\"It is required\"]', '[\"2\"]', 4),
(1765, 5770, 'For a hotel, the highest-value organic search terms are usually', 'single_choice', 4, '[\"Generic terms like \\\"hotel\\\"\",\"Location plus intent, such as \\\"hotel near Riyadh airport\\\"\",\"Brand terms only\",\"Competitor names\"]', '[\"2\"]', 1),
(1766, 5770, 'A Google Business Profile matters because', 'single_choice', 4, '[\"It replaces the website\",\"It is often the first and sometimes only result a local searcher sees\",\"It improves rankings directly\",\"It is required\"]', '[\"2\"]', 2),
(1767, 5770, 'Duplicate descriptions copied from an OTA harm the site because', 'single_choice', 4, '[\"The OTA objects\",\"Search engines have no reason to rank a page that adds nothing new\",\"They are too long\",\"They do not harm it\"]', '[\"2\"]', 3),
(1768, 5770, 'Page speed affects hotel SEO mainly through', 'single_choice', 4, '[\"Keyword ranking alone\",\"Users abandoning a slow page, which search engines observe\",\"Image quality\",\"Server cost\"]', '[\"2\"]', 4),
(1769, 5771, 'The most important thing to do with a negative review is', 'single_choice', 4, '[\"Dispute it\",\"Respond factually, and fix the cause if it is real\",\"Ignore it\",\"Ask for its removal\"]', '[\"2\"]', 1),
(1770, 5771, 'Review volume matters alongside score because', 'single_choice', 4, '[\"It affects commission\",\"A high score on very few reviews is not yet evidence\",\"It improves rate\",\"It does not matter\"]', '[\"2\"]', 2),
(1771, 5771, 'Asking every guest for a review is', 'single_choice', 4, '[\"Against policy everywhere\",\"Reasonable, provided it is not selective about who is asked\",\"Only for happy guests\",\"Ineffective\"]', '[\"2\"]', 3),
(1772, 5771, 'A pattern in reviews is more useful than any single review because', 'single_choice', 4, '[\"It is easier to read\",\"It points at a process that is repeatedly failing\",\"It is more recent\",\"It affects ranking more\"]', '[\"2\"]', 4),
(1773, 5772, 'When choosing hotel technology, integration matters because', 'single_choice', 4, '[\"It reduces licence cost\",\"Systems that cannot exchange data create manual work and errors\",\"It is a vendor requirement\",\"It speeds up training\"]', '[\"2\"]', 1),
(1774, 5772, 'Guest data held in a hotel system must be', 'single_choice', 4, '[\"Shared freely with partners\",\"Protected, with access limited to those who need it for their work\",\"Deleted monthly\",\"Stored locally only\"]', '[\"2\"]', 2),
(1775, 5772, 'The main risk in replacing a core system is', 'single_choice', 4, '[\"Cost\",\"Data migration and the period where staff know neither system well\",\"Vendor support\",\"Hardware\"]', '[\"2\"]', 3),
(1776, 5772, 'A technology decision should be led by', 'single_choice', 4, '[\"The IT supplier\",\"The operational problem it is meant to solve\",\"The lowest price\",\"What competitors use\"]', '[\"2\"]', 4),
(1777, 6439, 'A guest arrives at 11:00 and the room is not ready. What does the agent do first?', 'single_choice', 4, '[\"Tell the guest to come back at check-in time\",\"Acknowledge it, offer luggage storage and give a specific time the room will be ready\",\"Upgrade the guest to a suite at no charge\",\"Check the guest in anyway and let them wait in the corridor\"]', '[\"2\"]', 1),
(1778, 6439, 'What does the front office hand over at shift change?', 'single_choice', 4, '[\"Only the cash float\",\"Pending arrivals, guest requests still open, out-of-order rooms and anything unresolved\",\"Nothing, the system holds all of it\",\"Only complaints\"]', '[\"2\"]', 2),
(1779, 6439, 'Which department does the front desk depend on most to sell a clean room?', 'single_choice', 4, '[\"Engineering\",\"Housekeeping\",\"Finance\",\"Sales\"]', '[\"2\"]', 3),
(1780, 6439, 'A guest asks a question the agent cannot answer. The correct response is to', 'single_choice', 4, '[\"Guess, so the guest is not kept waiting\",\"Say it is not your department\",\"Say you will find out, give a time, and come back with the answer\",\"Refer them to the website\"]', '[\"3\"]', 4),
(1781, 6440, 'A walk-in guest arrives when the hotel is full. The agent should', 'single_choice', 4, '[\"Turn them away\",\"Check for cancellations, then help them find a room nearby if there is genuinely nothing\",\"Put them in an out-of-order room\",\"Ask them to wait indefinitely\"]', '[\"2\"]', 1),
(1782, 6440, 'The arrivals list is checked at the start of a shift to', 'single_choice', 4, '[\"Count staff\",\"Know who is coming, what they have asked for and which rooms are committed\",\"Set room rates\",\"Order breakfast\"]', '[\"2\"]', 2),
(1783, 6440, 'A reservation taken by phone must be read back because', 'single_choice', 4, '[\"It is polite\",\"It catches errors in dates, room type and spelling before they become a problem at arrival\",\"The system requires it\",\"It is not read back\"]', '[\"2\"]', 3),
(1784, 6440, 'Which of these is a front desk responsibility at every shift?', 'single_choice', 4, '[\"Counting and signing for the cash float\",\"Cleaning guest rooms\",\"Cooking breakfast\",\"Fixing air conditioning\"]', '[\"1\"]', 4),
(1785, 6441, 'What must be verified before a room key is issued?', 'single_choice', 4, '[\"The guest\'s identity against the reservation\",\"The guest\'s social media\",\"Nothing, the booking is enough\",\"Only the payment card\"]', '[\"1\"]', 1),
(1786, 6441, 'A guest booked a twin room and arrives expecting a double. What is the correct step?', 'single_choice', 4, '[\"Insist the booking is correct and move on\",\"Check availability for a double, explain the options and confirm before moving them\",\"Move them without telling them\",\"Charge a change fee first\"]', '[\"2\"]', 2),
(1787, 6441, 'Rooming a guest means', 'single_choice', 4, '[\"Leaving them to find the room themselves\",\"Escorting them and showing how the room works, then confirming they have what they need\",\"Sending a bellman with the luggage only\",\"Calling the room after ten minutes\"]', '[\"2\"]', 3),
(1788, 6441, 'When should the guest be told the checkout time?', 'single_choice', 4, '[\"Never, it is on the door\",\"At check-in, along with breakfast times and Wi-Fi\",\"Only if they ask\",\"On the morning of departure\"]', '[\"2\"]', 4),
(1789, 6442, 'A guest disputes a minibar charge at checkout. What is the first step?', 'single_choice', 4, '[\"Remove it immediately without checking\",\"Insist the charge stands\",\"Check the posting with housekeeping before deciding, and keep the guest informed\",\"Ask the guest to email the hotel later\"]', '[\"3\"]', 1),
(1790, 6442, 'What should be offered at the end of every checkout?', 'single_choice', 4, '[\"A discount voucher\",\"An itemised folio and help with onward travel or luggage\",\"A review request only\",\"Nothing\"]', '[\"2\"]', 2),
(1791, 6442, 'A late checkout request should be answered by', 'single_choice', 4, '[\"Refusing automatically\",\"Checking the arrivals for that room type before committing\",\"Always agreeing\",\"Charging a full extra night in every case\"]', '[\"2\"]', 3),
(1792, 6442, 'Why does the folio need to be accurate before the guest leaves?', 'single_choice', 4, '[\"It is easier to correct in person than after departure\",\"It is a legal requirement in every country\",\"It changes the room rate\",\"It is not important\"]', '[\"1\"]', 4),
(1793, 6443, 'The guest folio is', 'single_choice', 4, '[\"The room key record\",\"The running account of every charge and payment for that stay\",\"The housekeeping report\",\"The reservation confirmation\"]', '[\"2\"]', 1),
(1794, 6443, 'Which details must be captured at registration in Saudi Arabia?', 'single_choice', 4, '[\"Name only\",\"Identity document details as required by law, plus contact and payment\",\"Nothing, the booking suffices\",\"Social media handle\"]', '[\"2\"]', 2),
(1795, 6443, 'A registration card signed by the guest establishes', 'single_choice', 4, '[\"The guest\'s agreement to the rate and the hotel\'s terms\",\"The housekeeping schedule\",\"The loyalty tier\",\"Nothing legally\"]', '[\"1\"]', 3),
(1796, 6443, 'Where a guest declines to give required identity details, the agent should', 'single_choice', 4, '[\"Check them in anyway\",\"Explain that it is a legal requirement and involve the duty manager if it is refused\",\"Refuse service without explanation\",\"Copy details from a previous stay\"]', '[\"2\"]', 4),
(1797, 6444, 'Which guest should be prioritised when assigning the best available room?', 'single_choice', 4, '[\"The latest booker\",\"Guests with an accessibility requirement, then VIP and repeat guests\",\"Whoever complains most\",\"The cheapest rate\"]', '[\"2\"]', 1),
(1798, 6444, 'An accessible room should be held for', 'single_choice', 4, '[\"Anyone, it is a normal room\",\"A guest who has requested one, until it is clear none is needed\",\"Staff use\",\"Group bookings\"]', '[\"2\"]', 2),
(1799, 6444, 'A room marked out of order should be', 'single_choice', 4, '[\"Sold at a discount\",\"Kept out of inventory until engineering releases it\",\"Assigned to a late arrival\",\"Cleaned and sold\"]', '[\"2\"]', 3),
(1800, 6444, 'Why are connecting rooms held back during a family-heavy arrival day?', 'single_choice', 4, '[\"They are harder to clean\",\"They are the only option for families travelling with children and are quickly exhausted\",\"They cost more\",\"They are not held back\"]', '[\"2\"]', 4),
(1801, 6445, 'A guest asks for a restaurant recommendation. The best answer', 'single_choice', 4, '[\"Names the hotel restaurant only\",\"Asks what they are in the mood for, then gives two or three options with reasons\",\"Hands them a directory\",\"Names the most expensive option\"]', '[\"2\"]', 1),
(1802, 6445, 'The bell desk is responsible for', 'single_choice', 4, '[\"Room cleaning\",\"Luggage handling, storage and delivery, and assisting arrivals and departures\",\"Billing\",\"Reservations\"]', '[\"2\"]', 2),
(1803, 6445, 'When storing luggage, the item must be', 'single_choice', 4, '[\"Left in the lobby\",\"Tagged with a receipt given to the guest, and stored securely\",\"Kept behind the desk untagged\",\"Taken to the guest room\"]', '[\"2\"]', 3),
(1804, 6445, 'A concierge who cannot arrange a request should', 'single_choice', 4, '[\"Say it is impossible\",\"Offer the nearest alternative and be clear about what can and cannot be done\",\"Promise and then not deliver\",\"Refer the guest to reception\"]', '[\"2\"]', 4),
(1805, 6446, 'A guest is angry about noise from the room above. What comes first?', 'single_choice', 4, '[\"Explain the hotel policy\",\"Listen without interrupting, acknowledge the problem and apologise for the effect on them\",\"Offer a free night\",\"Ask them to put it in writing\"]', '[\"2\"]', 1),
(1806, 6446, 'What does LEARN stand for in complaint handling?', 'single_choice', 4, '[\"Listen, Empathise, Apologise, React, Notify\",\"Leave, Escalate, Argue, Refuse, Note\",\"Log, Email, Assign, Review, Notify\",\"Listen, Explain, Argue, Refund, Note\"]', '[\"1\"]', 2),
(1807, 6446, 'When a complaint cannot be resolved by the agent, the correct action is', 'single_choice', 4, '[\"Tell the guest nothing can be done\",\"Escalate to the duty manager with the facts, and tell the guest who will contact them and when\",\"Give the guest the manager\'s mobile number\",\"Wait until the next shift\"]', '[\"2\"]', 3),
(1808, 6446, 'Why is every complaint logged, even one resolved on the spot?', 'single_choice', 4, '[\"To justify refusing a refund later\",\"So repeat causes can be found and fixed\",\"It is not logged if resolved\",\"To record which staff member was at fault\"]', '[\"2\"]', 4),
(1809, 6447, 'A returning guest\'s preferences should be', 'single_choice', 4, '[\"Asked again every stay as if new\",\"Held on the profile and acted on before arrival\",\"Guessed\",\"Ignored\"]', '[\"2\"]', 1),
(1810, 6447, 'A VIP arrival is prepared by', 'single_choice', 4, '[\"Doing nothing different\",\"Checking the room personally, confirming amenities are placed and briefing the team who will meet them\",\"Assigning any available room\",\"Upgrading automatically\"]', '[\"2\"]', 2),
(1811, 6447, 'Recognising a repeat guest by name at arrival matters because', 'single_choice', 4, '[\"It is required by law\",\"It is the clearest signal that the hotel remembers them, and it costs nothing\",\"It speeds up check-in\",\"It does not matter\"]', '[\"2\"]', 3),
(1812, 6447, 'A VIP complaint should be handled', 'single_choice', 4, '[\"The same as any other, with the duty manager informed early\",\"By giving whatever is asked for\",\"By ignoring the normal process\",\"By the general manager only\"]', '[\"1\"]', 4),
(1813, 6448, 'Within how many rings should an internal call be answered as a standard?', 'single_choice', 4, '[\"Three\",\"Eight\",\"Fifteen\",\"It does not matter\"]', '[\"1\"]', 1),
(1814, 6448, 'The correct greeting on answering an external call includes', 'single_choice', 4, '[\"Just \\\"hello\\\"\",\"The hotel name, the department, your name and an offer of help\",\"Only your name\",\"The room number\"]', '[\"2\"]', 2),
(1815, 6448, 'Before placing a caller on hold you should', 'single_choice', 4, '[\"Put them on hold immediately\",\"Ask permission, explain why, and thank them when you return\",\"Transfer them instead\",\"Tell them to call back\"]', '[\"2\"]', 3),
(1816, 6448, 'A caller asks to be put through to a guest room. The agent should', 'single_choice', 4, '[\"Connect without confirming anything\",\"Ask for the guest name, and connect without revealing the room number\",\"Give the room number so the caller can dial direct\",\"Refuse all such calls\"]', '[\"2\"]', 4),
(1817, 6449, 'The best moment to offer a room upgrade is', 'single_choice', 4, '[\"After the guest has paid and left the desk\",\"At check-in, once you know what the guest is here for\",\"By email a week later\",\"At checkout\"]', '[\"2\"]', 1),
(1818, 6449, 'An effective upsell is based on', 'single_choice', 4, '[\"The highest priced room\",\"A benefit that matches what the guest said they need\",\"Pressure\",\"A script read word for word\"]', '[\"2\"]', 2),
(1819, 6449, 'A guest declines the upgrade. The agent should', 'single_choice', 4, '[\"Ask again immediately\",\"Accept it gracefully and continue the check-in normally\",\"Note them as difficult\",\"Offer a discount on the same room\"]', '[\"2\"]', 3),
(1820, 6449, 'Why does upselling fail when the guest is tired and late?', 'single_choice', 4, '[\"It does not fail\",\"The guest wants the room, not a decision, and pressing reads as an obstacle\",\"The system blocks it\",\"Rates change at night\"]', '[\"2\"]', 4),
(1821, 6450, 'The night audit exists to', 'single_choice', 4, '[\"Clean the lobby\",\"Close the financial day, post room and tax charges and reconcile the day\'s revenue\",\"Prepare breakfast\",\"Reset the key system\"]', '[\"2\"]', 1),
(1822, 6450, 'A discrepancy found during the audit should be', 'single_choice', 4, '[\"Corrected silently\",\"Documented with the correction and passed to the accounts team\",\"Left for the morning shift\",\"Ignored if it is small\"]', '[\"2\"]', 2),
(1823, 6450, 'Rooms still showing as occupied after the expected departure should be', 'single_choice', 4, '[\"Charged automatically\",\"Checked against housekeeping status before any charge is raised\",\"Released without checking\",\"Reported to the police\"]', '[\"2\"]', 3),
(1824, 6450, 'Why is the audit run at night?', 'single_choice', 4, '[\"Staff are cheaper\",\"It is the quietest point of the trading day, so the books can be closed against a stable position\",\"It is a legal requirement\",\"The system is faster\"]', '[\"2\"]', 4),
(1825, 6451, 'A caller asks whether a named guest is staying at the hotel. The correct answer is', 'single_choice', 4, '[\"Confirm and put the call through\",\"Neither confirm nor deny that the guest is in house\",\"Confirm but refuse to connect\",\"Give the room number only\"]', '[\"2\"]', 1),
(1826, 6451, 'Under the Saudi Personal Data Protection Law, guest data may be used', 'single_choice', 4, '[\"For any purpose the hotel chooses\",\"Only for the purpose it was collected for, unless the guest consents to more\",\"Freely once the guest has checked out\",\"For marketing by default\"]', '[\"2\"]', 2),
(1827, 6451, 'A printed arrivals list left on the desk is a problem because', 'single_choice', 4, '[\"It wastes paper\",\"It exposes guest names and room numbers to anyone passing\",\"It is out of date quickly\",\"It is not a problem\"]', '[\"2\"]', 3),
(1828, 6451, 'A guest asks what data the hotel holds about them. The correct response is', 'single_choice', 4, '[\"Refuse, it is internal\",\"Follow the hotel\'s data request procedure, which gives the guest a right to know\",\"Read it out from the screen immediately\",\"Tell them no data is held\"]', '[\"2\"]', 4),
(1829, 6452, 'What does a room attendant do before entering a guest room?', 'single_choice', 4, '[\"Enter using the key immediately\",\"Knock, announce \\\"housekeeping\\\", wait, repeat, then enter announcing again\",\"Call the guest from reception\",\"Wait for the guest to leave the floor\"]', '[\"2\"]', 1),
(1830, 6452, 'The housekeeping control desk is responsible for', 'single_choice', 4, '[\"Cooking\",\"Coordinating room status, assignments, keys and guest requests across the floors\",\"Billing guests\",\"Checking guests in\"]', '[\"2\"]', 2),
(1831, 6452, 'A room reported as \"clean\" but not inspected should be', 'single_choice', 4, '[\"Sold immediately\",\"Held until inspected, if the standard requires inspection before release\",\"Reported as out of order\",\"Cleaned again\"]', '[\"2\"]', 3),
(1832, 6452, 'Why is the cleaning sequence fixed rather than left to preference?', 'single_choice', 4, '[\"It is faster to supervise\",\"A fixed order prevents steps being missed and stops clean surfaces being recontaminated\",\"It is not fixed\",\"It saves chemicals\"]', '[\"2\"]', 4),
(1833, 6453, 'In what order should a guest room be cleaned?', 'single_choice', 4, '[\"Bathroom first, then bedroom, then floor\",\"Top to bottom and clean to dirty, finishing with the floor\",\"Floor first\",\"Whatever is quickest\"]', '[\"2\"]', 1),
(1834, 6453, 'Cloths are colour coded so that', 'single_choice', 4, '[\"They look tidy\",\"A cloth used in the toilet is never used on a surface a guest touches\",\"They match the uniform\",\"They are easier to count\"]', '[\"2\"]', 2),
(1835, 6453, 'A guest\'s personal belongings found during cleaning should be', 'single_choice', 4, '[\"Moved to a drawer\",\"Left where they are, tidied around but not handled or moved unnecessarily\",\"Put in lost and found\",\"Photographed\"]', '[\"2\"]', 3),
(1836, 6453, 'A departure room differs from a stayover room mainly because', 'single_choice', 4, '[\"It takes less time\",\"Everything is stripped and replaced, and the room is reset to a sellable standard\",\"Only the bed is made\",\"It needs no inspection\"]', '[\"2\"]', 4),
(1837, 6454, 'Linen should be changed on a stayover', 'single_choice', 4, '[\"Never\",\"According to the hotel standard, and always on request or when soiled\",\"Only at departure\",\"Every third day regardless\"]', '[\"2\"]', 1),
(1838, 6454, 'Stripped linen should be', 'single_choice', 4, '[\"Placed on the floor\",\"Placed directly into the linen bag on the trolley, never on the floor or furniture\",\"Left on the chair\",\"Shaken out in the room\"]', '[\"2\"]', 2),
(1839, 6454, 'Why is bed linen not shaken out in a guest room?', 'single_choice', 4, '[\"It creases\",\"It disperses dust and any contamination into the air the guest will breathe\",\"It takes longer\",\"It is allowed\"]', '[\"2\"]', 3),
(1840, 6454, 'A mattress protector is checked at every departure because', 'single_choice', 4, '[\"It is decorative\",\"A soiled protector means the mattress may be affected and must be dealt with before the room is sold\",\"It is not checked\",\"Guests ask about it\"]', '[\"2\"]', 4),
(1841, 6455, 'Which is cleaned last in a bathroom?', 'single_choice', 4, '[\"The mirror\",\"The toilet\",\"The basin\",\"The shower\"]', '[\"2\"]', 1),
(1842, 6455, 'A cloth used on the toilet may then be used on', 'single_choice', 4, '[\"The basin\",\"The mirror\",\"Nothing else, it is removed from service\",\"The bath\"]', '[\"3\"]', 2),
(1843, 6455, 'Contact time for a disinfectant means', 'single_choice', 4, '[\"How long it takes to apply\",\"The time the surface must stay wet for the product to work\",\"How long the bottle lasts\",\"The drying time\"]', '[\"2\"]', 3),
(1844, 6455, 'Bathroom amenities are replenished', 'single_choice', 4, '[\"Only at departure\",\"To the standard set for the room type, at every service\",\"When the guest asks\",\"Never\"]', '[\"2\"]', 4),
(1845, 6456, 'Room inspection exists to', 'single_choice', 4, '[\"Catch staff out\",\"Confirm the room meets the standard before it is sold, and find what training is needed\",\"Slow the release of rooms\",\"Satisfy the guest\"]', '[\"2\"]', 1),
(1846, 6456, 'An inspector finding a repeated fault across several rooms should', 'single_choice', 4, '[\"Fix it quietly\",\"Record it and raise it as a training or process issue, not just a room issue\",\"Ignore it\",\"Report the attendant\"]', '[\"2\"]', 2),
(1847, 6456, 'A room failing inspection is', 'single_choice', 4, '[\"Sold anyway\",\"Returned for correction and re-inspected before release\",\"Marked out of order\",\"Released with a note\"]', '[\"2\"]', 3),
(1848, 6456, 'Which is checked in an inspection but easily missed in cleaning?', 'single_choice', 4, '[\"The bed\",\"High and low surfaces, behind doors, and the underside of fittings\",\"The floor\",\"The towels\"]', '[\"2\"]', 4),
(1849, 6457, 'An item found in a departed room must be', 'single_choice', 4, '[\"Kept by the finder\",\"Logged with the room, date and finder, and stored securely\",\"Left in the room\",\"Thrown away\"]', '[\"2\"]', 1),
(1850, 6457, 'A guest calls about an item left behind. The correct step is', 'single_choice', 4, '[\"Say nothing was found\",\"Check the log, and arrange return at the guest\'s cost if it is there\",\"Post it immediately without checking\",\"Ask them to return\"]', '[\"2\"]', 2),
(1851, 6457, 'High-value items such as passports and jewellery should be', 'single_choice', 4, '[\"Stored with everything else\",\"Stored in the safe and reported to the duty manager the same day\",\"Returned to the room\",\"Held by the attendant\"]', '[\"2\"]', 3),
(1852, 6457, 'Unclaimed items are disposed of', 'single_choice', 4, '[\"Immediately\",\"After the retention period set by hotel policy, with the disposal recorded\",\"Never\",\"By the finder\"]', '[\"2\"]', 4),
(1853, 6458, 'Clean and soiled linen must be', 'single_choice', 4, '[\"Transported together to save time\",\"Kept separate at every stage, including transport and storage\",\"Stored in the same room\",\"Sorted by the guest\"]', '[\"2\"]', 1),
(1854, 6458, 'Linen stained with blood or bodily fluid is', 'single_choice', 4, '[\"Washed with the normal load\",\"Handled as infectious, bagged separately and washed to the required temperature\",\"Discarded\",\"Soaked in the room\"]', '[\"2\"]', 2),
(1855, 6458, 'Par stock for linen means', 'single_choice', 4, '[\"The cheapest supplier\",\"The quantity needed to keep every bed supplied while other sets are in circulation\",\"The stock in the laundry\",\"One set per bed\"]', '[\"2\"]', 3),
(1856, 6458, 'Overloading a washing machine results in', 'single_choice', 4, '[\"Faster cycles\",\"Linen that is not properly cleaned or rinsed, and more rewashing\",\"Lower cost\",\"No effect\"]', '[\"2\"]', 4),
(1857, 6459, 'A wet floor in a public area requires', 'single_choice', 4, '[\"No action if it is small\",\"A warning sign in place for as long as the floor is wet\",\"Closing the area\",\"Only a verbal warning\"]', '[\"2\"]', 1),
(1858, 6459, 'Public areas are cleaned on a frequency based on', 'single_choice', 4, '[\"Convenience\",\"Traffic and visibility, with high-touch points done most often\",\"Cost\",\"Guest complaints only\"]', '[\"2\"]', 2),
(1859, 6459, 'High-touch points in a lobby include', 'single_choice', 4, '[\"The ceiling\",\"Door handles, lift buttons, handrails and counter edges\",\"The carpet centre\",\"Artwork\"]', '[\"2\"]', 3),
(1860, 6459, 'Cleaning a public area during peak hours should', 'single_choice', 4, '[\"Proceed as normal\",\"Be limited to what can be done without obstructing guests, with the rest rescheduled\",\"Be skipped entirely\",\"Close the area\"]', '[\"2\"]', 4),
(1861, 6460, 'Deep cleaning differs from daily cleaning because it', 'single_choice', 4, '[\"Is faster\",\"Addresses what daily cleaning cannot reach, on a planned cycle\",\"Uses no chemicals\",\"Is done by the front desk\"]', '[\"2\"]', 1),
(1862, 6460, 'A room scheduled for deep cleaning should be', 'single_choice', 4, '[\"Sold as normal\",\"Blocked from sale for the time the work needs\",\"Cleaned around the guest\",\"Left until it is quiet\"]', '[\"2\"]', 2),
(1863, 6460, 'Deep cleaning is planned on a cycle because', 'single_choice', 4, '[\"It is cheaper\",\"Condition declines predictably, and planned work is cheaper than replacement\",\"Guests request it\",\"It is not planned\"]', '[\"2\"]', 3),
(1864, 6460, 'Which is a deep cleaning task rather than a daily one?', 'single_choice', 4, '[\"Making the bed\",\"Shampooing carpet and cleaning behind and under furniture\",\"Emptying the bin\",\"Replacing towels\"]', '[\"2\"]', 4),
(1865, 6461, 'Two cleaning chemicals should never be mixed because', 'single_choice', 4, '[\"It wastes product\",\"Some combinations, such as bleach and acid cleaners, release toxic gas\",\"It changes the colour\",\"It is allowed if diluted\"]', '[\"2\"]', 1),
(1866, 6461, 'Dilution rates are taken from', 'single_choice', 4, '[\"Experience\",\"The manufacturer\'s instructions and the product data sheet\",\"The strongest that works\",\"The supervisor\'s preference\"]', '[\"2\"]', 2),
(1867, 6461, 'A chemical decanted into a second container must be', 'single_choice', 4, '[\"Left unlabelled\",\"Labelled with the product name and its hazards\",\"Marked only with a colour\",\"Used the same day\"]', '[\"2\"]', 3),
(1868, 6461, 'The safety data sheet for a product tells you', 'single_choice', 4, '[\"The price\",\"The hazards, the protective equipment needed and what to do in an exposure\",\"The supplier address only\",\"Nothing useful\"]', '[\"2\"]', 4),
(1869, 6462, 'Room turnaround time is measured from', 'single_choice', 4, '[\"The guest\'s departure to the room being sellable again\",\"Check-in to checkout\",\"The start to the end of a shift\",\"The booking to the arrival\"]', '[\"1\"]', 1),
(1870, 6462, 'The biggest cause of slow turnaround on a busy departure day is usually', 'single_choice', 4, '[\"Slow attendants\",\"Rooms not being reported as vacant promptly, so cleaning starts late\",\"Too much linen\",\"Guests checking out early\"]', '[\"2\"]', 2),
(1871, 6462, 'Priority rooms in the turnaround queue are', 'single_choice', 4, '[\"The nearest to the linen room\",\"Those with a confirmed early arrival or a guest waiting\",\"The largest rooms\",\"The cheapest rooms\"]', '[\"2\"]', 3),
(1872, 6462, 'Rushing a turnaround typically costs the hotel more because', 'single_choice', 4, '[\"It uses more chemicals\",\"A room released below standard generates a complaint, a move and a refund\",\"It does not cost more\",\"Staff work overtime\"]', '[\"2\"]', 4),
(1873, 6463, 'A trolley is stocked before the shift so that', 'single_choice', 4, '[\"It looks tidy\",\"The attendant does not lose time returning to the store mid-room\",\"It is easier to push\",\"The supervisor can check it\"]', '[\"2\"]', 1),
(1874, 6463, 'Productivity in housekeeping is measured against', 'single_choice', 4, '[\"Rooms per hour alone\",\"Rooms cleaned to standard per hour, since a fast room that fails inspection is not done\",\"Chemicals used\",\"Hours worked\"]', '[\"2\"]', 2),
(1875, 6463, 'Which change most reliably improves productivity?', 'single_choice', 4, '[\"Working faster\",\"Removing interruptions and having the right supplies to hand\",\"Shorter breaks\",\"More staff\"]', '[\"2\"]', 3),
(1876, 6463, 'A room attendant consistently over time should first be', 'single_choice', 4, '[\"Disciplined\",\"Observed, to find whether the cause is method, supplies or the rooms assigned\",\"Reassigned\",\"Given fewer rooms\"]', '[\"2\"]', 4),
(1877, 6464, 'From which side is a plated dish normally served?', 'single_choice', 4, '[\"The guest\'s left, and cleared from the right\",\"The guest\'s right always\",\"Whichever is convenient\",\"Over the guest\'s shoulder\"]', '[\"1\"]', 1),
(1878, 6464, 'A guest at the table has not received their dish while others are eating. The server should', 'single_choice', 4, '[\"Say nothing\",\"Acknowledge it at once, check with the kitchen and give the guest a time\",\"Offer a free dessert\",\"Remove the other plates\"]', '[\"2\"]', 2),
(1879, 6464, 'Plates are cleared when', 'single_choice', 4, '[\"The first guest finishes\",\"Everyone at the table has finished\",\"The kitchen asks\",\"After thirty minutes\"]', '[\"2\"]', 3),
(1880, 6464, 'Carrying a tray, the server should', 'single_choice', 4, '[\"Hold it at chest height across the body\",\"Balance it on the flat palm and forearm, away from the body, loaded heaviest in the centre\",\"Carry it with both hands in front\",\"Rest it on the hip\"]', '[\"2\"]', 4),
(1881, 6465, 'A guest arriving without a reservation at a full restaurant should be', 'single_choice', 4, '[\"Turned away\",\"Given a realistic wait time and the option to wait or book another time\",\"Seated at a reserved table\",\"Asked to come back\"]', '[\"2\"]', 1),
(1882, 6465, 'Within how long should an arriving guest be acknowledged?', 'single_choice', 4, '[\"Thirty seconds, even if the host cannot seat them yet\",\"Five minutes\",\"When a table is free\",\"It does not matter\"]', '[\"1\"]', 2),
(1883, 6465, 'Seating a guest includes', 'single_choice', 4, '[\"Pointing to a table\",\"Escorting them, presenting the menu and telling them who will serve them\",\"Nothing more than showing the table\",\"Taking the order\"]', '[\"2\"]', 3),
(1884, 6465, 'A guest with a mobility aid should be seated', 'single_choice', 4, '[\"Wherever is free\",\"Where they can reach the table without obstruction, asked rather than assumed\",\"Near the door always\",\"At the back\"]', '[\"2\"]', 4),
(1885, 6466, 'In American style service, the food is', 'single_choice', 4, '[\"Carved at the table\",\"Plated in the kitchen and brought to the guest\",\"Served from a platter to the guest\'s plate\",\"Placed in the centre to share\"]', '[\"2\"]', 1),
(1886, 6466, 'Silver service differs in that the server', 'single_choice', 4, '[\"Plates in the kitchen\",\"Transfers food from a platter to the guest\'s plate at the table\",\"Leaves the platter with the guest\",\"Does not serve at all\"]', '[\"2\"]', 2),
(1887, 6466, 'Cutlery is laid', 'single_choice', 4, '[\"In any order\",\"From the outside in, in the order the courses will be eaten\",\"All on the right\",\"After the guest sits\"]', '[\"2\"]', 3),
(1888, 6466, 'The cover is checked before service to confirm', 'single_choice', 4, '[\"The bill is ready\",\"Everything is clean, matched, correctly spaced and free of marks\",\"The guest has arrived\",\"The menu is printed\"]', '[\"2\"]', 4),
(1889, 6467, 'Hot food held for service must be kept at or above', 'single_choice', 4, '[\"50°C\",\"60°C\",\"45°C\",\"37°C\"]', '[\"2\"]', 1),
(1890, 6467, 'A server notices a dish has been on the pass for twenty minutes. They should', 'single_choice', 4, '[\"Serve it quickly\",\"Not serve it, and tell the kitchen so it is replaced\",\"Reheat it under the lamp\",\"Serve it with an apology\"]', '[\"2\"]', 2),
(1891, 6467, 'A guest declares a nut allergy. The server must', 'single_choice', 4, '[\"Suggest dishes they think are safe\",\"Inform the kitchen, confirm with them, and not guess about any ingredient\",\"Say all food is safe\",\"Ask the guest to choose carefully\"]', '[\"2\"]', 3),
(1892, 6467, 'Cross-contamination in the service area most often happens through', 'single_choice', 4, '[\"The menu\",\"Hands, cloths and shared utensils moving between raw and ready-to-eat items\",\"The floor\",\"The till\"]', '[\"2\"]', 4),
(1893, 6468, 'HACCP stands for', 'single_choice', 4, '[\"Hotel and Catering Cleaning Procedure\",\"Hazard Analysis and Critical Control Points\",\"Health and Catering Control Plan\",\"Hygiene Assessment of Cooking and Chilling Practice\"]', '[\"2\"]', 1),
(1894, 6468, 'A critical control point is', 'single_choice', 4, '[\"Any step in the process\",\"A step where control is essential to prevent or eliminate a hazard\",\"The final inspection\",\"The delivery point\"]', '[\"2\"]', 2);
INSERT INTO `question` (`id`, `quiz_id`, `title`, `type`, `number_of_options`, `options`, `correct_answers`, `order`) VALUES
(1895, 6468, 'A critical limit is', 'single_choice', 4, '[\"The maximum number of guests\",\"The measurable boundary, such as a temperature, that separates safe from unsafe\",\"The budget\",\"The shelf life\"]', '[\"2\"]', 3),
(1896, 6468, 'When monitoring shows a critical limit has been breached,', 'single_choice', 4, '[\"Note it and continue\",\"Take the corrective action set out in the plan and record what was done\",\"Discard the record\",\"Inform the guest\"]', '[\"2\"]', 4),
