(2012, 6497, 'Forecasting accuracy matters most because', 'single_choice', 4, '[\"It satisfies the owner\",\"Staffing, purchasing and pricing decisions are all made from it\",\"It sets the budget\",\"It is reported weekly\"]', '[\"2\"]', 4),
(2013, 6498, 'Cost control means', 'single_choice', 4, '[\"Spending less on everything\",\"Spending to a standard, and finding where spend does not produce value\",\"Cutting payroll\",\"Buying the cheapest option\"]', '[\"2\"]', 1),
(2014, 6498, 'Payroll is best controlled by', 'single_choice', 4, '[\"Cutting hours across the board\",\"Matching rostered hours to forecast demand\",\"Reducing pay rates\",\"Using agency staff\"]', '[\"2\"]', 2),
(2015, 6498, 'Purchasing through agreed suppliers helps because', 'single_choice', 4, '[\"It is faster\",\"It fixes specification and price, which makes variance visible\",\"It reduces paperwork\",\"It is required\"]', '[\"2\"]', 3),
(2016, 6498, 'A stock take that is consistently over should prompt', 'single_choice', 4, '[\"A change of supplier\",\"A check of recording, portioning and waste before assuming theft\",\"Reduced ordering\",\"No action\"]', '[\"2\"]', 4),
(2017, 6499, 'The guest experience is shaped most by', 'single_choice', 4, '[\"The building\",\"The moments where something goes wrong and how they are handled\",\"The rate\",\"The location\"]', '[\"2\"]', 1),
(2018, 6499, 'Service recovery done well often results in', 'single_choice', 4, '[\"A worse impression than if nothing had gone wrong\",\"Loyalty higher than if nothing had gone wrong\",\"No change\",\"A refund request\"]', '[\"2\"]', 2),
(2019, 6499, 'Guest feedback is most useful when', 'single_choice', 4, '[\"It is positive\",\"It is specific enough to act on and is routed to the team who can act\",\"It is anonymous\",\"It is public\"]', '[\"2\"]', 3),
(2020, 6499, 'A guest journey map is used to', 'single_choice', 4, '[\"Plan the building layout\",\"Find the points where the guest\'s experience is decided, and design those\",\"Track room moves\",\"Schedule staff\"]', '[\"2\"]', 4),
(2021, 6500, 'A quality standard is useful only if', 'single_choice', 4, '[\"It is written down\",\"It is measurable, and someone actually checks against it\",\"It is ambitious\",\"It matches competitors\"]', '[\"2\"]', 1),
(2022, 6500, 'Root cause analysis asks', 'single_choice', 4, '[\"Who was responsible\",\"Why the failure was possible, repeatedly, until the underlying cause is reached\",\"How much it cost\",\"When it happened\"]', '[\"2\"]', 2),
(2023, 6500, 'A mystery guest audit is most valuable when', 'single_choice', 4, '[\"The score is high\",\"The findings are acted on and re-checked\",\"It is announced\",\"It is frequent\"]', '[\"2\"]', 3),
(2024, 6500, 'Recurring complaints about the same issue indicate', 'single_choice', 4, '[\"Difficult guests\",\"A process problem rather than an individual one\",\"Bad luck\",\"A training need only\"]', '[\"2\"]', 4),
(2025, 6501, 'The first minutes of a crisis should be spent', 'single_choice', 4, '[\"Drafting a statement\",\"Making people safe and establishing who is in charge\",\"Informing the owner\",\"Investigating the cause\"]', '[\"2\"]', 1),
(2026, 6501, 'A single spokesperson is nominated so that', 'single_choice', 4, '[\"Others can avoid responsibility\",\"The hotel speaks with one accurate voice\",\"It is faster\",\"It is legally required\"]', '[\"2\"]', 2),
(2027, 6501, 'A crisis plan is tested because', 'single_choice', 4, '[\"Regulators require it\",\"An untested plan fails at the point of use, and the gaps are only visible in rehearsal\",\"It reassures staff\",\"It is cheap\"]', '[\"2\"]', 3),
(2028, 6501, 'After a crisis, guests and staff should receive', 'single_choice', 4, '[\"No further contact\",\"Follow-up and, where needed, support, since the effect outlasts the event\",\"A discount\",\"A survey\"]', '[\"2\"]', 4),
(2029, 6502, 'RevPAR is', 'single_choice', 4, '[\"Revenue per available room\",\"Revenue per arriving reservation\",\"Rate per available room\",\"Rooms per available rate\"]', '[\"1\"]', 1),
(2030, 6502, 'ADR measures', 'single_choice', 4, '[\"Total revenue divided by rooms available\",\"Room revenue divided by rooms sold\",\"Occupancy times rate\",\"Revenue per guest\"]', '[\"2\"]', 2),
(2031, 6502, 'A hotel with high occupancy and falling RevPAR is likely', 'single_choice', 4, '[\"Performing well\",\"Discounting too heavily to fill rooms\",\"Losing market share\",\"Understaffed\"]', '[\"2\"]', 3),
(2032, 6502, 'GOPPAR is more useful than RevPAR because it', 'single_choice', 4, '[\"Is easier to calculate\",\"Accounts for the cost of earning the revenue, not just the revenue\",\"Excludes departments\",\"Is reported daily\"]', '[\"2\"]', 4),
(2033, 6503, 'A property management system holds', 'single_choice', 4, '[\"Only room rates\",\"Reservations, guest profiles, room status, folios and the night audit\",\"Only housekeeping schedules\",\"Only the booking engine\"]', '[\"2\"]', 1),
(2034, 6503, 'Room status in the PMS should be updated by housekeeping because', 'single_choice', 4, '[\"The front desk cannot sell a room it believes is dirty\",\"It is a legal requirement\",\"It changes the rate\",\"It is not updated\"]', '[\"1\"]', 2),
(2035, 6503, 'A guest profile merged in error causes', 'single_choice', 4, '[\"No problem\",\"Charges and preferences attached to the wrong person, which is both a service and a data protection failure\",\"Faster check-in\",\"A rate change\"]', '[\"2\"]', 3),
(2036, 6503, 'Before overriding a PMS rate, an agent should', 'single_choice', 4, '[\"Override freely\",\"Follow the authorisation rule, because rate overrides are auditable\",\"Ask the guest\",\"Change it back afterwards\"]', '[\"2\"]', 4),
(2037, 6504, 'A channel manager exists to', 'single_choice', 4, '[\"Choose which OTAs to use\",\"Keep rates and availability consistent across every connected channel\",\"Negotiate commission\",\"Handle guest messages\"]', '[\"2\"]', 1),
(2038, 6504, 'Overbooking most often results from', 'single_choice', 4, '[\"Guest error\",\"Inventory not syncing between channels in time\",\"Rate changes\",\"Cancellations\"]', '[\"2\"]', 2),
(2039, 6504, 'Channel mix should be reviewed because', 'single_choice', 4, '[\"Contracts expire\",\"Each channel has a different cost of acquisition, and the mix decides net revenue\",\"OTAs require it\",\"It changes rarely\"]', '[\"2\"]', 3),
(2040, 6504, 'Closing a channel at short notice risks', 'single_choice', 4, '[\"Nothing\",\"Penalties and loss of ranking, so it is a planned decision rather than a reaction\",\"Lower rates\",\"Higher commission\"]', '[\"2\"]', 4),
(2041, 6505, 'The booking engine\'s main commercial purpose is', 'single_choice', 4, '[\"Displaying photographs\",\"Converting a visitor into a direct booking without commission\",\"Managing inventory\",\"Collecting reviews\"]', '[\"2\"]', 1),
(2042, 6505, 'The most common cause of booking abandonment is', 'single_choice', 4, '[\"Room photographs\",\"Unexpected cost or friction appearing late in the flow\",\"Too few room types\",\"Slow email\"]', '[\"2\"]', 2),
(2043, 6505, 'Mobile conversion matters because', 'single_choice', 4, '[\"It is fashionable\",\"A large share of hotel searches happen on a phone, and a poor mobile flow loses them\",\"Desktop is declining\",\"It affects SEO only\"]', '[\"2\"]', 3),
(2044, 6505, 'Rate parity with OTAs should be maintained so that', 'single_choice', 4, '[\"OTAs rank the hotel higher\",\"The direct channel is never more expensive than the commissioned one\",\"The rate is simple\",\"It is legally required everywhere\"]', '[\"2\"]', 4),
(2045, 6506, 'The strongest reason a guest books direct is usually', 'single_choice', 4, '[\"Loyalty points\",\"Confidence that the direct channel gives the best price and terms\",\"Website design\",\"Email offers\"]', '[\"2\"]', 1),
(2046, 6506, 'A direct booking strategy should begin with', 'single_choice', 4, '[\"Discounting below the OTA rate\",\"Making the direct channel at least as good, then making that visible\",\"Closing OTA channels\",\"Paid search only\"]', '[\"2\"]', 2),
(2047, 6506, 'Undercutting OTA rates publicly usually', 'single_choice', 4, '[\"Increases direct share safely\",\"Breaches parity agreements and can cost ranking or the contract\",\"Has no downside\",\"Is the standard approach\"]', '[\"2\"]', 3),
(2048, 6506, 'Direct booking value is measured by', 'single_choice', 4, '[\"Volume alone\",\"Net revenue after acquisition cost, compared with the same booking through an OTA\",\"Conversion rate\",\"Page views\"]', '[\"2\"]', 4),
(2049, 6507, 'OTA commission is best understood as', 'single_choice', 4, '[\"A marketing cost with a measurable return\",\"An unavoidable tax\",\"A fixed fee\",\"A discount to the guest\"]', '[\"1\"]', 1),
(2050, 6507, 'Content on an OTA listing should be', 'single_choice', 4, '[\"Minimal\",\"Complete and accurate, because it drives both ranking and guest expectation\",\"Copied from competitors\",\"Updated annually\"]', '[\"2\"]', 2),
(2051, 6507, 'A poor OTA review should be', 'single_choice', 4, '[\"Ignored\",\"Answered publicly, factually and without argument\",\"Disputed with the OTA\",\"Removed\"]', '[\"2\"]', 3),
(2052, 6507, 'The billboard effect describes', 'single_choice', 4, '[\"OTA advertising spend\",\"Guests finding a hotel on an OTA and then booking direct\",\"Roadside signage\",\"Rate parity\"]', '[\"2\"]', 4),
(2053, 6508, 'A useful metric is one that', 'single_choice', 4, '[\"Is easy to collect\",\"Changes a decision\",\"Looks good in a report\",\"Is tracked by competitors\"]', '[\"2\"]', 1),
(2054, 6508, 'Comparing this month to last month alone is misleading because', 'single_choice', 4, '[\"Months differ in length\",\"Hotel demand is seasonal, so the right comparison is the same period last year\",\"The data is late\",\"It is not misleading\"]', '[\"2\"]', 2),
(2055, 6508, 'Pace reporting shows', 'single_choice', 4, '[\"How fast the website loads\",\"How bookings for a future date are building compared with the same point last year\",\"Staff productivity\",\"Channel cost\"]', '[\"2\"]', 3),
(2056, 6508, 'A dashboard with fifty metrics usually', 'single_choice', 4, '[\"Gives the fullest picture\",\"Hides the few numbers that actually drive action\",\"Is best practice\",\"Is easier to read\"]', '[\"2\"]', 4),
(2057, 6509, 'Hotel marketing spend should be judged on', 'single_choice', 4, '[\"Impressions\",\"Revenue generated against cost, by channel\",\"Follower growth\",\"Click volume\"]', '[\"2\"]', 1),
(2058, 6509, 'The most valuable owned channel for a hotel is usually', 'single_choice', 4, '[\"Social media\",\"The guest email list, because it is direct and costs nothing per send\",\"Paid search\",\"Display advertising\"]', '[\"2\"]', 2),
(2059, 6509, 'Photography matters commercially because', 'single_choice', 4, '[\"It fills the website\",\"It is the single biggest driver of whether a listing converts\",\"It is cheap\",\"It supports SEO\"]', '[\"2\"]', 3),
(2060, 6509, 'Marketing to past guests works because', 'single_choice', 4, '[\"They are easy to reach\",\"They convert at a far higher rate and cost less to reach than new prospects\",\"They expect discounts\",\"It is required\"]', '[\"2\"]', 4),
(2061, 6510, 'For a hotel, the highest-value organic search terms are usually', 'single_choice', 4, '[\"Generic terms like \\\"hotel\\\"\",\"Location plus intent, such as \\\"hotel near Riyadh airport\\\"\",\"Brand terms only\",\"Competitor names\"]', '[\"2\"]', 1),
(2062, 6510, 'A Google Business Profile matters because', 'single_choice', 4, '[\"It replaces the website\",\"It is often the first and sometimes only result a local searcher sees\",\"It improves rankings directly\",\"It is required\"]', '[\"2\"]', 2),
(2063, 6510, 'Duplicate descriptions copied from an OTA harm the site because', 'single_choice', 4, '[\"The OTA objects\",\"Search engines have no reason to rank a page that adds nothing new\",\"They are too long\",\"They do not harm it\"]', '[\"2\"]', 3),
(2064, 6510, 'Page speed affects hotel SEO mainly through', 'single_choice', 4, '[\"Keyword ranking alone\",\"Users abandoning a slow page, which search engines observe\",\"Image quality\",\"Server cost\"]', '[\"2\"]', 4),
(2065, 6511, 'The most important thing to do with a negative review is', 'single_choice', 4, '[\"Dispute it\",\"Respond factually, and fix the cause if it is real\",\"Ignore it\",\"Ask for its removal\"]', '[\"2\"]', 1),
(2066, 6511, 'Review volume matters alongside score because', 'single_choice', 4, '[\"It affects commission\",\"A high score on very few reviews is not yet evidence\",\"It improves rate\",\"It does not matter\"]', '[\"2\"]', 2),
(2067, 6511, 'Asking every guest for a review is', 'single_choice', 4, '[\"Against policy everywhere\",\"Reasonable, provided it is not selective about who is asked\",\"Only for happy guests\",\"Ineffective\"]', '[\"2\"]', 3),
(2068, 6511, 'A pattern in reviews is more useful than any single review because', 'single_choice', 4, '[\"It is easier to read\",\"It points at a process that is repeatedly failing\",\"It is more recent\",\"It affects ranking more\"]', '[\"2\"]', 4),
(2069, 6512, 'When choosing hotel technology, integration matters because', 'single_choice', 4, '[\"It reduces licence cost\",\"Systems that cannot exchange data create manual work and errors\",\"It is a vendor requirement\",\"It speeds up training\"]', '[\"2\"]', 1),
(2070, 6512, 'Guest data held in a hotel system must be', 'single_choice', 4, '[\"Shared freely with partners\",\"Protected, with access limited to those who need it for their work\",\"Deleted monthly\",\"Stored locally only\"]', '[\"2\"]', 2),
(2071, 6512, 'The main risk in replacing a core system is', 'single_choice', 4, '[\"Cost\",\"Data migration and the period where staff know neither system well\",\"Vendor support\",\"Hardware\"]', '[\"2\"]', 3),
(2072, 6512, 'A technology decision should be led by', 'single_choice', 4, '[\"The IT supplier\",\"The operational problem it is meant to solve\",\"The lowest price\",\"What competitors use\"]', '[\"2\"]', 4),
(2073, 7179, 'A guest arrives at 11:00 and the room is not ready. What does the agent do first?', 'single_choice', 4, '[\"Tell the guest to come back at check-in time\",\"Acknowledge it, offer luggage storage and give a specific time the room will be ready\",\"Upgrade the guest to a suite at no charge\",\"Check the guest in anyway and let them wait in the corridor\"]', '[\"2\"]', 1),
(2074, 7179, 'What does the front office hand over at shift change?', 'single_choice', 4, '[\"Only the cash float\",\"Pending arrivals, guest requests still open, out-of-order rooms and anything unresolved\",\"Nothing, the system holds all of it\",\"Only complaints\"]', '[\"2\"]', 2),
(2075, 7179, 'Which department does the front desk depend on most to sell a clean room?', 'single_choice', 4, '[\"Engineering\",\"Housekeeping\",\"Finance\",\"Sales\"]', '[\"2\"]', 3),
(2076, 7179, 'A guest asks a question the agent cannot answer. The correct response is to', 'single_choice', 4, '[\"Guess, so the guest is not kept waiting\",\"Say it is not your department\",\"Say you will find out, give a time, and come back with the answer\",\"Refer them to the website\"]', '[\"3\"]', 4),
(2077, 7180, 'A walk-in guest arrives when the hotel is full. The agent should', 'single_choice', 4, '[\"Turn them away\",\"Check for cancellations, then help them find a room nearby if there is genuinely nothing\",\"Put them in an out-of-order room\",\"Ask them to wait indefinitely\"]', '[\"2\"]', 1),
(2078, 7180, 'The arrivals list is checked at the start of a shift to', 'single_choice', 4, '[\"Count staff\",\"Know who is coming, what they have asked for and which rooms are committed\",\"Set room rates\",\"Order breakfast\"]', '[\"2\"]', 2),
(2079, 7180, 'A reservation taken by phone must be read back because', 'single_choice', 4, '[\"It is polite\",\"It catches errors in dates, room type and spelling before they become a problem at arrival\",\"The system requires it\",\"It is not read back\"]', '[\"2\"]', 3),
(2080, 7180, 'Which of these is a front desk responsibility at every shift?', 'single_choice', 4, '[\"Counting and signing for the cash float\",\"Cleaning guest rooms\",\"Cooking breakfast\",\"Fixing air conditioning\"]', '[\"1\"]', 4),
(2081, 7181, 'What must be verified before a room key is issued?', 'single_choice', 4, '[\"The guest\'s identity against the reservation\",\"The guest\'s social media\",\"Nothing, the booking is enough\",\"Only the payment card\"]', '[\"1\"]', 1),
(2082, 7181, 'A guest booked a twin room and arrives expecting a double. What is the correct step?', 'single_choice', 4, '[\"Insist the booking is correct and move on\",\"Check availability for a double, explain the options and confirm before moving them\",\"Move them without telling them\",\"Charge a change fee first\"]', '[\"2\"]', 2),
(2083, 7181, 'Rooming a guest means', 'single_choice', 4, '[\"Leaving them to find the room themselves\",\"Escorting them and showing how the room works, then confirming they have what they need\",\"Sending a bellman with the luggage only\",\"Calling the room after ten minutes\"]', '[\"2\"]', 3),
(2084, 7181, 'When should the guest be told the checkout time?', 'single_choice', 4, '[\"Never, it is on the door\",\"At check-in, along with breakfast times and Wi-Fi\",\"Only if they ask\",\"On the morning of departure\"]', '[\"2\"]', 4),
(2085, 7182, 'A guest disputes a minibar charge at checkout. What is the first step?', 'single_choice', 4, '[\"Remove it immediately without checking\",\"Insist the charge stands\",\"Check the posting with housekeeping before deciding, and keep the guest informed\",\"Ask the guest to email the hotel later\"]', '[\"3\"]', 1),
(2086, 7182, 'What should be offered at the end of every checkout?', 'single_choice', 4, '[\"A discount voucher\",\"An itemised folio and help with onward travel or luggage\",\"A review request only\",\"Nothing\"]', '[\"2\"]', 2),
(2087, 7182, 'A late checkout request should be answered by', 'single_choice', 4, '[\"Refusing automatically\",\"Checking the arrivals for that room type before committing\",\"Always agreeing\",\"Charging a full extra night in every case\"]', '[\"2\"]', 3),
(2088, 7182, 'Why does the folio need to be accurate before the guest leaves?', 'single_choice', 4, '[\"It is easier to correct in person than after departure\",\"It is a legal requirement in every country\",\"It changes the room rate\",\"It is not important\"]', '[\"1\"]', 4),
(2089, 7183, 'The guest folio is', 'single_choice', 4, '[\"The room key record\",\"The running account of every charge and payment for that stay\",\"The housekeeping report\",\"The reservation confirmation\"]', '[\"2\"]', 1),
(2090, 7183, 'Which details must be captured at registration in Saudi Arabia?', 'single_choice', 4, '[\"Name only\",\"Identity document details as required by law, plus contact and payment\",\"Nothing, the booking suffices\",\"Social media handle\"]', '[\"2\"]', 2),
(2091, 7183, 'A registration card signed by the guest establishes', 'single_choice', 4, '[\"The guest\'s agreement to the rate and the hotel\'s terms\",\"The housekeeping schedule\",\"The loyalty tier\",\"Nothing legally\"]', '[\"1\"]', 3),
(2092, 7183, 'Where a guest declines to give required identity details, the agent should', 'single_choice', 4, '[\"Check them in anyway\",\"Explain that it is a legal requirement and involve the duty manager if it is refused\",\"Refuse service without explanation\",\"Copy details from a previous stay\"]', '[\"2\"]', 4),
(2093, 7184, 'Which guest should be prioritised when assigning the best available room?', 'single_choice', 4, '[\"The latest booker\",\"Guests with an accessibility requirement, then VIP and repeat guests\",\"Whoever complains most\",\"The cheapest rate\"]', '[\"2\"]', 1),
(2094, 7184, 'An accessible room should be held for', 'single_choice', 4, '[\"Anyone, it is a normal room\",\"A guest who has requested one, until it is clear none is needed\",\"Staff use\",\"Group bookings\"]', '[\"2\"]', 2),
(2095, 7184, 'A room marked out of order should be', 'single_choice', 4, '[\"Sold at a discount\",\"Kept out of inventory until engineering releases it\",\"Assigned to a late arrival\",\"Cleaned and sold\"]', '[\"2\"]', 3),
(2096, 7184, 'Why are connecting rooms held back during a family-heavy arrival day?', 'single_choice', 4, '[\"They are harder to clean\",\"They are the only option for families travelling with children and are quickly exhausted\",\"They cost more\",\"They are not held back\"]', '[\"2\"]', 4),
(2097, 7185, 'A guest asks for a restaurant recommendation. The best answer', 'single_choice', 4, '[\"Names the hotel restaurant only\",\"Asks what they are in the mood for, then gives two or three options with reasons\",\"Hands them a directory\",\"Names the most expensive option\"]', '[\"2\"]', 1),
(2098, 7185, 'The bell desk is responsible for', 'single_choice', 4, '[\"Room cleaning\",\"Luggage handling, storage and delivery, and assisting arrivals and departures\",\"Billing\",\"Reservations\"]', '[\"2\"]', 2),
(2099, 7185, 'When storing luggage, the item must be', 'single_choice', 4, '[\"Left in the lobby\",\"Tagged with a receipt given to the guest, and stored securely\",\"Kept behind the desk untagged\",\"Taken to the guest room\"]', '[\"2\"]', 3),
(2100, 7185, 'A concierge who cannot arrange a request should', 'single_choice', 4, '[\"Say it is impossible\",\"Offer the nearest alternative and be clear about what can and cannot be done\",\"Promise and then not deliver\",\"Refer the guest to reception\"]', '[\"2\"]', 4),
(2101, 7186, 'A guest is angry about noise from the room above. What comes first?', 'single_choice', 4, '[\"Explain the hotel policy\",\"Listen without interrupting, acknowledge the problem and apologise for the effect on them\",\"Offer a free night\",\"Ask them to put it in writing\"]', '[\"2\"]', 1),
(2102, 7186, 'What does LEARN stand for in complaint handling?', 'single_choice', 4, '[\"Listen, Empathise, Apologise, React, Notify\",\"Leave, Escalate, Argue, Refuse, Note\",\"Log, Email, Assign, Review, Notify\",\"Listen, Explain, Argue, Refund, Note\"]', '[\"1\"]', 2),
(2103, 7186, 'When a complaint cannot be resolved by the agent, the correct action is', 'single_choice', 4, '[\"Tell the guest nothing can be done\",\"Escalate to the duty manager with the facts, and tell the guest who will contact them and when\",\"Give the guest the manager\'s mobile number\",\"Wait until the next shift\"]', '[\"2\"]', 3),
(2104, 7186, 'Why is every complaint logged, even one resolved on the spot?', 'single_choice', 4, '[\"To justify refusing a refund later\",\"So repeat causes can be found and fixed\",\"It is not logged if resolved\",\"To record which staff member was at fault\"]', '[\"2\"]', 4),
(2105, 7187, 'A returning guest\'s preferences should be', 'single_choice', 4, '[\"Asked again every stay as if new\",\"Held on the profile and acted on before arrival\",\"Guessed\",\"Ignored\"]', '[\"2\"]', 1),
(2106, 7187, 'A VIP arrival is prepared by', 'single_choice', 4, '[\"Doing nothing different\",\"Checking the room personally, confirming amenities are placed and briefing the team who will meet them\",\"Assigning any available room\",\"Upgrading automatically\"]', '[\"2\"]', 2),
(2107, 7187, 'Recognising a repeat guest by name at arrival matters because', 'single_choice', 4, '[\"It is required by law\",\"It is the clearest signal that the hotel remembers them, and it costs nothing\",\"It speeds up check-in\",\"It does not matter\"]', '[\"2\"]', 3),
(2108, 7187, 'A VIP complaint should be handled', 'single_choice', 4, '[\"The same as any other, with the duty manager informed early\",\"By giving whatever is asked for\",\"By ignoring the normal process\",\"By the general manager only\"]', '[\"1\"]', 4);
INSERT INTO `question` (`id`, `quiz_id`, `title`, `type`, `number_of_options`, `options`, `correct_answers`, `order`) VALUES
(2109, 7188, 'Within how many rings should an internal call be answered as a standard?', 'single_choice', 4, '[\"Three\",\"Eight\",\"Fifteen\",\"It does not matter\"]', '[\"1\"]', 1),
(2110, 7188, 'The correct greeting on answering an external call includes', 'single_choice', 4, '[\"Just \\\"hello\\\"\",\"The hotel name, the department, your name and an offer of help\",\"Only your name\",\"The room number\"]', '[\"2\"]', 2),
(2111, 7188, 'Before placing a caller on hold you should', 'single_choice', 4, '[\"Put them on hold immediately\",\"Ask permission, explain why, and thank them when you return\",\"Transfer them instead\",\"Tell them to call back\"]', '[\"2\"]', 3),
(2112, 7188, 'A caller asks to be put through to a guest room. The agent should', 'single_choice', 4, '[\"Connect without confirming anything\",\"Ask for the guest name, and connect without revealing the room number\",\"Give the room number so the caller can dial direct\",\"Refuse all such calls\"]', '[\"2\"]', 4),
(2113, 7189, 'The best moment to offer a room upgrade is', 'single_choice', 4, '[\"After the guest has paid and left the desk\",\"At check-in, once you know what the guest is here for\",\"By email a week later\",\"At checkout\"]', '[\"2\"]', 1),
(2114, 7189, 'An effective upsell is based on', 'single_choice', 4, '[\"The highest priced room\",\"A benefit that matches what the guest said they need\",\"Pressure\",\"A script read word for word\"]', '[\"2\"]', 2),
(2115, 7189, 'A guest declines the upgrade. The agent should', 'single_choice', 4, '[\"Ask again immediately\",\"Accept it gracefully and continue the check-in normally\",\"Note them as difficult\",\"Offer a discount on the same room\"]', '[\"2\"]', 3),
(2116, 7189, 'Why does upselling fail when the guest is tired and late?', 'single_choice', 4, '[\"It does not fail\",\"The guest wants the room, not a decision, and pressing reads as an obstacle\",\"The system blocks it\",\"Rates change at night\"]', '[\"2\"]', 4),
(2117, 7190, 'The night audit exists to', 'single_choice', 4, '[\"Clean the lobby\",\"Close the financial day, post room and tax charges and reconcile the day\'s revenue\",\"Prepare breakfast\",\"Reset the key system\"]', '[\"2\"]', 1),
(2118, 7190, 'A discrepancy found during the audit should be', 'single_choice', 4, '[\"Corrected silently\",\"Documented with the correction and passed to the accounts team\",\"Left for the morning shift\",\"Ignored if it is small\"]', '[\"2\"]', 2),
(2119, 7190, 'Rooms still showing as occupied after the expected departure should be', 'single_choice', 4, '[\"Charged automatically\",\"Checked against housekeeping status before any charge is raised\",\"Released without checking\",\"Reported to the police\"]', '[\"2\"]', 3),
(2120, 7190, 'Why is the audit run at night?', 'single_choice', 4, '[\"Staff are cheaper\",\"It is the quietest point of the trading day, so the books can be closed against a stable position\",\"It is a legal requirement\",\"The system is faster\"]', '[\"2\"]', 4),
(2121, 7191, 'A caller asks whether a named guest is staying at the hotel. The correct answer is', 'single_choice', 4, '[\"Confirm and put the call through\",\"Neither confirm nor deny that the guest is in house\",\"Confirm but refuse to connect\",\"Give the room number only\"]', '[\"2\"]', 1),
(2122, 7191, 'Under the Saudi Personal Data Protection Law, guest data may be used', 'single_choice', 4, '[\"For any purpose the hotel chooses\",\"Only for the purpose it was collected for, unless the guest consents to more\",\"Freely once the guest has checked out\",\"For marketing by default\"]', '[\"2\"]', 2),
(2123, 7191, 'A printed arrivals list left on the desk is a problem because', 'single_choice', 4, '[\"It wastes paper\",\"It exposes guest names and room numbers to anyone passing\",\"It is out of date quickly\",\"It is not a problem\"]', '[\"2\"]', 3),
(2124, 7191, 'A guest asks what data the hotel holds about them. The correct response is', 'single_choice', 4, '[\"Refuse, it is internal\",\"Follow the hotel\'s data request procedure, which gives the guest a right to know\",\"Read it out from the screen immediately\",\"Tell them no data is held\"]', '[\"2\"]', 4),
(2125, 7192, 'What does a room attendant do before entering a guest room?', 'single_choice', 4, '[\"Enter using the key immediately\",\"Knock, announce \\\"housekeeping\\\", wait, repeat, then enter announcing again\",\"Call the guest from reception\",\"Wait for the guest to leave the floor\"]', '[\"2\"]', 1),
(2126, 7192, 'The housekeeping control desk is responsible for', 'single_choice', 4, '[\"Cooking\",\"Coordinating room status, assignments, keys and guest requests across the floors\",\"Billing guests\",\"Checking guests in\"]', '[\"2\"]', 2),
(2127, 7192, 'A room reported as \"clean\" but not inspected should be', 'single_choice', 4, '[\"Sold immediately\",\"Held until inspected, if the standard requires inspection before release\",\"Reported as out of order\",\"Cleaned again\"]', '[\"2\"]', 3),
(2128, 7192, 'Why is the cleaning sequence fixed rather than left to preference?', 'single_choice', 4, '[\"It is faster to supervise\",\"A fixed order prevents steps being missed and stops clean surfaces being recontaminated\",\"It is not fixed\",\"It saves chemicals\"]', '[\"2\"]', 4),
(2129, 7193, 'In what order should a guest room be cleaned?', 'single_choice', 4, '[\"Bathroom first, then bedroom, then floor\",\"Top to bottom and clean to dirty, finishing with the floor\",\"Floor first\",\"Whatever is quickest\"]', '[\"2\"]', 1),
(2130, 7193, 'Cloths are colour coded so that', 'single_choice', 4, '[\"They look tidy\",\"A cloth used in the toilet is never used on a surface a guest touches\",\"They match the uniform\",\"They are easier to count\"]', '[\"2\"]', 2),
(2131, 7193, 'A guest\'s personal belongings found during cleaning should be', 'single_choice', 4, '[\"Moved to a drawer\",\"Left where they are, tidied around but not handled or moved unnecessarily\",\"Put in lost and found\",\"Photographed\"]', '[\"2\"]', 3),
(2132, 7193, 'A departure room differs from a stayover room mainly because', 'single_choice', 4, '[\"It takes less time\",\"Everything is stripped and replaced, and the room is reset to a sellable standard\",\"Only the bed is made\",\"It needs no inspection\"]', '[\"2\"]', 4),
(2133, 7194, 'Linen should be changed on a stayover', 'single_choice', 4, '[\"Never\",\"According to the hotel standard, and always on request or when soiled\",\"Only at departure\",\"Every third day regardless\"]', '[\"2\"]', 1),
(2134, 7194, 'Stripped linen should be', 'single_choice', 4, '[\"Placed on the floor\",\"Placed directly into the linen bag on the trolley, never on the floor or furniture\",\"Left on the chair\",\"Shaken out in the room\"]', '[\"2\"]', 2),
(2135, 7194, 'Why is bed linen not shaken out in a guest room?', 'single_choice', 4, '[\"It creases\",\"It disperses dust and any contamination into the air the guest will breathe\",\"It takes longer\",\"It is allowed\"]', '[\"2\"]', 3),
(2136, 7194, 'A mattress protector is checked at every departure because', 'single_choice', 4, '[\"It is decorative\",\"A soiled protector means the mattress may be affected and must be dealt with before the room is sold\",\"It is not checked\",\"Guests ask about it\"]', '[\"2\"]', 4),
(2137, 7195, 'Which is cleaned last in a bathroom?', 'single_choice', 4, '[\"The mirror\",\"The toilet\",\"The basin\",\"The shower\"]', '[\"2\"]', 1),
(2138, 7195, 'A cloth used on the toilet may then be used on', 'single_choice', 4, '[\"The basin\",\"The mirror\",\"Nothing else, it is removed from service\",\"The bath\"]', '[\"3\"]', 2),
(2139, 7195, 'Contact time for a disinfectant means', 'single_choice', 4, '[\"How long it takes to apply\",\"The time the surface must stay wet for the product to work\",\"How long the bottle lasts\",\"The drying time\"]', '[\"2\"]', 3),
(2140, 7195, 'Bathroom amenities are replenished', 'single_choice', 4, '[\"Only at departure\",\"To the standard set for the room type, at every service\",\"When the guest asks\",\"Never\"]', '[\"2\"]', 4),
(2141, 7196, 'Room inspection exists to', 'single_choice', 4, '[\"Catch staff out\",\"Confirm the room meets the standard before it is sold, and find what training is needed\",\"Slow the release of rooms\",\"Satisfy the guest\"]', '[\"2\"]', 1),
(2142, 7196, 'An inspector finding a repeated fault across several rooms should', 'single_choice', 4, '[\"Fix it quietly\",\"Record it and raise it as a training or process issue, not just a room issue\",\"Ignore it\",\"Report the attendant\"]', '[\"2\"]', 2),
(2143, 7196, 'A room failing inspection is', 'single_choice', 4, '[\"Sold anyway\",\"Returned for correction and re-inspected before release\",\"Marked out of order\",\"Released with a note\"]', '[\"2\"]', 3),
(2144, 7196, 'Which is checked in an inspection but easily missed in cleaning?', 'single_choice', 4, '[\"The bed\",\"High and low surfaces, behind doors, and the underside of fittings\",\"The floor\",\"The towels\"]', '[\"2\"]', 4),
(2145, 7197, 'An item found in a departed room must be', 'single_choice', 4, '[\"Kept by the finder\",\"Logged with the room, date and finder, and stored securely\",\"Left in the room\",\"Thrown away\"]', '[\"2\"]', 1),
(2146, 7197, 'A guest calls about an item left behind. The correct step is', 'single_choice', 4, '[\"Say nothing was found\",\"Check the log, and arrange return at the guest\'s cost if it is there\",\"Post it immediately without checking\",\"Ask them to return\"]', '[\"2\"]', 2),
(2147, 7197, 'High-value items such as passports and jewellery should be', 'single_choice', 4, '[\"Stored with everything else\",\"Stored in the safe and reported to the duty manager the same day\",\"Returned to the room\",\"Held by the attendant\"]', '[\"2\"]', 3),
(2148, 7197, 'Unclaimed items are disposed of', 'single_choice', 4, '[\"Immediately\",\"After the retention period set by hotel policy, with the disposal recorded\",\"Never\",\"By the finder\"]', '[\"2\"]', 4),
(2149, 7198, 'Clean and soiled linen must be', 'single_choice', 4, '[\"Transported together to save time\",\"Kept separate at every stage, including transport and storage\",\"Stored in the same room\",\"Sorted by the guest\"]', '[\"2\"]', 1),
(2150, 7198, 'Linen stained with blood or bodily fluid is', 'single_choice', 4, '[\"Washed with the normal load\",\"Handled as infectious, bagged separately and washed to the required temperature\",\"Discarded\",\"Soaked in the room\"]', '[\"2\"]', 2),
(2151, 7198, 'Par stock for linen means', 'single_choice', 4, '[\"The cheapest supplier\",\"The quantity needed to keep every bed supplied while other sets are in circulation\",\"The stock in the laundry\",\"One set per bed\"]', '[\"2\"]', 3),
(2152, 7198, 'Overloading a washing machine results in', 'single_choice', 4, '[\"Faster cycles\",\"Linen that is not properly cleaned or rinsed, and more rewashing\",\"Lower cost\",\"No effect\"]', '[\"2\"]', 4),
(2153, 7199, 'A wet floor in a public area requires', 'single_choice', 4, '[\"No action if it is small\",\"A warning sign in place for as long as the floor is wet\",\"Closing the area\",\"Only a verbal warning\"]', '[\"2\"]', 1),
(2154, 7199, 'Public areas are cleaned on a frequency based on', 'single_choice', 4, '[\"Convenience\",\"Traffic and visibility, with high-touch points done most often\",\"Cost\",\"Guest complaints only\"]', '[\"2\"]', 2),
(2155, 7199, 'High-touch points in a lobby include', 'single_choice', 4, '[\"The ceiling\",\"Door handles, lift buttons, handrails and counter edges\",\"The carpet centre\",\"Artwork\"]', '[\"2\"]', 3),
(2156, 7199, 'Cleaning a public area during peak hours should', 'single_choice', 4, '[\"Proceed as normal\",\"Be limited to what can be done without obstructing guests, with the rest rescheduled\",\"Be skipped entirely\",\"Close the area\"]', '[\"2\"]', 4),
(2157, 7200, 'Deep cleaning differs from daily cleaning because it', 'single_choice', 4, '[\"Is faster\",\"Addresses what daily cleaning cannot reach, on a planned cycle\",\"Uses no chemicals\",\"Is done by the front desk\"]', '[\"2\"]', 1),
(2158, 7200, 'A room scheduled for deep cleaning should be', 'single_choice', 4, '[\"Sold as normal\",\"Blocked from sale for the time the work needs\",\"Cleaned around the guest\",\"Left until it is quiet\"]', '[\"2\"]', 2),
(2159, 7200, 'Deep cleaning is planned on a cycle because', 'single_choice', 4, '[\"It is cheaper\",\"Condition declines predictably, and planned work is cheaper than replacement\",\"Guests request it\",\"It is not planned\"]', '[\"2\"]', 3),
(2160, 7200, 'Which is a deep cleaning task rather than a daily one?', 'single_choice', 4, '[\"Making the bed\",\"Shampooing carpet and cleaning behind and under furniture\",\"Emptying the bin\",\"Replacing towels\"]', '[\"2\"]', 4),
(2161, 7201, 'Two cleaning chemicals should never be mixed because', 'single_choice', 4, '[\"It wastes product\",\"Some combinations, such as bleach and acid cleaners, release toxic gas\",\"It changes the colour\",\"It is allowed if diluted\"]', '[\"2\"]', 1),
(2162, 7201, 'Dilution rates are taken from', 'single_choice', 4, '[\"Experience\",\"The manufacturer\'s instructions and the product data sheet\",\"The strongest that works\",\"The supervisor\'s preference\"]', '[\"2\"]', 2),
(2163, 7201, 'A chemical decanted into a second container must be', 'single_choice', 4, '[\"Left unlabelled\",\"Labelled with the product name and its hazards\",\"Marked only with a colour\",\"Used the same day\"]', '[\"2\"]', 3),
(2164, 7201, 'The safety data sheet for a product tells you', 'single_choice', 4, '[\"The price\",\"The hazards, the protective equipment needed and what to do in an exposure\",\"The supplier address only\",\"Nothing useful\"]', '[\"2\"]', 4),
(2165, 7202, 'Room turnaround time is measured from', 'single_choice', 4, '[\"The guest\'s departure to the room being sellable again\",\"Check-in to checkout\",\"The start to the end of a shift\",\"The booking to the arrival\"]', '[\"1\"]', 1),
(2166, 7202, 'The biggest cause of slow turnaround on a busy departure day is usually', 'single_choice', 4, '[\"Slow attendants\",\"Rooms not being reported as vacant promptly, so cleaning starts late\",\"Too much linen\",\"Guests checking out early\"]', '[\"2\"]', 2),
(2167, 7202, 'Priority rooms in the turnaround queue are', 'single_choice', 4, '[\"The nearest to the linen room\",\"Those with a confirmed early arrival or a guest waiting\",\"The largest rooms\",\"The cheapest rooms\"]', '[\"2\"]', 3),
(2168, 7202, 'Rushing a turnaround typically costs the hotel more because', 'single_choice', 4, '[\"It uses more chemicals\",\"A room released below standard generates a complaint, a move and a refund\",\"It does not cost more\",\"Staff work overtime\"]', '[\"2\"]', 4),
(2169, 7203, 'A trolley is stocked before the shift so that', 'single_choice', 4, '[\"It looks tidy\",\"The attendant does not lose time returning to the store mid-room\",\"It is easier to push\",\"The supervisor can check it\"]', '[\"2\"]', 1),
(2170, 7203, 'Productivity in housekeeping is measured against', 'single_choice', 4, '[\"Rooms per hour alone\",\"Rooms cleaned to standard per hour, since a fast room that fails inspection is not done\",\"Chemicals used\",\"Hours worked\"]', '[\"2\"]', 2),
(2171, 7203, 'Which change most reliably improves productivity?', 'single_choice', 4, '[\"Working faster\",\"Removing interruptions and having the right supplies to hand\",\"Shorter breaks\",\"More staff\"]', '[\"2\"]', 3),
(2172, 7203, 'A room attendant consistently over time should first be', 'single_choice', 4, '[\"Disciplined\",\"Observed, to find whether the cause is method, supplies or the rooms assigned\",\"Reassigned\",\"Given fewer rooms\"]', '[\"2\"]', 4),
(2173, 7204, 'From which side is a plated dish normally served?', 'single_choice', 4, '[\"The guest\'s left, and cleared from the right\",\"The guest\'s right always\",\"Whichever is convenient\",\"Over the guest\'s shoulder\"]', '[\"1\"]', 1),
(2174, 7204, 'A guest at the table has not received their dish while others are eating. The server should', 'single_choice', 4, '[\"Say nothing\",\"Acknowledge it at once, check with the kitchen and give the guest a time\",\"Offer a free dessert\",\"Remove the other plates\"]', '[\"2\"]', 2),
(2175, 7204, 'Plates are cleared when', 'single_choice', 4, '[\"The first guest finishes\",\"Everyone at the table has finished\",\"The kitchen asks\",\"After thirty minutes\"]', '[\"2\"]', 3),
(2176, 7204, 'Carrying a tray, the server should', 'single_choice', 4, '[\"Hold it at chest height across the body\",\"Balance it on the flat palm and forearm, away from the body, loaded heaviest in the centre\",\"Carry it with both hands in front\",\"Rest it on the hip\"]', '[\"2\"]', 4),
(2177, 7205, 'A guest arriving without a reservation at a full restaurant should be', 'single_choice', 4, '[\"Turned away\",\"Given a realistic wait time and the option to wait or book another time\",\"Seated at a reserved table\",\"Asked to come back\"]', '[\"2\"]', 1),
(2178, 7205, 'Within how long should an arriving guest be acknowledged?', 'single_choice', 4, '[\"Thirty seconds, even if the host cannot seat them yet\",\"Five minutes\",\"When a table is free\",\"It does not matter\"]', '[\"1\"]', 2),
(2179, 7205, 'Seating a guest includes', 'single_choice', 4, '[\"Pointing to a table\",\"Escorting them, presenting the menu and telling them who will serve them\",\"Nothing more than showing the table\",\"Taking the order\"]', '[\"2\"]', 3),
(2180, 7205, 'A guest with a mobility aid should be seated', 'single_choice', 4, '[\"Wherever is free\",\"Where they can reach the table without obstruction, asked rather than assumed\",\"Near the door always\",\"At the back\"]', '[\"2\"]', 4),
(2181, 7206, 'In American style service, the food is', 'single_choice', 4, '[\"Carved at the table\",\"Plated in the kitchen and brought to the guest\",\"Served from a platter to the guest\'s plate\",\"Placed in the centre to share\"]', '[\"2\"]', 1),
(2182, 7206, 'Silver service differs in that the server', 'single_choice', 4, '[\"Plates in the kitchen\",\"Transfers food from a platter to the guest\'s plate at the table\",\"Leaves the platter with the guest\",\"Does not serve at all\"]', '[\"2\"]', 2),
(2183, 7206, 'Cutlery is laid', 'single_choice', 4, '[\"In any order\",\"From the outside in, in the order the courses will be eaten\",\"All on the right\",\"After the guest sits\"]', '[\"2\"]', 3),
(2184, 7206, 'The cover is checked before service to confirm', 'single_choice', 4, '[\"The bill is ready\",\"Everything is clean, matched, correctly spaced and free of marks\",\"The guest has arrived\",\"The menu is printed\"]', '[\"2\"]', 4),
(2185, 7207, 'Hot food held for service must be kept at or above', 'single_choice', 4, '[\"50°C\",\"60°C\",\"45°C\",\"37°C\"]', '[\"2\"]', 1),
(2186, 7207, 'A server notices a dish has been on the pass for twenty minutes. They should', 'single_choice', 4, '[\"Serve it quickly\",\"Not serve it, and tell the kitchen so it is replaced\",\"Reheat it under the lamp\",\"Serve it with an apology\"]', '[\"2\"]', 2),
(2187, 7207, 'A guest declares a nut allergy. The server must', 'single_choice', 4, '[\"Suggest dishes they think are safe\",\"Inform the kitchen, confirm with them, and not guess about any ingredient\",\"Say all food is safe\",\"Ask the guest to choose carefully\"]', '[\"2\"]', 3),
(2188, 7207, 'Cross-contamination in the service area most often happens through', 'single_choice', 4, '[\"The menu\",\"Hands, cloths and shared utensils moving between raw and ready-to-eat items\",\"The floor\",\"The till\"]', '[\"2\"]', 4),
(2189, 7208, 'HACCP stands for', 'single_choice', 4, '[\"Hotel and Catering Cleaning Procedure\",\"Hazard Analysis and Critical Control Points\",\"Health and Catering Control Plan\",\"Hygiene Assessment of Cooking and Chilling Practice\"]', '[\"2\"]', 1),
(2190, 7208, 'A critical control point is', 'single_choice', 4, '[\"Any step in the process\",\"A step where control is essential to prevent or eliminate a hazard\",\"The final inspection\",\"The delivery point\"]', '[\"2\"]', 2),
(2191, 7208, 'A critical limit is', 'single_choice', 4, '[\"The maximum number of guests\",\"The measurable boundary, such as a temperature, that separates safe from unsafe\",\"The budget\",\"The shelf life\"]', '[\"2\"]', 3),
(2192, 7208, 'When monitoring shows a critical limit has been breached,', 'single_choice', 4, '[\"Note it and continue\",\"Take the corrective action set out in the plan and record what was done\",\"Discard the record\",\"Inform the guest\"]', '[\"2\"]', 4),
(2193, 7209, 'Hands must be washed', 'single_choice', 4, '[\"At the start of the shift only\",\"After any task that could contaminate them, and between handling different foods\",\"Once an hour\",\"Only after the toilet\"]', '[\"2\"]', 1),
(2194, 7209, 'A server with vomiting or diarrhoea must', 'single_choice', 4, '[\"Work with gloves\",\"Report it and stay away from food handling until clear for the required period\",\"Work away from the kitchen\",\"Take medication and continue\"]', '[\"2\"]', 2),
(2195, 7209, 'A cut on the hand must be', 'single_choice', 4, '[\"Left uncovered\",\"Covered with a coloured waterproof dressing, and a glove worn over it\",\"Covered with any plaster\",\"Reason to go home\"]', '[\"2\"]', 3),
(2196, 7209, 'Jewellery is restricted in food areas because', 'single_choice', 4, '[\"It looks unprofessional\",\"It harbours bacteria and can fall into food\",\"It is expensive\",\"It is not restricted\"]', '[\"2\"]', 4),
(2197, 7210, 'Beverages are served', 'single_choice', 4, '[\"Before the guest orders\",\"From the guest\'s right, without reaching across\",\"From the left always\",\"By placing the tray on the table\"]', '[\"2\"]', 1),
(2198, 7210, 'A guest orders an alcoholic drink in a venue that does not serve alcohol. The server should', 'single_choice', 4, '[\"Argue\",\"Explain politely that it is not served and offer the alternatives available\",\"Ignore the request\",\"Send them elsewhere\"]', '[\"2\"]', 2),
(2199, 7210, 'Glassware is handled', 'single_choice', 4, '[\"By the rim\",\"By the stem or the base, never the rim\",\"With a cloth over the top\",\"However is fastest\"]', '[\"2\"]', 3),
(2200, 7210, 'A drink is checked before it leaves the bar for', 'single_choice', 4, '[\"Price\",\"Correct glass, correct garnish, correct level and a clean exterior\",\"Temperature only\",\"Nothing\"]', '[\"2\"]', 4),
(2201, 7211, 'The banquet event order exists to', 'single_choice', 4, '[\"Price the event\",\"Tell every department exactly what is required, when and where\",\"Record complaints\",\"Book the room\"]', '[\"2\"]', 1),
(2202, 7211, 'A last-minute increase in guest numbers should be', 'single_choice', 4, '[\"Refused\",\"Confirmed in writing and communicated to kitchen, service and stewarding at once\",\"Handled on the day\",\"Accepted verbally only\"]', '[\"2\"]', 2),
(2203, 7211, 'In buffet service, food safety depends most on', 'single_choice', 4, '[\"Presentation\",\"Holding temperature and the time food has been on display\",\"The number of dishes\",\"Staff numbers\"]', '[\"2\"]', 3),
(2204, 7211, 'Room set-up should be completed', 'single_choice', 4, '[\"As guests arrive\",\"Before the agreed time, allowing for a final check\",\"Whenever the room is free\",\"By the client\"]', '[\"2\"]', 4),
(2205, 7212, 'An order entered incorrectly into the point of sale should be', 'single_choice', 4, '[\"Left and corrected on the bill\",\"Voided following the authorisation rule, with the reason recorded\",\"Deleted quietly\",\"Ignored if small\"]', '[\"2\"]', 1),
(2206, 7212, 'Voids and discounts are authorised because', 'single_choice', 4, '[\"It slows service\",\"They are the most common route for revenue loss and must be traceable\",\"The system requires it\",\"Guests expect it\"]', '[\"2\"]', 2),
(2207, 7212, 'Splitting a bill should be offered', 'single_choice', 4, '[\"Never\",\"When the table asks, and handled before payment begins\",\"Only for large groups\",\"After payment\"]', '[\"2\"]', 3),
(2208, 7212, 'The till is reconciled at the end of a shift to', 'single_choice', 4, '[\"Count staff\",\"Match takings against recorded sales and find differences while they can still be traced\",\"Set prices\",\"Order stock\"]', '[\"2\"]', 4),
(2209, 7213, 'An effective suggestion at the table is', 'single_choice', 4, '[\"The most expensive item\",\"A specific item that fits what the guest has already chosen\",\"Everything on the menu\",\"A discount\"]', '[\"2\"]', 1),
(2210, 7213, 'Order taking should begin with', 'single_choice', 4, '[\"The nearest guest\",\"A logical order the table can follow, noting seat positions so dishes reach the right person\",\"Whoever speaks first\",\"The host only\"]', '[\"2\"]', 2),
(2211, 7213, 'Repeating the order back to the table', 'single_choice', 4, '[\"Wastes time\",\"Catches errors before they reach the kitchen\",\"Is only for large tables\",\"Is unnecessary with a handheld device\"]', '[\"2\"]', 3),
(2212, 7213, 'Suggesting a dessert works best', 'single_choice', 4, '[\"With the main course order\",\"When the main plates are cleared and the guest is deciding whether to stay\",\"At arrival\",\"With the bill\"]', '[\"2\"]', 4),
(2213, 7214, 'Mise en place means', 'single_choice', 4, '[\"Cleaning down\",\"Everything prepared and in position before service begins\",\"The menu order\",\"The kitchen brigade\"]', '[\"2\"]', 1),
(2214, 7214, 'The brigade system exists to', 'single_choice', 4, '[\"Create hierarchy\",\"Divide the kitchen into sections with clear responsibility so service flows\",\"Reduce staff\",\"Set pay grades\"]', '[\"2\"]', 2),
(2215, 7214, 'A recipe specification is followed exactly because', 'single_choice', 4, '[\"The chef says so\",\"It controls cost, portion and consistency, which the guest and the margin both depend on\",\"It is faster\",\"It is not followed exactly\"]', '[\"2\"]', 3),
(2216, 7214, 'The pass is where', 'single_choice', 4, '[\"Deliveries arrive\",\"Finished dishes are checked before they leave the kitchen\",\"Waste is sorted\",\"Staff eat\"]', '[\"2\"]', 4),
(2217, 7215, 'The temperature danger zone is', 'single_choice', 4, '[\"0°C to 4°C\",\"5°C to 63°C\",\"63°C to 100°C\",\"Below 0°C\"]', '[\"2\"]', 1),
(2218, 7215, 'Cooked food to be cooled must pass through the danger zone', 'single_choice', 4, '[\"Slowly, at room temperature\",\"As quickly as possible, within the time the standard allows\",\"Overnight\",\"It does not matter\"]', '[\"2\"]', 2),
(2219, 7215, 'Raw meat is stored', 'single_choice', 4, '[\"Above ready-to-eat food\",\"Below ready-to-eat food, to prevent drips contaminating it\",\"Anywhere in the fridge\",\"At room temperature\"]', '[\"2\"]', 3),
(2220, 7215, 'Reheated food must reach a core temperature of at least', 'single_choice', 4, '[\"63°C\",\"75°C\",\"50°C\",\"100°C\"]', '[\"2\"]', 4),
(2221, 7216, 'A chef changes their apron', 'single_choice', 4, '[\"Once a week\",\"Whenever it is soiled, and between raw and ready-to-eat work\",\"At the end of the shift\",\"Never\"]', '[\"2\"]', 1),
(2222, 7216, 'Colour-coded boards are used so that', 'single_choice', 4, '[\"They look organised\",\"Raw and ready-to-eat foods never share a preparation surface\",\"They are easier to replace\",\"Chefs can find them\"]', '[\"2\"]', 2),
(2223, 7216, 'Hand contact with ready-to-eat food should be', 'single_choice', 4, '[\"Normal practice\",\"Minimised by using tongs, utensils or single-use gloves\",\"Avoided by washing hands only\",\"Unrestricted with gloves\"]', '[\"2\"]', 3),
(2224, 7216, 'A damaged chopping board must be', 'single_choice', 4, '[\"Cleaned more often\",\"Taken out of service, because cuts and cracks hold bacteria that cannot be cleaned out\",\"Turned over\",\"Sanded down\"]', '[\"2\"]', 4),
(2225, 7217, 'A sharp knife is safer than a blunt one because', 'single_choice', 4, '[\"It cuts less deeply\",\"It needs less force, so it is less likely to slip\",\"It is lighter\",\"It is not safer\"]', '[\"2\"]', 1),
(2226, 7217, 'A knife should be carried', 'single_choice', 4, '[\"Point up\",\"Point down, close to the body, blade turned away\",\"On a tray\",\"In a pocket\"]', '[\"2\"]', 2),
(2227, 7217, 'A falling knife should be', 'single_choice', 4, '[\"Caught\",\"Allowed to fall, with feet moved clear\",\"Kicked aside\",\"Caught by the handle\"]', '[\"2\"]', 3),
(2228, 7217, 'Knives are cleaned', 'single_choice', 4, '[\"In the dishwasher\",\"By hand, immediately, and never left in a sink of water\",\"At the end of service\",\"With the pans\"]', '[\"2\"]', 4),
(2229, 7218, 'FIFO means', 'single_choice', 4, '[\"Fresh In, Frozen Out\",\"First In, First Out, so older stock is used first\",\"Food Inspection For Operations\",\"Fast In, Fast Out\"]', '[\"2\"]', 1),
(2230, 7218, 'Dry goods are stored', 'single_choice', 4, '[\"On the floor\",\"Off the floor on shelving, in sealed containers, away from damp\",\"In the walkway\",\"Next to chemicals\"]', '[\"2\"]', 2),
(2231, 7218, 'An opened product must be', 'single_choice', 4, '[\"Used the same day\",\"Labelled with the date it was opened and its use-by date\",\"Returned to the supplier\",\"Left as delivered\"]', '[\"2\"]', 3),
(2232, 7218, 'Chemicals are stored', 'single_choice', 4, '[\"With the food\",\"In a separate, marked area away from all food\",\"Above the preparation surface\",\"In the fridge\"]', '[\"2\"]', 4),
(2233, 7219, 'A chilled delivery should be checked for temperature', 'single_choice', 4, '[\"After it is put away\",\"On arrival, before it is accepted\",\"The next day\",\"Only if it looks warm\"]', '[\"2\"]', 1),
(2234, 7219, 'A delivery that fails the check should be', 'single_choice', 4, '[\"Accepted and used quickly\",\"Rejected and recorded, with the supplier informed\",\"Accepted and frozen\",\"Accepted at a discount\"]', '[\"2\"]', 2),
(2235, 7219, 'Goods are checked against', 'single_choice', 4, '[\"Memory\",\"The purchase order and the delivery note, for quantity, quality and price\",\"The invoice only\",\"Nothing\"]', '[\"2\"]', 3),
(2236, 7219, 'Damaged packaging matters because', 'single_choice', 4, '[\"It looks poor\",\"The contents may be contaminated and the seal can no longer be relied on\",\"It is harder to store\",\"It does not matter\"]', '[\"2\"]', 4),
(2237, 7220, 'A fridge should run at', 'single_choice', 4, '[\"0°C to 5°C\",\"8°C to 12°C\",\"−18°C\",\"10°C\"]', '[\"1\"]', 1),
(2238, 7220, 'A freezer should run at or below', 'single_choice', 4, '[\"0°C\",\"−18°C\",\"−5°C\",\"4°C\"]', '[\"2\"]', 2),
(2239, 7220, 'Temperature checks are recorded because', 'single_choice', 4, '[\"It is a habit\",\"The record is the evidence that control was maintained, and shows trends before a failure\",\"The supplier asks\",\"They are not recorded\"]', '[\"2\"]', 3),
(2240, 7220, 'A probe thermometer is sanitised', 'single_choice', 4, '[\"Once a day\",\"Before and after every use, and between different foods\",\"Weekly\",\"Never\"]', '[\"2\"]', 4),
(2241, 7221, 'A guest asks whether a dish contains sesame. The correct response is', 'single_choice', 4, '[\"Say you think not\",\"Check the recipe specification and allergen record, and answer from that\",\"Say all dishes are safe\",\"Suggest they avoid it\"]', '[\"2\"]', 1),
(2242, 7221, 'The safest way to prepare an allergen-free dish is', 'single_choice', 4, '[\"Remove the ingredient at the end\",\"Prepare it separately with clean equipment and clean hands\",\"Cook it hotter\",\"Serve it first\"]', '[\"2\"]', 2),
(2243, 7221, 'Allergen information must be', 'single_choice', 4, '[\"Given only if asked\",\"Available and accurate for every dish served\",\"Kept in the office\",\"Estimated\"]', '[\"2\"]', 3),
(2244, 7221, 'A recipe change affecting allergens must be', 'single_choice', 4, '[\"Made quietly\",\"Recorded and communicated to service before the dish is sold\",\"Made only by the head chef\",\"Tested on staff first\"]', '[\"2\"]', 4),
(2245, 7222, 'Food waste is separated because', 'single_choice', 4, '[\"It is required by the landlord\",\"It can be measured and reduced, and it must be disposed of correctly\",\"It smells\",\"It is not separated\"]', '[\"2\"]', 1),
(2246, 7222, 'The largest avoidable source of kitchen waste is usually', 'single_choice', 4, '[\"Trimmings\",\"Over-production and spoilage from poor stock rotation\",\"Packaging\",\"Guest plates\"]', '[\"2\"]', 2),
(2247, 7222, 'Waste oil must be', 'single_choice', 4, '[\"Poured down the drain\",\"Collected and removed by an approved contractor\",\"Mixed with food waste\",\"Reused indefinitely\"]', '[\"2\"]', 3),
(2248, 7222, 'Recording waste is useful because', 'single_choice', 4, '[\"It satisfies the auditor\",\"It shows where product and money are actually being lost, so it can be fixed\",\"It is not useful\",\"It reduces cost directly\"]', '[\"2\"]', 4),
(2249, 7223, 'A cleaning schedule sets out', 'single_choice', 4, '[\"Who is on shift\",\"What is cleaned, how, how often, with what, and by whom\",\"The menu\",\"Delivery times\"]', '[\"2\"]', 1),
(2250, 7223, 'Clean as you go matters because', 'single_choice', 4, '[\"It looks better\",\"It stops contamination building up and keeps the workspace safe during service\",\"It saves chemicals\",\"It is not required\"]', '[\"2\"]', 2),
(2251, 7223, 'Equipment is dismantled for cleaning when', 'single_choice', 4, '[\"It is broken\",\"The manufacturer\'s instructions require it to reach food contact surfaces\",\"Once a year\",\"Never\"]', '[\"2\"]', 3),
(2252, 7223, 'Cleaning is signed off so that', 'single_choice', 4, '[\"Staff can be blamed\",\"There is a record that the task was done, by whom and when\",\"It takes longer\",\"The schedule is met\"]', '[\"2\"]', 4),
(2253, 7224, 'Engineering\'s main contribution to revenue is', 'single_choice', 4, '[\"Reducing the electricity bill\",\"Keeping rooms sellable, because an out-of-order room earns nothing\",\"Buying equipment cheaply\",\"Staffing levels\"]', '[\"2\"]', 1),
(2254, 7224, 'A fault reported by housekeeping should be', 'single_choice', 4, '[\"Fixed when convenient\",\"Logged as a work order, prioritised and tracked to completion\",\"Reported to the guest\",\"Fixed without record\"]', '[\"2\"]', 2),
(2255, 7224, 'Planned maintenance is preferred to reactive repair because', 'single_choice', 4, '[\"It is more interesting\",\"It is cheaper, and it fails at a time you choose rather than during a full house\",\"It uses fewer parts\",\"It is required by law\"]', '[\"2\"]', 3),
(2256, 7224, 'Which record tells you whether a recurring fault is really fixed?', 'single_choice', 4, '[\"The invoice\",\"The work order history for that asset\",\"The guest comment\",\"The duty log\"]', '[\"2\"]', 4),
(2257, 7225, 'Preventive maintenance is scheduled by', 'single_choice', 4, '[\"When something breaks\",\"Time or usage intervals set for each asset\",\"Guest complaints\",\"Budget availability\"]', '[\"2\"]', 1),
(2258, 7225, 'The cost of preventive maintenance is justified by', 'single_choice', 4, '[\"Longer asset life and fewer out-of-order rooms\",\"A lower headcount\",\"Cheaper parts\",\"Insurance discounts\"]', '[\"1\"]', 2),
(2259, 7225, 'A preventive task that is repeatedly skipped should be', 'single_choice', 4, '[\"Removed from the schedule\",\"Investigated, since either the interval is wrong or the resource is not there\",\"Done twice next time\",\"Ignored\"]', '[\"2\"]', 3),
(2260, 7225, 'Asset history is kept so that', 'single_choice', 4, '[\"The auditor is satisfied\",\"Replace-or-repair decisions are made on evidence rather than impression\",\"Staff can be assessed\",\"Warranty is valid\"]', '[\"2\"]', 4),
(2261, 7226, 'A guest reports the room will not cool. The first check is', 'single_choice', 4, '[\"Replace the unit\",\"The set point, the filter and whether a window or balcony door is open\",\"The chiller plant\",\"The thermostat wiring\"]', '[\"2\"]', 1),
(2262, 7226, 'Dirty air filters cause', 'single_choice', 4, '[\"Better filtration\",\"Reduced airflow, higher energy use and poorer cooling\",\"No change\",\"Lower running cost\"]', '[\"2\"]', 2),
(2263, 7226, 'Legionella risk in a building system is managed mainly by', 'single_choice', 4, '[\"Cleaning the ducts\",\"Controlling water temperature and avoiding stagnation\",\"Changing filters\",\"Running the system harder\"]', '[\"2\"]', 3),
(2264, 7226, 'Condensate drains are checked because', 'single_choice', 4, '[\"They are noisy\",\"A blocked drain causes water damage to ceilings and rooms below\",\"They affect temperature\",\"They do not need checking\"]', '[\"2\"]', 4),
(2265, 7227, 'Work on live electrical equipment is', 'single_choice', 4, '[\"Normal for small jobs\",\"Done only by a competent person, with the circuit isolated wherever possible\",\"Allowed with gloves\",\"Done by any technician\"]', '[\"2\"]', 1),
(2266, 7227, 'Lock-out tag-out exists to', 'single_choice', 4, '[\"Record who did the work\",\"Make sure isolated equipment cannot be re-energised while someone is working on it\",\"Prevent theft\",\"Satisfy the insurer\"]', '[\"2\"]', 2),
(2267, 7227, 'A damaged power cable in a guest room should be', 'single_choice', 4, '[\"Taped up\",\"Taken out of service immediately and the item replaced or repaired\",\"Left if it still works\",\"Reported next week\"]', '[\"2\"]', 3),
(2268, 7227, 'Portable appliance testing is done to', 'single_choice', 4, '[\"Extend warranty\",\"Confirm equipment is still electrically safe to use, on a set frequency\",\"Increase efficiency\",\"Track assets\"]', '[\"2\"]', 4),
(2269, 7228, 'The first action on a burst pipe in an occupied floor is', 'single_choice', 4, '[\"Call a contractor\",\"Isolate the water supply to that section\",\"Mop the floor\",\"Move the guest\"]', '[\"2\"]', 1),
(2270, 7228, 'A slow draining shower is most often caused by', 'single_choice', 4, '[\"Low water pressure\",\"A blockage of hair and soap in the trap\",\"A faulty valve\",\"Air in the system\"]', '[\"2\"]', 2),
(2271, 7228, 'Backflow prevention protects', 'single_choice', 4, '[\"The drains\",\"The drinking water supply from contamination\",\"The boiler\",\"The pump\"]', '[\"2\"]', 3),
(2272, 7228, 'Hot water delivered to a guest outlet must be', 'single_choice', 4, '[\"As hot as the system allows\",\"Controlled to prevent scalding, while stored hot enough to control bacteria\",\"Below 40°C in storage\",\"Unregulated\"]', '[\"2\"]', 4),
(2273, 7229, 'On discovering a fire, the first action is', 'single_choice', 4, '[\"Fight the fire\",\"Raise the alarm\",\"Open windows to clear smoke\",\"Find the fire marshal\"]', '[\"2\"]', 1),
(2274, 7229, 'A fire door must never be', 'single_choice', 4, '[\"Closed\",\"Wedged or propped open\",\"Signed\",\"Painted\"]', '[\"2\"]', 2),
(2275, 7229, 'A CO2 extinguisher is used on', 'single_choice', 4, '[\"Cooking oil fires\",\"Electrical fires\",\"Paper and wood\",\"Metal fires\"]', '[\"2\"]', 3),
(2276, 7229, 'The assembly point is where', 'single_choice', 4, '[\"Staff wait for instructions to return\",\"Everyone is accounted for after evacuation\",\"The fire panel is\",\"Guests collect belongings\"]', '[\"2\"]', 4),
(2277, 7230, 'A work order should record', 'single_choice', 4, '[\"Only the fault\",\"The asset, the fault, the priority, who did what and when it was closed\",\"The cost only\",\"The reporter\'s name\"]', '[\"2\"]', 1),
(2278, 7230, 'Priority on a work order is set by', 'single_choice', 4, '[\"Who reported it\",\"Impact on guest safety and on sellable rooms\",\"Ease of repair\",\"Age of the asset\"]', '[\"2\"]', 2),
(2279, 7230, 'A work order is closed when', 'single_choice', 4, '[\"The technician leaves\",\"The fault is fixed and verified, with the work recorded\",\"The part is ordered\",\"The shift ends\"]', '[\"2\"]', 3),
(2280, 7230, 'Open work orders are reviewed daily because', 'single_choice', 4, '[\"It fills the morning meeting\",\"Ageing jobs are the ones that become guest complaints and out-of-order rooms\",\"The system requires it\",\"They are not reviewed\"]', '[\"2\"]', 4),
(2281, 7231, 'An asset inspection checks', 'single_choice', 4, '[\"Only whether it runs\",\"Condition, safety, performance against its standard and what needs planning\",\"The purchase price\",\"The warranty\"]', '[\"2\"]', 1),
(2282, 7231, 'A defect found during inspection is', 'single_choice', 4, '[\"Fixed on the spot if possible, otherwise raised as a work order\",\"Noted for the annual review\",\"Reported verbally\",\"Ignored if minor\"]', '[\"1\"]', 2),
(2283, 7231, 'Inspection frequency is based on', 'single_choice', 4, '[\"Convenience\",\"Criticality, usage and manufacturer guidance\",\"Age alone\",\"Budget\"]', '[\"2\"]', 3),
(2284, 7231, 'Photographs on an inspection record help because', 'single_choice', 4, '[\"They look professional\",\"They show condition at a point in time, which makes deterioration visible\",\"They are required\",\"They speed up the inspection\"]', '[\"2\"]', 4),
(2285, 7232, 'In a power failure, the first priority is', 'single_choice', 4, '[\"Restoring the lifts\",\"Life safety systems and emergency lighting, and accounting for anyone trapped\",\"Restarting the kitchen\",\"Informing guests\"]', '[\"2\"]', 1),
(2286, 7232, 'A guest trapped in a lift should be', 'single_choice', 4, '[\"Told to wait quietly\",\"Kept in contact and reassured while trained release is arranged\",\"Released by any available staff member\",\"Left until the engineer arrives\"]', '[\"2\"]', 2),
(2287, 7232, 'Emergency contact lists are checked regularly because', 'single_choice', 4, '[\"Staff change and an out-of-date number costs time in the one moment it matters\",\"It is an audit point\",\"The list is long\",\"They are not checked\"]', '[\"1\"]', 3),
(2288, 7232, 'After any emergency, the hotel should', 'single_choice', 4, '[\"Return to normal quietly\",\"Review what happened, record it and change what did not work\",\"Report only if a guest was hurt\",\"Wait for the insurer\"]', '[\"2\"]', 4),
(2289, 7233, 'A hotel general manager\'s first responsibility is', 'single_choice', 4, '[\"Occupancy\",\"The safety of guests and staff\",\"Profit\",\"Guest satisfaction scores\"]', '[\"2\"]', 1),
(2290, 7233, 'Departments conflict most often over', 'single_choice', 4, '[\"Budget alone\",\"Room readiness, where housekeeping, engineering and front office share one deadline\",\"Staffing\",\"Menus\"]', '[\"2\"]', 2),
(2291, 7233, 'A daily operations meeting exists to', 'single_choice', 4, '[\"Review the previous year\",\"Align departments on today\'s arrivals, events, issues and constraints\",\"Set strategy\",\"Discuss payroll\"]', '[\"2\"]', 3),
(2292, 7233, 'Standard operating procedures matter most when', 'single_choice', 4, '[\"The hotel is quiet\",\"The hotel is busy or short staffed, and judgement alone will not hold the standard\",\"An auditor visits\",\"New staff join\"]', '[\"2\"]', 4),
(2293, 7234, 'A supervisor who only corrects mistakes will usually', 'single_choice', 4, '[\"Raise standards fastest\",\"Lose the team\'s willingness to raise problems early\",\"Be respected\",\"Reduce turnover\"]', '[\"2\"]', 1),
(2294, 7234, 'Delegation means', 'single_choice', 4, '[\"Giving away the difficult work\",\"Assigning responsibility with the authority and information to carry it out\",\"Avoiding accountability\",\"Reducing your workload\"]', '[\"2\"]', 2),
(2295, 7234, 'Feedback is most effective when it is', 'single_choice', 4, '[\"Given in the annual review\",\"Specific, timely and about the work rather than the person\",\"Given publicly\",\"Written only\"]', '[\"2\"]', 3),
(2296, 7234, 'High turnover in a hospitality team is most often driven by', 'single_choice', 4, '[\"Pay alone\",\"The immediate supervisor and the daily working conditions\",\"Guest behaviour\",\"Shift length\"]', '[\"2\"]', 4),
(2297, 7235, 'A rota should be built around', 'single_choice', 4, '[\"Staff preference alone\",\"Forecast demand, with skill mix covered on every shift\",\"Equal hours for everyone\",\"Seniority\"]', '[\"2\"]', 1),
(2298, 7235, 'A new starter\'s first week should include', 'single_choice', 4, '[\"Full independent shifts\",\"Safety, the standards they will be held to, and supervised practice\",\"Only paperwork\",\"Whatever the shift allows\"]', '[\"2\"]', 2),
(2299, 7235, 'Performance problems should be addressed', 'single_choice', 4, '[\"At the annual review\",\"Early and directly, with clear expectations and support\",\"By reassignment\",\"By the HR department only\"]', '[\"2\"]', 3),
(2300, 7235, 'Cross-training helps the operation because', 'single_choice', 4, '[\"It reduces pay\",\"It covers absence and peaks without adding headcount\",\"It simplifies the rota\",\"It reduces training cost\"]', '[\"2\"]', 4),
(2301, 7236, 'In the uniform system of accounts, departmental profit is', 'single_choice', 4, '[\"Revenue less all hotel costs\",\"Departmental revenue less the direct costs of that department\",\"Revenue less payroll\",\"Gross operating profit\"]', '[\"2\"]', 1),
(2302, 7236, 'A flow-through analysis shows', 'single_choice', 4, '[\"Cash movement\",\"How much of a change in revenue reaches profit\",\"Guest numbers\",\"Debt cover\"]', '[\"2\"]', 2),
(2303, 7236, 'Fixed costs in a hotel', 'single_choice', 4, '[\"Vary with occupancy\",\"Continue whether or not rooms are sold\",\"Are only payroll\",\"Are avoidable\"]', '[\"2\"]', 3),
(2304, 7236, 'A budget variance should be explained by', 'single_choice', 4, '[\"The finance team alone\",\"The department head who owns the line, with the reason and the action\",\"The auditor\",\"Nobody, if it is small\"]', '[\"2\"]', 4),
(2305, 7237, 'Revenue management is the practice of selling', 'single_choice', 4, '[\"The most rooms possible\",\"The right room to the right guest at the right time and price\",\"Rooms at the highest rate\",\"Through the most channels\"]', '[\"2\"]', 1),
(2306, 7237, 'Displacement analysis asks', 'single_choice', 4, '[\"How many guests moved rooms\",\"Whether accepting a group displaces higher-value transient business\",\"Which channel performed best\",\"How many cancelled\"]', '[\"2\"]', 2),
(2307, 7237, 'A rate parity failure means', 'single_choice', 4, '[\"Rates differ between room types\",\"The same room is offered at different rates across channels, undermining direct sales\",\"The rate is too low\",\"Rates changed overnight\"]', '[\"2\"]', 3),
(2308, 7237, 'Forecasting accuracy matters most because', 'single_choice', 4, '[\"It satisfies the owner\",\"Staffing, purchasing and pricing decisions are all made from it\",\"It sets the budget\",\"It is reported weekly\"]', '[\"2\"]', 4),
(2309, 7238, 'Cost control means', 'single_choice', 4, '[\"Spending less on everything\",\"Spending to a standard, and finding where spend does not produce value\",\"Cutting payroll\",\"Buying the cheapest option\"]', '[\"2\"]', 1),
(2310, 7238, 'Payroll is best controlled by', 'single_choice', 4, '[\"Cutting hours across the board\",\"Matching rostered hours to forecast demand\",\"Reducing pay rates\",\"Using agency staff\"]', '[\"2\"]', 2),
(2311, 7238, 'Purchasing through agreed suppliers helps because', 'single_choice', 4, '[\"It is faster\",\"It fixes specification and price, which makes variance visible\",\"It reduces paperwork\",\"It is required\"]', '[\"2\"]', 3),
(2312, 7238, 'A stock take that is consistently over should prompt', 'single_choice', 4, '[\"A change of supplier\",\"A check of recording, portioning and waste before assuming theft\",\"Reduced ordering\",\"No action\"]', '[\"2\"]', 4),
(2313, 7239, 'The guest experience is shaped most by', 'single_choice', 4, '[\"The building\",\"The moments where something goes wrong and how they are handled\",\"The rate\",\"The location\"]', '[\"2\"]', 1),
(2314, 7239, 'Service recovery done well often results in', 'single_choice', 4, '[\"A worse impression than if nothing had gone wrong\",\"Loyalty higher than if nothing had gone wrong\",\"No change\",\"A refund request\"]', '[\"2\"]', 2),
(2315, 7239, 'Guest feedback is most useful when', 'single_choice', 4, '[\"It is positive\",\"It is specific enough to act on and is routed to the team who can act\",\"It is anonymous\",\"It is public\"]', '[\"2\"]', 3),
(2316, 7239, 'A guest journey map is used to', 'single_choice', 4, '[\"Plan the building layout\",\"Find the points where the guest\'s experience is decided, and design those\",\"Track room moves\",\"Schedule staff\"]', '[\"2\"]', 4),
(2317, 7240, 'A quality standard is useful only if', 'single_choice', 4, '[\"It is written down\",\"It is measurable, and someone actually checks against it\",\"It is ambitious\",\"It matches competitors\"]', '[\"2\"]', 1),
(2318, 7240, 'Root cause analysis asks', 'single_choice', 4, '[\"Who was responsible\",\"Why the failure was possible, repeatedly, until the underlying cause is reached\",\"How much it cost\",\"When it happened\"]', '[\"2\"]', 2),
(2319, 7240, 'A mystery guest audit is most valuable when', 'single_choice', 4, '[\"The score is high\",\"The findings are acted on and re-checked\",\"It is announced\",\"It is frequent\"]', '[\"2\"]', 3),
(2320, 7240, 'Recurring complaints about the same issue indicate', 'single_choice', 4, '[\"Difficult guests\",\"A process problem rather than an individual one\",\"Bad luck\",\"A training need only\"]', '[\"2\"]', 4),
(2321, 7241, 'The first minutes of a crisis should be spent', 'single_choice', 4, '[\"Drafting a statement\",\"Making people safe and establishing who is in charge\",\"Informing the owner\",\"Investigating the cause\"]', '[\"2\"]', 1),
(2322, 7241, 'A single spokesperson is nominated so that', 'single_choice', 4, '[\"Others can avoid responsibility\",\"The hotel speaks with one accurate voice\",\"It is faster\",\"It is legally required\"]', '[\"2\"]', 2),
(2323, 7241, 'A crisis plan is tested because', 'single_choice', 4, '[\"Regulators require it\",\"An untested plan fails at the point of use, and the gaps are only visible in rehearsal\",\"It reassures staff\",\"It is cheap\"]', '[\"2\"]', 3);
INSERT INTO `question` (`id`, `quiz_id`, `title`, `type`, `number_of_options`, `options`, `correct_answers`, `order`) VALUES
(2324, 7241, 'After a crisis, guests and staff should receive', 'single_choice', 4, '[\"No further contact\",\"Follow-up and, where needed, support, since the effect outlasts the event\",\"A discount\",\"A survey\"]', '[\"2\"]', 4),
(2325, 7242, 'RevPAR is', 'single_choice', 4, '[\"Revenue per available room\",\"Revenue per arriving reservation\",\"Rate per available room\",\"Rooms per available rate\"]', '[\"1\"]', 1),
(2326, 7242, 'ADR measures', 'single_choice', 4, '[\"Total revenue divided by rooms available\",\"Room revenue divided by rooms sold\",\"Occupancy times rate\",\"Revenue per guest\"]', '[\"2\"]', 2),
(2327, 7242, 'A hotel with high occupancy and falling RevPAR is likely', 'single_choice', 4, '[\"Performing well\",\"Discounting too heavily to fill rooms\",\"Losing market share\",\"Understaffed\"]', '[\"2\"]', 3),
(2328, 7242, 'GOPPAR is more useful than RevPAR because it', 'single_choice', 4, '[\"Is easier to calculate\",\"Accounts for the cost of earning the revenue, not just the revenue\",\"Excludes departments\",\"Is reported daily\"]', '[\"2\"]', 4),
(2329, 7243, 'A property management system holds', 'single_choice', 4, '[\"Only room rates\",\"Reservations, guest profiles, room status, folios and the night audit\",\"Only housekeeping schedules\",\"Only the booking engine\"]', '[\"2\"]', 1),
(2330, 7243, 'Room status in the PMS should be updated by housekeeping because', 'single_choice', 4, '[\"The front desk cannot sell a room it believes is dirty\",\"It is a legal requirement\",\"It changes the rate\",\"It is not updated\"]', '[\"1\"]', 2),
(2331, 7243, 'A guest profile merged in error causes', 'single_choice', 4, '[\"No problem\",\"Charges and preferences attached to the wrong person, which is both a service and a data protection failure\",\"Faster check-in\",\"A rate change\"]', '[\"2\"]', 3),
(2332, 7243, 'Before overriding a PMS rate, an agent should', 'single_choice', 4, '[\"Override freely\",\"Follow the authorisation rule, because rate overrides are auditable\",\"Ask the guest\",\"Change it back afterwards\"]', '[\"2\"]', 4),
(2333, 7244, 'A channel manager exists to', 'single_choice', 4, '[\"Choose which OTAs to use\",\"Keep rates and availability consistent across every connected channel\",\"Negotiate commission\",\"Handle guest messages\"]', '[\"2\"]', 1),
(2334, 7244, 'Overbooking most often results from', 'single_choice', 4, '[\"Guest error\",\"Inventory not syncing between channels in time\",\"Rate changes\",\"Cancellations\"]', '[\"2\"]', 2),
(2335, 7244, 'Channel mix should be reviewed because', 'single_choice', 4, '[\"Contracts expire\",\"Each channel has a different cost of acquisition, and the mix decides net revenue\",\"OTAs require it\",\"It changes rarely\"]', '[\"2\"]', 3),
(2336, 7244, 'Closing a channel at short notice risks', 'single_choice', 4, '[\"Nothing\",\"Penalties and loss of ranking, so it is a planned decision rather than a reaction\",\"Lower rates\",\"Higher commission\"]', '[\"2\"]', 4),
(2337, 7245, 'The booking engine\'s main commercial purpose is', 'single_choice', 4, '[\"Displaying photographs\",\"Converting a visitor into a direct booking without commission\",\"Managing inventory\",\"Collecting reviews\"]', '[\"2\"]', 1),
(2338, 7245, 'The most common cause of booking abandonment is', 'single_choice', 4, '[\"Room photographs\",\"Unexpected cost or friction appearing late in the flow\",\"Too few room types\",\"Slow email\"]', '[\"2\"]', 2),
(2339, 7245, 'Mobile conversion matters because', 'single_choice', 4, '[\"It is fashionable\",\"A large share of hotel searches happen on a phone, and a poor mobile flow loses them\",\"Desktop is declining\",\"It affects SEO only\"]', '[\"2\"]', 3),
(2340, 7245, 'Rate parity with OTAs should be maintained so that', 'single_choice', 4, '[\"OTAs rank the hotel higher\",\"The direct channel is never more expensive than the commissioned one\",\"The rate is simple\",\"It is legally required everywhere\"]', '[\"2\"]', 4),
(2341, 7246, 'The strongest reason a guest books direct is usually', 'single_choice', 4, '[\"Loyalty points\",\"Confidence that the direct channel gives the best price and terms\",\"Website design\",\"Email offers\"]', '[\"2\"]', 1),
(2342, 7246, 'A direct booking strategy should begin with', 'single_choice', 4, '[\"Discounting below the OTA rate\",\"Making the direct channel at least as good, then making that visible\",\"Closing OTA channels\",\"Paid search only\"]', '[\"2\"]', 2),
(2343, 7246, 'Undercutting OTA rates publicly usually', 'single_choice', 4, '[\"Increases direct share safely\",\"Breaches parity agreements and can cost ranking or the contract\",\"Has no downside\",\"Is the standard approach\"]', '[\"2\"]', 3),
(2344, 7246, 'Direct booking value is measured by', 'single_choice', 4, '[\"Volume alone\",\"Net revenue after acquisition cost, compared with the same booking through an OTA\",\"Conversion rate\",\"Page views\"]', '[\"2\"]', 4),
(2345, 7247, 'OTA commission is best understood as', 'single_choice', 4, '[\"A marketing cost with a measurable return\",\"An unavoidable tax\",\"A fixed fee\",\"A discount to the guest\"]', '[\"1\"]', 1),
(2346, 7247, 'Content on an OTA listing should be', 'single_choice', 4, '[\"Minimal\",\"Complete and accurate, because it drives both ranking and guest expectation\",\"Copied from competitors\",\"Updated annually\"]', '[\"2\"]', 2),
(2347, 7247, 'A poor OTA review should be', 'single_choice', 4, '[\"Ignored\",\"Answered publicly, factually and without argument\",\"Disputed with the OTA\",\"Removed\"]', '[\"2\"]', 3),
(2348, 7247, 'The billboard effect describes', 'single_choice', 4, '[\"OTA advertising spend\",\"Guests finding a hotel on an OTA and then booking direct\",\"Roadside signage\",\"Rate parity\"]', '[\"2\"]', 4),
(2349, 7248, 'A useful metric is one that', 'single_choice', 4, '[\"Is easy to collect\",\"Changes a decision\",\"Looks good in a report\",\"Is tracked by competitors\"]', '[\"2\"]', 1),
(2350, 7248, 'Comparing this month to last month alone is misleading because', 'single_choice', 4, '[\"Months differ in length\",\"Hotel demand is seasonal, so the right comparison is the same period last year\",\"The data is late\",\"It is not misleading\"]', '[\"2\"]', 2),
(2351, 7248, 'Pace reporting shows', 'single_choice', 4, '[\"How fast the website loads\",\"How bookings for a future date are building compared with the same point last year\",\"Staff productivity\",\"Channel cost\"]', '[\"2\"]', 3),
(2352, 7248, 'A dashboard with fifty metrics usually', 'single_choice', 4, '[\"Gives the fullest picture\",\"Hides the few numbers that actually drive action\",\"Is best practice\",\"Is easier to read\"]', '[\"2\"]', 4),
(2353, 7249, 'Hotel marketing spend should be judged on', 'single_choice', 4, '[\"Impressions\",\"Revenue generated against cost, by channel\",\"Follower growth\",\"Click volume\"]', '[\"2\"]', 1),
(2354, 7249, 'The most valuable owned channel for a hotel is usually', 'single_choice', 4, '[\"Social media\",\"The guest email list, because it is direct and costs nothing per send\",\"Paid search\",\"Display advertising\"]', '[\"2\"]', 2),
(2355, 7249, 'Photography matters commercially because', 'single_choice', 4, '[\"It fills the website\",\"It is the single biggest driver of whether a listing converts\",\"It is cheap\",\"It supports SEO\"]', '[\"2\"]', 3),
(2356, 7249, 'Marketing to past guests works because', 'single_choice', 4, '[\"They are easy to reach\",\"They convert at a far higher rate and cost less to reach than new prospects\",\"They expect discounts\",\"It is required\"]', '[\"2\"]', 4),
(2357, 7250, 'For a hotel, the highest-value organic search terms are usually', 'single_choice', 4, '[\"Generic terms like \\\"hotel\\\"\",\"Location plus intent, such as \\\"hotel near Riyadh airport\\\"\",\"Brand terms only\",\"Competitor names\"]', '[\"2\"]', 1),
(2358, 7250, 'A Google Business Profile matters because', 'single_choice', 4, '[\"It replaces the website\",\"It is often the first and sometimes only result a local searcher sees\",\"It improves rankings directly\",\"It is required\"]', '[\"2\"]', 2),
(2359, 7250, 'Duplicate descriptions copied from an OTA harm the site because', 'single_choice', 4, '[\"The OTA objects\",\"Search engines have no reason to rank a page that adds nothing new\",\"They are too long\",\"They do not harm it\"]', '[\"2\"]', 3),
(2360, 7250, 'Page speed affects hotel SEO mainly through', 'single_choice', 4, '[\"Keyword ranking alone\",\"Users abandoning a slow page, which search engines observe\",\"Image quality\",\"Server cost\"]', '[\"2\"]', 4),
(2361, 7251, 'The most important thing to do with a negative review is', 'single_choice', 4, '[\"Dispute it\",\"Respond factually, and fix the cause if it is real\",\"Ignore it\",\"Ask for its removal\"]', '[\"2\"]', 1),
(2362, 7251, 'Review volume matters alongside score because', 'single_choice', 4, '[\"It affects commission\",\"A high score on very few reviews is not yet evidence\",\"It improves rate\",\"It does not matter\"]', '[\"2\"]', 2),
(2363, 7251, 'Asking every guest for a review is', 'single_choice', 4, '[\"Against policy everywhere\",\"Reasonable, provided it is not selective about who is asked\",\"Only for happy guests\",\"Ineffective\"]', '[\"2\"]', 3),
(2364, 7251, 'A pattern in reviews is more useful than any single review because', 'single_choice', 4, '[\"It is easier to read\",\"It points at a process that is repeatedly failing\",\"It is more recent\",\"It affects ranking more\"]', '[\"2\"]', 4),
(2365, 7252, 'When choosing hotel technology, integration matters because', 'single_choice', 4, '[\"It reduces licence cost\",\"Systems that cannot exchange data create manual work and errors\",\"It is a vendor requirement\",\"It speeds up training\"]', '[\"2\"]', 1),
(2366, 7252, 'Guest data held in a hotel system must be', 'single_choice', 4, '[\"Shared freely with partners\",\"Protected, with access limited to those who need it for their work\",\"Deleted monthly\",\"Stored locally only\"]', '[\"2\"]', 2),
(2367, 7252, 'The main risk in replacing a core system is', 'single_choice', 4, '[\"Cost\",\"Data migration and the period where staff know neither system well\",\"Vendor support\",\"Hardware\"]', '[\"2\"]', 3),
(2368, 7252, 'A technology decision should be led by', 'single_choice', 4, '[\"The IT supplier\",\"The operational problem it is meant to solve\",\"The lowest price\",\"What competitors use\"]', '[\"2\"]', 4),
(2369, 7919, 'A guest arrives at 11:00 and the room is not ready. What does the agent do first?', 'single_choice', 4, '[\"Tell the guest to come back at check-in time\",\"Acknowledge it, offer luggage storage and give a specific time the room will be ready\",\"Upgrade the guest to a suite at no charge\",\"Check the guest in anyway and let them wait in the corridor\"]', '[\"2\"]', 1),
(2370, 7919, 'What does the front office hand over at shift change?', 'single_choice', 4, '[\"Only the cash float\",\"Pending arrivals, guest requests still open, out-of-order rooms and anything unresolved\",\"Nothing, the system holds all of it\",\"Only complaints\"]', '[\"2\"]', 2),
(2371, 7919, 'Which department does the front desk depend on most to sell a clean room?', 'single_choice', 4, '[\"Engineering\",\"Housekeeping\",\"Finance\",\"Sales\"]', '[\"2\"]', 3),
(2372, 7919, 'A guest asks a question the agent cannot answer. The correct response is to', 'single_choice', 4, '[\"Guess, so the guest is not kept waiting\",\"Say it is not your department\",\"Say you will find out, give a time, and come back with the answer\",\"Refer them to the website\"]', '[\"3\"]', 4),
(2373, 7920, 'A walk-in guest arrives when the hotel is full. The agent should', 'single_choice', 4, '[\"Turn them away\",\"Check for cancellations, then help them find a room nearby if there is genuinely nothing\",\"Put them in an out-of-order room\",\"Ask them to wait indefinitely\"]', '[\"2\"]', 1),
(2374, 7920, 'The arrivals list is checked at the start of a shift to', 'single_choice', 4, '[\"Count staff\",\"Know who is coming, what they have asked for and which rooms are committed\",\"Set room rates\",\"Order breakfast\"]', '[\"2\"]', 2),
(2375, 7920, 'A reservation taken by phone must be read back because', 'single_choice', 4, '[\"It is polite\",\"It catches errors in dates, room type and spelling before they become a problem at arrival\",\"The system requires it\",\"It is not read back\"]', '[\"2\"]', 3),
(2376, 7920, 'Which of these is a front desk responsibility at every shift?', 'single_choice', 4, '[\"Counting and signing for the cash float\",\"Cleaning guest rooms\",\"Cooking breakfast\",\"Fixing air conditioning\"]', '[\"1\"]', 4),
(2377, 7921, 'What must be verified before a room key is issued?', 'single_choice', 4, '[\"The guest\'s identity against the reservation\",\"The guest\'s social media\",\"Nothing, the booking is enough\",\"Only the payment card\"]', '[\"1\"]', 1),
(2378, 7921, 'A guest booked a twin room and arrives expecting a double. What is the correct step?', 'single_choice', 4, '[\"Insist the booking is correct and move on\",\"Check availability for a double, explain the options and confirm before moving them\",\"Move them without telling them\",\"Charge a change fee first\"]', '[\"2\"]', 2),
(2379, 7921, 'Rooming a guest means', 'single_choice', 4, '[\"Leaving them to find the room themselves\",\"Escorting them and showing how the room works, then confirming they have what they need\",\"Sending a bellman with the luggage only\",\"Calling the room after ten minutes\"]', '[\"2\"]', 3),
(2380, 7921, 'When should the guest be told the checkout time?', 'single_choice', 4, '[\"Never, it is on the door\",\"At check-in, along with breakfast times and Wi-Fi\",\"Only if they ask\",\"On the morning of departure\"]', '[\"2\"]', 4),
(2381, 7922, 'A guest disputes a minibar charge at checkout. What is the first step?', 'single_choice', 4, '[\"Remove it immediately without checking\",\"Insist the charge stands\",\"Check the posting with housekeeping before deciding, and keep the guest informed\",\"Ask the guest to email the hotel later\"]', '[\"3\"]', 1),
(2382, 7922, 'What should be offered at the end of every checkout?', 'single_choice', 4, '[\"A discount voucher\",\"An itemised folio and help with onward travel or luggage\",\"A review request only\",\"Nothing\"]', '[\"2\"]', 2),
(2383, 7922, 'A late checkout request should be answered by', 'single_choice', 4, '[\"Refusing automatically\",\"Checking the arrivals for that room type before committing\",\"Always agreeing\",\"Charging a full extra night in every case\"]', '[\"2\"]', 3),
(2384, 7922, 'Why does the folio need to be accurate before the guest leaves?', 'single_choice', 4, '[\"It is easier to correct in person than after departure\",\"It is a legal requirement in every country\",\"It changes the room rate\",\"It is not important\"]', '[\"1\"]', 4),
(2385, 7923, 'The guest folio is', 'single_choice', 4, '[\"The room key record\",\"The running account of every charge and payment for that stay\",\"The housekeeping report\",\"The reservation confirmation\"]', '[\"2\"]', 1),
(2386, 7923, 'Which details must be captured at registration in Saudi Arabia?', 'single_choice', 4, '[\"Name only\",\"Identity document details as required by law, plus contact and payment\",\"Nothing, the booking suffices\",\"Social media handle\"]', '[\"2\"]', 2),
(2387, 7923, 'A registration card signed by the guest establishes', 'single_choice', 4, '[\"The guest\'s agreement to the rate and the hotel\'s terms\",\"The housekeeping schedule\",\"The loyalty tier\",\"Nothing legally\"]', '[\"1\"]', 3),
(2388, 7923, 'Where a guest declines to give required identity details, the agent should', 'single_choice', 4, '[\"Check them in anyway\",\"Explain that it is a legal requirement and involve the duty manager if it is refused\",\"Refuse service without explanation\",\"Copy details from a previous stay\"]', '[\"2\"]', 4),
(2389, 7924, 'Which guest should be prioritised when assigning the best available room?', 'single_choice', 4, '[\"The latest booker\",\"Guests with an accessibility requirement, then VIP and repeat guests\",\"Whoever complains most\",\"The cheapest rate\"]', '[\"2\"]', 1),
(2390, 7924, 'An accessible room should be held for', 'single_choice', 4, '[\"Anyone, it is a normal room\",\"A guest who has requested one, until it is clear none is needed\",\"Staff use\",\"Group bookings\"]', '[\"2\"]', 2),
(2391, 7924, 'A room marked out of order should be', 'single_choice', 4, '[\"Sold at a discount\",\"Kept out of inventory until engineering releases it\",\"Assigned to a late arrival\",\"Cleaned and sold\"]', '[\"2\"]', 3),
(2392, 7924, 'Why are connecting rooms held back during a family-heavy arrival day?', 'single_choice', 4, '[\"They are harder to clean\",\"They are the only option for families travelling with children and are quickly exhausted\",\"They cost more\",\"They are not held back\"]', '[\"2\"]', 4),
(2393, 7925, 'A guest asks for a restaurant recommendation. The best answer', 'single_choice', 4, '[\"Names the hotel restaurant only\",\"Asks what they are in the mood for, then gives two or three options with reasons\",\"Hands them a directory\",\"Names the most expensive option\"]', '[\"2\"]', 1),
(2394, 7925, 'The bell desk is responsible for', 'single_choice', 4, '[\"Room cleaning\",\"Luggage handling, storage and delivery, and assisting arrivals and departures\",\"Billing\",\"Reservations\"]', '[\"2\"]', 2),
(2395, 7925, 'When storing luggage, the item must be', 'single_choice', 4, '[\"Left in the lobby\",\"Tagged with a receipt given to the guest, and stored securely\",\"Kept behind the desk untagged\",\"Taken to the guest room\"]', '[\"2\"]', 3),
(2396, 7925, 'A concierge who cannot arrange a request should', 'single_choice', 4, '[\"Say it is impossible\",\"Offer the nearest alternative and be clear about what can and cannot be done\",\"Promise and then not deliver\",\"Refer the guest to reception\"]', '[\"2\"]', 4),
(2397, 7926, 'A guest is angry about noise from the room above. What comes first?', 'single_choice', 4, '[\"Explain the hotel policy\",\"Listen without interrupting, acknowledge the problem and apologise for the effect on them\",\"Offer a free night\",\"Ask them to put it in writing\"]', '[\"2\"]', 1),
(2398, 7926, 'What does LEARN stand for in complaint handling?', 'single_choice', 4, '[\"Listen, Empathise, Apologise, React, Notify\",\"Leave, Escalate, Argue, Refuse, Note\",\"Log, Email, Assign, Review, Notify\",\"Listen, Explain, Argue, Refund, Note\"]', '[\"1\"]', 2),
(2399, 7926, 'When a complaint cannot be resolved by the agent, the correct action is', 'single_choice', 4, '[\"Tell the guest nothing can be done\",\"Escalate to the duty manager with the facts, and tell the guest who will contact them and when\",\"Give the guest the manager\'s mobile number\",\"Wait until the next shift\"]', '[\"2\"]', 3),
(2400, 7926, 'Why is every complaint logged, even one resolved on the spot?', 'single_choice', 4, '[\"To justify refusing a refund later\",\"So repeat causes can be found and fixed\",\"It is not logged if resolved\",\"To record which staff member was at fault\"]', '[\"2\"]', 4),
(2401, 7927, 'A returning guest\'s preferences should be', 'single_choice', 4, '[\"Asked again every stay as if new\",\"Held on the profile and acted on before arrival\",\"Guessed\",\"Ignored\"]', '[\"2\"]', 1),
(2402, 7927, 'A VIP arrival is prepared by', 'single_choice', 4, '[\"Doing nothing different\",\"Checking the room personally, confirming amenities are placed and briefing the team who will meet them\",\"Assigning any available room\",\"Upgrading automatically\"]', '[\"2\"]', 2),
(2403, 7927, 'Recognising a repeat guest by name at arrival matters because', 'single_choice', 4, '[\"It is required by law\",\"It is the clearest signal that the hotel remembers them, and it costs nothing\",\"It speeds up check-in\",\"It does not matter\"]', '[\"2\"]', 3),
(2404, 7927, 'A VIP complaint should be handled', 'single_choice', 4, '[\"The same as any other, with the duty manager informed early\",\"By giving whatever is asked for\",\"By ignoring the normal process\",\"By the general manager only\"]', '[\"1\"]', 4),
(2405, 7928, 'Within how many rings should an internal call be answered as a standard?', 'single_choice', 4, '[\"Three\",\"Eight\",\"Fifteen\",\"It does not matter\"]', '[\"1\"]', 1),
(2406, 7928, 'The correct greeting on answering an external call includes', 'single_choice', 4, '[\"Just \\\"hello\\\"\",\"The hotel name, the department, your name and an offer of help\",\"Only your name\",\"The room number\"]', '[\"2\"]', 2),
(2407, 7928, 'Before placing a caller on hold you should', 'single_choice', 4, '[\"Put them on hold immediately\",\"Ask permission, explain why, and thank them when you return\",\"Transfer them instead\",\"Tell them to call back\"]', '[\"2\"]', 3),
(2408, 7928, 'A caller asks to be put through to a guest room. The agent should', 'single_choice', 4, '[\"Connect without confirming anything\",\"Ask for the guest name, and connect without revealing the room number\",\"Give the room number so the caller can dial direct\",\"Refuse all such calls\"]', '[\"2\"]', 4),
(2409, 7929, 'The best moment to offer a room upgrade is', 'single_choice', 4, '[\"After the guest has paid and left the desk\",\"At check-in, once you know what the guest is here for\",\"By email a week later\",\"At checkout\"]', '[\"2\"]', 1),
(2410, 7929, 'An effective upsell is based on', 'single_choice', 4, '[\"The highest priced room\",\"A benefit that matches what the guest said they need\",\"Pressure\",\"A script read word for word\"]', '[\"2\"]', 2),
(2411, 7929, 'A guest declines the upgrade. The agent should', 'single_choice', 4, '[\"Ask again immediately\",\"Accept it gracefully and continue the check-in normally\",\"Note them as difficult\",\"Offer a discount on the same room\"]', '[\"2\"]', 3),
(2412, 7929, 'Why does upselling fail when the guest is tired and late?', 'single_choice', 4, '[\"It does not fail\",\"The guest wants the room, not a decision, and pressing reads as an obstacle\",\"The system blocks it\",\"Rates change at night\"]', '[\"2\"]', 4),
(2413, 7930, 'The night audit exists to', 'single_choice', 4, '[\"Clean the lobby\",\"Close the financial day, post room and tax charges and reconcile the day\'s revenue\",\"Prepare breakfast\",\"Reset the key system\"]', '[\"2\"]', 1),
(2414, 7930, 'A discrepancy found during the audit should be', 'single_choice', 4, '[\"Corrected silently\",\"Documented with the correction and passed to the accounts team\",\"Left for the morning shift\",\"Ignored if it is small\"]', '[\"2\"]', 2),
(2415, 7930, 'Rooms still showing as occupied after the expected departure should be', 'single_choice', 4, '[\"Charged automatically\",\"Checked against housekeeping status before any charge is raised\",\"Released without checking\",\"Reported to the police\"]', '[\"2\"]', 3),
(2416, 7930, 'Why is the audit run at night?', 'single_choice', 4, '[\"Staff are cheaper\",\"It is the quietest point of the trading day, so the books can be closed against a stable position\",\"It is a legal requirement\",\"The system is faster\"]', '[\"2\"]', 4),
(2417, 7931, 'A caller asks whether a named guest is staying at the hotel. The correct answer is', 'single_choice', 4, '[\"Confirm and put the call through\",\"Neither confirm nor deny that the guest is in house\",\"Confirm but refuse to connect\",\"Give the room number only\"]', '[\"2\"]', 1),
(2418, 7931, 'Under the Saudi Personal Data Protection Law, guest data may be used', 'single_choice', 4, '[\"For any purpose the hotel chooses\",\"Only for the purpose it was collected for, unless the guest consents to more\",\"Freely once the guest has checked out\",\"For marketing by default\"]', '[\"2\"]', 2),
(2419, 7931, 'A printed arrivals list left on the desk is a problem because', 'single_choice', 4, '[\"It wastes paper\",\"It exposes guest names and room numbers to anyone passing\",\"It is out of date quickly\",\"It is not a problem\"]', '[\"2\"]', 3),
(2420, 7931, 'A guest asks what data the hotel holds about them. The correct response is', 'single_choice', 4, '[\"Refuse, it is internal\",\"Follow the hotel\'s data request procedure, which gives the guest a right to know\",\"Read it out from the screen immediately\",\"Tell them no data is held\"]', '[\"2\"]', 4),
(2421, 7932, 'What does a room attendant do before entering a guest room?', 'single_choice', 4, '[\"Enter using the key immediately\",\"Knock, announce \\\"housekeeping\\\", wait, repeat, then enter announcing again\",\"Call the guest from reception\",\"Wait for the guest to leave the floor\"]', '[\"2\"]', 1),
(2422, 7932, 'The housekeeping control desk is responsible for', 'single_choice', 4, '[\"Cooking\",\"Coordinating room status, assignments, keys and guest requests across the floors\",\"Billing guests\",\"Checking guests in\"]', '[\"2\"]', 2),
(2423, 7932, 'A room reported as \"clean\" but not inspected should be', 'single_choice', 4, '[\"Sold immediately\",\"Held until inspected, if the standard requires inspection before release\",\"Reported as out of order\",\"Cleaned again\"]', '[\"2\"]', 3),
(2424, 7932, 'Why is the cleaning sequence fixed rather than left to preference?', 'single_choice', 4, '[\"It is faster to supervise\",\"A fixed order prevents steps being missed and stops clean surfaces being recontaminated\",\"It is not fixed\",\"It saves chemicals\"]', '[\"2\"]', 4),
(2425, 7933, 'In what order should a guest room be cleaned?', 'single_choice', 4, '[\"Bathroom first, then bedroom, then floor\",\"Top to bottom and clean to dirty, finishing with the floor\",\"Floor first\",\"Whatever is quickest\"]', '[\"2\"]', 1),
(2426, 7933, 'Cloths are colour coded so that', 'single_choice', 4, '[\"They look tidy\",\"A cloth used in the toilet is never used on a surface a guest touches\",\"They match the uniform\",\"They are easier to count\"]', '[\"2\"]', 2),
(2427, 7933, 'A guest\'s personal belongings found during cleaning should be', 'single_choice', 4, '[\"Moved to a drawer\",\"Left where they are, tidied around but not handled or moved unnecessarily\",\"Put in lost and found\",\"Photographed\"]', '[\"2\"]', 3),
(2428, 7933, 'A departure room differs from a stayover room mainly because', 'single_choice', 4, '[\"It takes less time\",\"Everything is stripped and replaced, and the room is reset to a sellable standard\",\"Only the bed is made\",\"It needs no inspection\"]', '[\"2\"]', 4),
(2429, 7934, 'Linen should be changed on a stayover', 'single_choice', 4, '[\"Never\",\"According to the hotel standard, and always on request or when soiled\",\"Only at departure\",\"Every third day regardless\"]', '[\"2\"]', 1),
(2430, 7934, 'Stripped linen should be', 'single_choice', 4, '[\"Placed on the floor\",\"Placed directly into the linen bag on the trolley, never on the floor or furniture\",\"Left on the chair\",\"Shaken out in the room\"]', '[\"2\"]', 2),
(2431, 7934, 'Why is bed linen not shaken out in a guest room?', 'single_choice', 4, '[\"It creases\",\"It disperses dust and any contamination into the air the guest will breathe\",\"It takes longer\",\"It is allowed\"]', '[\"2\"]', 3),
(2432, 7934, 'A mattress protector is checked at every departure because', 'single_choice', 4, '[\"It is decorative\",\"A soiled protector means the mattress may be affected and must be dealt with before the room is sold\",\"It is not checked\",\"Guests ask about it\"]', '[\"2\"]', 4),
(2433, 7935, 'Which is cleaned last in a bathroom?', 'single_choice', 4, '[\"The mirror\",\"The toilet\",\"The basin\",\"The shower\"]', '[\"2\"]', 1),
(2434, 7935, 'A cloth used on the toilet may then be used on', 'single_choice', 4, '[\"The basin\",\"The mirror\",\"Nothing else, it is removed from service\",\"The bath\"]', '[\"3\"]', 2),
(2435, 7935, 'Contact time for a disinfectant means', 'single_choice', 4, '[\"How long it takes to apply\",\"The time the surface must stay wet for the product to work\",\"How long the bottle lasts\",\"The drying time\"]', '[\"2\"]', 3),
(2436, 7935, 'Bathroom amenities are replenished', 'single_choice', 4, '[\"Only at departure\",\"To the standard set for the room type, at every service\",\"When the guest asks\",\"Never\"]', '[\"2\"]', 4),
(2437, 7936, 'Room inspection exists to', 'single_choice', 4, '[\"Catch staff out\",\"Confirm the room meets the standard before it is sold, and find what training is needed\",\"Slow the release of rooms\",\"Satisfy the guest\"]', '[\"2\"]', 1),
(2438, 7936, 'An inspector finding a repeated fault across several rooms should', 'single_choice', 4, '[\"Fix it quietly\",\"Record it and raise it as a training or process issue, not just a room issue\",\"Ignore it\",\"Report the attendant\"]', '[\"2\"]', 2),
(2439, 7936, 'A room failing inspection is', 'single_choice', 4, '[\"Sold anyway\",\"Returned for correction and re-inspected before release\",\"Marked out of order\",\"Released with a note\"]', '[\"2\"]', 3),
(2440, 7936, 'Which is checked in an inspection but easily missed in cleaning?', 'single_choice', 4, '[\"The bed\",\"High and low surfaces, behind doors, and the underside of fittings\",\"The floor\",\"The towels\"]', '[\"2\"]', 4),
(2441, 7937, 'An item found in a departed room must be', 'single_choice', 4, '[\"Kept by the finder\",\"Logged with the room, date and finder, and stored securely\",\"Left in the room\",\"Thrown away\"]', '[\"2\"]', 1),
(2442, 7937, 'A guest calls about an item left behind. The correct step is', 'single_choice', 4, '[\"Say nothing was found\",\"Check the log, and arrange return at the guest\'s cost if it is there\",\"Post it immediately without checking\",\"Ask them to return\"]', '[\"2\"]', 2),
(2443, 7937, 'High-value items such as passports and jewellery should be', 'single_choice', 4, '[\"Stored with everything else\",\"Stored in the safe and reported to the duty manager the same day\",\"Returned to the room\",\"Held by the attendant\"]', '[\"2\"]', 3),
(2444, 7937, 'Unclaimed items are disposed of', 'single_choice', 4, '[\"Immediately\",\"After the retention period set by hotel policy, with the disposal recorded\",\"Never\",\"By the finder\"]', '[\"2\"]', 4),
(2445, 7938, 'Clean and soiled linen must be', 'single_choice', 4, '[\"Transported together to save time\",\"Kept separate at every stage, including transport and storage\",\"Stored in the same room\",\"Sorted by the guest\"]', '[\"2\"]', 1),
(2446, 7938, 'Linen stained with blood or bodily fluid is', 'single_choice', 4, '[\"Washed with the normal load\",\"Handled as infectious, bagged separately and washed to the required temperature\",\"Discarded\",\"Soaked in the room\"]', '[\"2\"]', 2),
(2447, 7938, 'Par stock for linen means', 'single_choice', 4, '[\"The cheapest supplier\",\"The quantity needed to keep every bed supplied while other sets are in circulation\",\"The stock in the laundry\",\"One set per bed\"]', '[\"2\"]', 3),
(2448, 7938, 'Overloading a washing machine results in', 'single_choice', 4, '[\"Faster cycles\",\"Linen that is not properly cleaned or rinsed, and more rewashing\",\"Lower cost\",\"No effect\"]', '[\"2\"]', 4),
(2449, 7939, 'A wet floor in a public area requires', 'single_choice', 4, '[\"No action if it is small\",\"A warning sign in place for as long as the floor is wet\",\"Closing the area\",\"Only a verbal warning\"]', '[\"2\"]', 1),
(2450, 7939, 'Public areas are cleaned on a frequency based on', 'single_choice', 4, '[\"Convenience\",\"Traffic and visibility, with high-touch points done most often\",\"Cost\",\"Guest complaints only\"]', '[\"2\"]', 2),
(2451, 7939, 'High-touch points in a lobby include', 'single_choice', 4, '[\"The ceiling\",\"Door handles, lift buttons, handrails and counter edges\",\"The carpet centre\",\"Artwork\"]', '[\"2\"]', 3),
(2452, 7939, 'Cleaning a public area during peak hours should', 'single_choice', 4, '[\"Proceed as normal\",\"Be limited to what can be done without obstructing guests, with the rest rescheduled\",\"Be skipped entirely\",\"Close the area\"]', '[\"2\"]', 4),
(2453, 7940, 'Deep cleaning differs from daily cleaning because it', 'single_choice', 4, '[\"Is faster\",\"Addresses what daily cleaning cannot reach, on a planned cycle\",\"Uses no chemicals\",\"Is done by the front desk\"]', '[\"2\"]', 1),
(2454, 7940, 'A room scheduled for deep cleaning should be', 'single_choice', 4, '[\"Sold as normal\",\"Blocked from sale for the time the work needs\",\"Cleaned around the guest\",\"Left until it is quiet\"]', '[\"2\"]', 2),
(2455, 7940, 'Deep cleaning is planned on a cycle because', 'single_choice', 4, '[\"It is cheaper\",\"Condition declines predictably, and planned work is cheaper than replacement\",\"Guests request it\",\"It is not planned\"]', '[\"2\"]', 3),
(2456, 7940, 'Which is a deep cleaning task rather than a daily one?', 'single_choice', 4, '[\"Making the bed\",\"Shampooing carpet and cleaning behind and under furniture\",\"Emptying the bin\",\"Replacing towels\"]', '[\"2\"]', 4),
(2457, 7941, 'Two cleaning chemicals should never be mixed because', 'single_choice', 4, '[\"It wastes product\",\"Some combinations, such as bleach and acid cleaners, release toxic gas\",\"It changes the colour\",\"It is allowed if diluted\"]', '[\"2\"]', 1),
(2458, 7941, 'Dilution rates are taken from', 'single_choice', 4, '[\"Experience\",\"The manufacturer\'s instructions and the product data sheet\",\"The strongest that works\",\"The supervisor\'s preference\"]', '[\"2\"]', 2),
(2459, 7941, 'A chemical decanted into a second container must be', 'single_choice', 4, '[\"Left unlabelled\",\"Labelled with the product name and its hazards\",\"Marked only with a colour\",\"Used the same day\"]', '[\"2\"]', 3),
(2460, 7941, 'The safety data sheet for a product tells you', 'single_choice', 4, '[\"The price\",\"The hazards, the protective equipment needed and what to do in an exposure\",\"The supplier address only\",\"Nothing useful\"]', '[\"2\"]', 4),
(2461, 7942, 'Room turnaround time is measured from', 'single_choice', 4, '[\"The guest\'s departure to the room being sellable again\",\"Check-in to checkout\",\"The start to the end of a shift\",\"The booking to the arrival\"]', '[\"1\"]', 1),
(2462, 7942, 'The biggest cause of slow turnaround on a busy departure day is usually', 'single_choice', 4, '[\"Slow attendants\",\"Rooms not being reported as vacant promptly, so cleaning starts late\",\"Too much linen\",\"Guests checking out early\"]', '[\"2\"]', 2),
(2463, 7942, 'Priority rooms in the turnaround queue are', 'single_choice', 4, '[\"The nearest to the linen room\",\"Those with a confirmed early arrival or a guest waiting\",\"The largest rooms\",\"The cheapest rooms\"]', '[\"2\"]', 3),
(2464, 7942, 'Rushing a turnaround typically costs the hotel more because', 'single_choice', 4, '[\"It uses more chemicals\",\"A room released below standard generates a complaint, a move and a refund\",\"It does not cost more\",\"Staff work overtime\"]', '[\"2\"]', 4),
(2465, 7943, 'A trolley is stocked before the shift so that', 'single_choice', 4, '[\"It looks tidy\",\"The attendant does not lose time returning to the store mid-room\",\"It is easier to push\",\"The supervisor can check it\"]', '[\"2\"]', 1),
(2466, 7943, 'Productivity in housekeeping is measured against', 'single_choice', 4, '[\"Rooms per hour alone\",\"Rooms cleaned to standard per hour, since a fast room that fails inspection is not done\",\"Chemicals used\",\"Hours worked\"]', '[\"2\"]', 2),
(2467, 7943, 'Which change most reliably improves productivity?', 'single_choice', 4, '[\"Working faster\",\"Removing interruptions and having the right supplies to hand\",\"Shorter breaks\",\"More staff\"]', '[\"2\"]', 3),
(2468, 7943, 'A room attendant consistently over time should first be', 'single_choice', 4, '[\"Disciplined\",\"Observed, to find whether the cause is method, supplies or the rooms assigned\",\"Reassigned\",\"Given fewer rooms\"]', '[\"2\"]', 4),
(2469, 7944, 'From which side is a plated dish normally served?', 'single_choice', 4, '[\"The guest\'s left, and cleared from the right\",\"The guest\'s right always\",\"Whichever is convenient\",\"Over the guest\'s shoulder\"]', '[\"1\"]', 1),
(2470, 7944, 'A guest at the table has not received their dish while others are eating. The server should', 'single_choice', 4, '[\"Say nothing\",\"Acknowledge it at once, check with the kitchen and give the guest a time\",\"Offer a free dessert\",\"Remove the other plates\"]', '[\"2\"]', 2),
(2471, 7944, 'Plates are cleared when', 'single_choice', 4, '[\"The first guest finishes\",\"Everyone at the table has finished\",\"The kitchen asks\",\"After thirty minutes\"]', '[\"2\"]', 3),
(2472, 7944, 'Carrying a tray, the server should', 'single_choice', 4, '[\"Hold it at chest height across the body\",\"Balance it on the flat palm and forearm, away from the body, loaded heaviest in the centre\",\"Carry it with both hands in front\",\"Rest it on the hip\"]', '[\"2\"]', 4),
(2473, 7945, 'A guest arriving without a reservation at a full restaurant should be', 'single_choice', 4, '[\"Turned away\",\"Given a realistic wait time and the option to wait or book another time\",\"Seated at a reserved table\",\"Asked to come back\"]', '[\"2\"]', 1),
(2474, 7945, 'Within how long should an arriving guest be acknowledged?', 'single_choice', 4, '[\"Thirty seconds, even if the host cannot seat them yet\",\"Five minutes\",\"When a table is free\",\"It does not matter\"]', '[\"1\"]', 2),
(2475, 7945, 'Seating a guest includes', 'single_choice', 4, '[\"Pointing to a table\",\"Escorting them, presenting the menu and telling them who will serve them\",\"Nothing more than showing the table\",\"Taking the order\"]', '[\"2\"]', 3),
(2476, 7945, 'A guest with a mobility aid should be seated', 'single_choice', 4, '[\"Wherever is free\",\"Where they can reach the table without obstruction, asked rather than assumed\",\"Near the door always\",\"At the back\"]', '[\"2\"]', 4),
(2477, 7946, 'In American style service, the food is', 'single_choice', 4, '[\"Carved at the table\",\"Plated in the kitchen and brought to the guest\",\"Served from a platter to the guest\'s plate\",\"Placed in the centre to share\"]', '[\"2\"]', 1),
(2478, 7946, 'Silver service differs in that the server', 'single_choice', 4, '[\"Plates in the kitchen\",\"Transfers food from a platter to the guest\'s plate at the table\",\"Leaves the platter with the guest\",\"Does not serve at all\"]', '[\"2\"]', 2),
(2479, 7946, 'Cutlery is laid', 'single_choice', 4, '[\"In any order\",\"From the outside in, in the order the courses will be eaten\",\"All on the right\",\"After the guest sits\"]', '[\"2\"]', 3),
(2480, 7946, 'The cover is checked before service to confirm', 'single_choice', 4, '[\"The bill is ready\",\"Everything is clean, matched, correctly spaced and free of marks\",\"The guest has arrived\",\"The menu is printed\"]', '[\"2\"]', 4),
(2481, 7947, 'Hot food held for service must be kept at or above', 'single_choice', 4, '[\"50°C\",\"60°C\",\"45°C\",\"37°C\"]', '[\"2\"]', 1),
(2482, 7947, 'A server notices a dish has been on the pass for twenty minutes. They should', 'single_choice', 4, '[\"Serve it quickly\",\"Not serve it, and tell the kitchen so it is replaced\",\"Reheat it under the lamp\",\"Serve it with an apology\"]', '[\"2\"]', 2),
(2483, 7947, 'A guest declares a nut allergy. The server must', 'single_choice', 4, '[\"Suggest dishes they think are safe\",\"Inform the kitchen, confirm with them, and not guess about any ingredient\",\"Say all food is safe\",\"Ask the guest to choose carefully\"]', '[\"2\"]', 3),
(2484, 7947, 'Cross-contamination in the service area most often happens through', 'single_choice', 4, '[\"The menu\",\"Hands, cloths and shared utensils moving between raw and ready-to-eat items\",\"The floor\",\"The till\"]', '[\"2\"]', 4),
(2485, 7948, 'HACCP stands for', 'single_choice', 4, '[\"Hotel and Catering Cleaning Procedure\",\"Hazard Analysis and Critical Control Points\",\"Health and Catering Control Plan\",\"Hygiene Assessment of Cooking and Chilling Practice\"]', '[\"2\"]', 1),
(2486, 7948, 'A critical control point is', 'single_choice', 4, '[\"Any step in the process\",\"A step where control is essential to prevent or eliminate a hazard\",\"The final inspection\",\"The delivery point\"]', '[\"2\"]', 2),
(2487, 7948, 'A critical limit is', 'single_choice', 4, '[\"The maximum number of guests\",\"The measurable boundary, such as a temperature, that separates safe from unsafe\",\"The budget\",\"The shelf life\"]', '[\"2\"]', 3),
(2488, 7948, 'When monitoring shows a critical limit has been breached,', 'single_choice', 4, '[\"Note it and continue\",\"Take the corrective action set out in the plan and record what was done\",\"Discard the record\",\"Inform the guest\"]', '[\"2\"]', 4),
(2489, 7949, 'Hands must be washed', 'single_choice', 4, '[\"At the start of the shift only\",\"After any task that could contaminate them, and between handling different foods\",\"Once an hour\",\"Only after the toilet\"]', '[\"2\"]', 1),
(2490, 7949, 'A server with vomiting or diarrhoea must', 'single_choice', 4, '[\"Work with gloves\",\"Report it and stay away from food handling until clear for the required period\",\"Work away from the kitchen\",\"Take medication and continue\"]', '[\"2\"]', 2),
(2491, 7949, 'A cut on the hand must be', 'single_choice', 4, '[\"Left uncovered\",\"Covered with a coloured waterproof dressing, and a glove worn over it\",\"Covered with any plaster\",\"Reason to go home\"]', '[\"2\"]', 3),
(2492, 7949, 'Jewellery is restricted in food areas because', 'single_choice', 4, '[\"It looks unprofessional\",\"It harbours bacteria and can fall into food\",\"It is expensive\",\"It is not restricted\"]', '[\"2\"]', 4),
(2493, 7950, 'Beverages are served', 'single_choice', 4, '[\"Before the guest orders\",\"From the guest\'s right, without reaching across\",\"From the left always\",\"By placing the tray on the table\"]', '[\"2\"]', 1),
(2494, 7950, 'A guest orders an alcoholic drink in a venue that does not serve alcohol. The server should', 'single_choice', 4, '[\"Argue\",\"Explain politely that it is not served and offer the alternatives available\",\"Ignore the request\",\"Send them elsewhere\"]', '[\"2\"]', 2),
(2495, 7950, 'Glassware is handled', 'single_choice', 4, '[\"By the rim\",\"By the stem or the base, never the rim\",\"With a cloth over the top\",\"However is fastest\"]', '[\"2\"]', 3),
(2496, 7950, 'A drink is checked before it leaves the bar for', 'single_choice', 4, '[\"Price\",\"Correct glass, correct garnish, correct level and a clean exterior\",\"Temperature only\",\"Nothing\"]', '[\"2\"]', 4),
(2497, 7951, 'The banquet event order exists to', 'single_choice', 4, '[\"Price the event\",\"Tell every department exactly what is required, when and where\",\"Record complaints\",\"Book the room\"]', '[\"2\"]', 1),
(2498, 7951, 'A last-minute increase in guest numbers should be', 'single_choice', 4, '[\"Refused\",\"Confirmed in writing and communicated to kitchen, service and stewarding at once\",\"Handled on the day\",\"Accepted verbally only\"]', '[\"2\"]', 2),
(2499, 7951, 'In buffet service, food safety depends most on', 'single_choice', 4, '[\"Presentation\",\"Holding temperature and the time food has been on display\",\"The number of dishes\",\"Staff numbers\"]', '[\"2\"]', 3),
(2500, 7951, 'Room set-up should be completed', 'single_choice', 4, '[\"As guests arrive\",\"Before the agreed time, allowing for a final check\",\"Whenever the room is free\",\"By the client\"]', '[\"2\"]', 4),
(2501, 7952, 'An order entered incorrectly into the point of sale should be', 'single_choice', 4, '[\"Left and corrected on the bill\",\"Voided following the authorisation rule, with the reason recorded\",\"Deleted quietly\",\"Ignored if small\"]', '[\"2\"]', 1),
(2502, 7952, 'Voids and discounts are authorised because', 'single_choice', 4, '[\"It slows service\",\"They are the most common route for revenue loss and must be traceable\",\"The system requires it\",\"Guests expect it\"]', '[\"2\"]', 2),
(2503, 7952, 'Splitting a bill should be offered', 'single_choice', 4, '[\"Never\",\"When the table asks, and handled before payment begins\",\"Only for large groups\",\"After payment\"]', '[\"2\"]', 3),
(2504, 7952, 'The till is reconciled at the end of a shift to', 'single_choice', 4, '[\"Count staff\",\"Match takings against recorded sales and find differences while they can still be traced\",\"Set prices\",\"Order stock\"]', '[\"2\"]', 4),
(2505, 7953, 'An effective suggestion at the table is', 'single_choice', 4, '[\"The most expensive item\",\"A specific item that fits what the guest has already chosen\",\"Everything on the menu\",\"A discount\"]', '[\"2\"]', 1),
(2506, 7953, 'Order taking should begin with', 'single_choice', 4, '[\"The nearest guest\",\"A logical order the table can follow, noting seat positions so dishes reach the right person\",\"Whoever speaks first\",\"The host only\"]', '[\"2\"]', 2),
(2507, 7953, 'Repeating the order back to the table', 'single_choice', 4, '[\"Wastes time\",\"Catches errors before they reach the kitchen\",\"Is only for large tables\",\"Is unnecessary with a handheld device\"]', '[\"2\"]', 3),
(2508, 7953, 'Suggesting a dessert works best', 'single_choice', 4, '[\"With the main course order\",\"When the main plates are cleared and the guest is deciding whether to stay\",\"At arrival\",\"With the bill\"]', '[\"2\"]', 4),
(2509, 7954, 'Mise en place means', 'single_choice', 4, '[\"Cleaning down\",\"Everything prepared and in position before service begins\",\"The menu order\",\"The kitchen brigade\"]', '[\"2\"]', 1),
(2510, 7954, 'The brigade system exists to', 'single_choice', 4, '[\"Create hierarchy\",\"Divide the kitchen into sections with clear responsibility so service flows\",\"Reduce staff\",\"Set pay grades\"]', '[\"2\"]', 2),
(2511, 7954, 'A recipe specification is followed exactly because', 'single_choice', 4, '[\"The chef says so\",\"It controls cost, portion and consistency, which the guest and the margin both depend on\",\"It is faster\",\"It is not followed exactly\"]', '[\"2\"]', 3),
(2512, 7954, 'The pass is where', 'single_choice', 4, '[\"Deliveries arrive\",\"Finished dishes are checked before they leave the kitchen\",\"Waste is sorted\",\"Staff eat\"]', '[\"2\"]', 4),
(2513, 7955, 'The temperature danger zone is', 'single_choice', 4, '[\"0°C to 4°C\",\"5°C to 63°C\",\"63°C to 100°C\",\"Below 0°C\"]', '[\"2\"]', 1),
(2514, 7955, 'Cooked food to be cooled must pass through the danger zone', 'single_choice', 4, '[\"Slowly, at room temperature\",\"As quickly as possible, within the time the standard allows\",\"Overnight\",\"It does not matter\"]', '[\"2\"]', 2),
(2515, 7955, 'Raw meat is stored', 'single_choice', 4, '[\"Above ready-to-eat food\",\"Below ready-to-eat food, to prevent drips contaminating it\",\"Anywhere in the fridge\",\"At room temperature\"]', '[\"2\"]', 3),
(2516, 7955, 'Reheated food must reach a core temperature of at least', 'single_choice', 4, '[\"63°C\",\"75°C\",\"50°C\",\"100°C\"]', '[\"2\"]', 4),
(2517, 7956, 'A chef changes their apron', 'single_choice', 4, '[\"Once a week\",\"Whenever it is soiled, and between raw and ready-to-eat work\",\"At the end of the shift\",\"Never\"]', '[\"2\"]', 1),
(2518, 7956, 'Colour-coded boards are used so that', 'single_choice', 4, '[\"They look organised\",\"Raw and ready-to-eat foods never share a preparation surface\",\"They are easier to replace\",\"Chefs can find them\"]', '[\"2\"]', 2),
(2519, 7956, 'Hand contact with ready-to-eat food should be', 'single_choice', 4, '[\"Normal practice\",\"Minimised by using tongs, utensils or single-use gloves\",\"Avoided by washing hands only\",\"Unrestricted with gloves\"]', '[\"2\"]', 3),
(2520, 7956, 'A damaged chopping board must be', 'single_choice', 4, '[\"Cleaned more often\",\"Taken out of service, because cuts and cracks hold bacteria that cannot be cleaned out\",\"Turned over\",\"Sanded down\"]', '[\"2\"]', 4),
(2521, 7957, 'A sharp knife is safer than a blunt one because', 'single_choice', 4, '[\"It cuts less deeply\",\"It needs less force, so it is less likely to slip\",\"It is lighter\",\"It is not safer\"]', '[\"2\"]', 1),
(2522, 7957, 'A knife should be carried', 'single_choice', 4, '[\"Point up\",\"Point down, close to the body, blade turned away\",\"On a tray\",\"In a pocket\"]', '[\"2\"]', 2),
(2523, 7957, 'A falling knife should be', 'single_choice', 4, '[\"Caught\",\"Allowed to fall, with feet moved clear\",\"Kicked aside\",\"Caught by the handle\"]', '[\"2\"]', 3),
(2524, 7957, 'Knives are cleaned', 'single_choice', 4, '[\"In the dishwasher\",\"By hand, immediately, and never left in a sink of water\",\"At the end of service\",\"With the pans\"]', '[\"2\"]', 4),
(2525, 7958, 'FIFO means', 'single_choice', 4, '[\"Fresh In, Frozen Out\",\"First In, First Out, so older stock is used first\",\"Food Inspection For Operations\",\"Fast In, Fast Out\"]', '[\"2\"]', 1),
(2526, 7958, 'Dry goods are stored', 'single_choice', 4, '[\"On the floor\",\"Off the floor on shelving, in sealed containers, away from damp\",\"In the walkway\",\"Next to chemicals\"]', '[\"2\"]', 2),
(2527, 7958, 'An opened product must be', 'single_choice', 4, '[\"Used the same day\",\"Labelled with the date it was opened and its use-by date\",\"Returned to the supplier\",\"Left as delivered\"]', '[\"2\"]', 3),
(2528, 7958, 'Chemicals are stored', 'single_choice', 4, '[\"With the food\",\"In a separate, marked area away from all food\",\"Above the preparation surface\",\"In the fridge\"]', '[\"2\"]', 4),
(2529, 7959, 'A chilled delivery should be checked for temperature', 'single_choice', 4, '[\"After it is put away\",\"On arrival, before it is accepted\",\"The next day\",\"Only if it looks warm\"]', '[\"2\"]', 1),
(2530, 7959, 'A delivery that fails the check should be', 'single_choice', 4, '[\"Accepted and used quickly\",\"Rejected and recorded, with the supplier informed\",\"Accepted and frozen\",\"Accepted at a discount\"]', '[\"2\"]', 2);
INSERT INTO `question` (`id`, `quiz_id`, `title`, `type`, `number_of_options`, `options`, `correct_answers`, `order`) VALUES
(2531, 7959, 'Goods are checked against', 'single_choice', 4, '[\"Memory\",\"The purchase order and the delivery note, for quantity, quality and price\",\"The invoice only\",\"Nothing\"]', '[\"2\"]', 3),
(2532, 7959, 'Damaged packaging matters because', 'single_choice', 4, '[\"It looks poor\",\"The contents may be contaminated and the seal can no longer be relied on\",\"It is harder to store\",\"It does not matter\"]', '[\"2\"]', 4),
(2533, 7960, 'A fridge should run at', 'single_choice', 4, '[\"0°C to 5°C\",\"8°C to 12°C\",\"−18°C\",\"10°C\"]', '[\"1\"]', 1),
(2534, 7960, 'A freezer should run at or below', 'single_choice', 4, '[\"0°C\",\"−18°C\",\"−5°C\",\"4°C\"]', '[\"2\"]', 2),
(2535, 7960, 'Temperature checks are recorded because', 'single_choice', 4, '[\"It is a habit\",\"The record is the evidence that control was maintained, and shows trends before a failure\",\"The supplier asks\",\"They are not recorded\"]', '[\"2\"]', 3),
(2536, 7960, 'A probe thermometer is sanitised', 'single_choice', 4, '[\"Once a day\",\"Before and after every use, and between different foods\",\"Weekly\",\"Never\"]', '[\"2\"]', 4),
(2537, 7961, 'A guest asks whether a dish contains sesame. The correct response is', 'single_choice', 4, '[\"Say you think not\",\"Check the recipe specification and allergen record, and answer from that\",\"Say all dishes are safe\",\"Suggest they avoid it\"]', '[\"2\"]', 1),
(2538, 7961, 'The safest way to prepare an allergen-free dish is', 'single_choice', 4, '[\"Remove the ingredient at the end\",\"Prepare it separately with clean equipment and clean hands\",\"Cook it hotter\",\"Serve it first\"]', '[\"2\"]', 2),
(2539, 7961, 'Allergen information must be', 'single_choice', 4, '[\"Given only if asked\",\"Available and accurate for every dish served\",\"Kept in the office\",\"Estimated\"]', '[\"2\"]', 3),
(2540, 7961, 'A recipe change affecting allergens must be', 'single_choice', 4, '[\"Made quietly\",\"Recorded and communicated to service before the dish is sold\",\"Made only by the head chef\",\"Tested on staff first\"]', '[\"2\"]', 4),
(2541, 7962, 'Food waste is separated because', 'single_choice', 4, '[\"It is required by the landlord\",\"It can be measured and reduced, and it must be disposed of correctly\",\"It smells\",\"It is not separated\"]', '[\"2\"]', 1),
(2542, 7962, 'The largest avoidable source of kitchen waste is usually', 'single_choice', 4, '[\"Trimmings\",\"Over-production and spoilage from poor stock rotation\",\"Packaging\",\"Guest plates\"]', '[\"2\"]', 2),
(2543, 7962, 'Waste oil must be', 'single_choice', 4, '[\"Poured down the drain\",\"Collected and removed by an approved contractor\",\"Mixed with food waste\",\"Reused indefinitely\"]', '[\"2\"]', 3),
(2544, 7962, 'Recording waste is useful because', 'single_choice', 4, '[\"It satisfies the auditor\",\"It shows where product and money are actually being lost, so it can be fixed\",\"It is not useful\",\"It reduces cost directly\"]', '[\"2\"]', 4),
(2545, 7963, 'A cleaning schedule sets out', 'single_choice', 4, '[\"Who is on shift\",\"What is cleaned, how, how often, with what, and by whom\",\"The menu\",\"Delivery times\"]', '[\"2\"]', 1),
(2546, 7963, 'Clean as you go matters because', 'single_choice', 4, '[\"It looks better\",\"It stops contamination building up and keeps the workspace safe during service\",\"It saves chemicals\",\"It is not required\"]', '[\"2\"]', 2),
(2547, 7963, 'Equipment is dismantled for cleaning when', 'single_choice', 4, '[\"It is broken\",\"The manufacturer\'s instructions require it to reach food contact surfaces\",\"Once a year\",\"Never\"]', '[\"2\"]', 3),
(2548, 7963, 'Cleaning is signed off so that', 'single_choice', 4, '[\"Staff can be blamed\",\"There is a record that the task was done, by whom and when\",\"It takes longer\",\"The schedule is met\"]', '[\"2\"]', 4),
(2549, 7964, 'Engineering\'s main contribution to revenue is', 'single_choice', 4, '[\"Reducing the electricity bill\",\"Keeping rooms sellable, because an out-of-order room earns nothing\",\"Buying equipment cheaply\",\"Staffing levels\"]', '[\"2\"]', 1),
(2550, 7964, 'A fault reported by housekeeping should be', 'single_choice', 4, '[\"Fixed when convenient\",\"Logged as a work order, prioritised and tracked to completion\",\"Reported to the guest\",\"Fixed without record\"]', '[\"2\"]', 2),
(2551, 7964, 'Planned maintenance is preferred to reactive repair because', 'single_choice', 4, '[\"It is more interesting\",\"It is cheaper, and it fails at a time you choose rather than during a full house\",\"It uses fewer parts\",\"It is required by law\"]', '[\"2\"]', 3),
(2552, 7964, 'Which record tells you whether a recurring fault is really fixed?', 'single_choice', 4, '[\"The invoice\",\"The work order history for that asset\",\"The guest comment\",\"The duty log\"]', '[\"2\"]', 4),
(2553, 7965, 'Preventive maintenance is scheduled by', 'single_choice', 4, '[\"When something breaks\",\"Time or usage intervals set for each asset\",\"Guest complaints\",\"Budget availability\"]', '[\"2\"]', 1),
(2554, 7965, 'The cost of preventive maintenance is justified by', 'single_choice', 4, '[\"Longer asset life and fewer out-of-order rooms\",\"A lower headcount\",\"Cheaper parts\",\"Insurance discounts\"]', '[\"1\"]', 2),
(2555, 7965, 'A preventive task that is repeatedly skipped should be', 'single_choice', 4, '[\"Removed from the schedule\",\"Investigated, since either the interval is wrong or the resource is not there\",\"Done twice next time\",\"Ignored\"]', '[\"2\"]', 3),
(2556, 7965, 'Asset history is kept so that', 'single_choice', 4, '[\"The auditor is satisfied\",\"Replace-or-repair decisions are made on evidence rather than impression\",\"Staff can be assessed\",\"Warranty is valid\"]', '[\"2\"]', 4),
(2557, 7966, 'A guest reports the room will not cool. The first check is', 'single_choice', 4, '[\"Replace the unit\",\"The set point, the filter and whether a window or balcony door is open\",\"The chiller plant\",\"The thermostat wiring\"]', '[\"2\"]', 1),
(2558, 7966, 'Dirty air filters cause', 'single_choice', 4, '[\"Better filtration\",\"Reduced airflow, higher energy use and poorer cooling\",\"No change\",\"Lower running cost\"]', '[\"2\"]', 2),
(2559, 7966, 'Legionella risk in a building system is managed mainly by', 'single_choice', 4, '[\"Cleaning the ducts\",\"Controlling water temperature and avoiding stagnation\",\"Changing filters\",\"Running the system harder\"]', '[\"2\"]', 3),
(2560, 7966, 'Condensate drains are checked because', 'single_choice', 4, '[\"They are noisy\",\"A blocked drain causes water damage to ceilings and rooms below\",\"They affect temperature\",\"They do not need checking\"]', '[\"2\"]', 4),
(2561, 7967, 'Work on live electrical equipment is', 'single_choice', 4, '[\"Normal for small jobs\",\"Done only by a competent person, with the circuit isolated wherever possible\",\"Allowed with gloves\",\"Done by any technician\"]', '[\"2\"]', 1),
(2562, 7967, 'Lock-out tag-out exists to', 'single_choice', 4, '[\"Record who did the work\",\"Make sure isolated equipment cannot be re-energised while someone is working on it\",\"Prevent theft\",\"Satisfy the insurer\"]', '[\"2\"]', 2),
(2563, 7967, 'A damaged power cable in a guest room should be', 'single_choice', 4, '[\"Taped up\",\"Taken out of service immediately and the item replaced or repaired\",\"Left if it still works\",\"Reported next week\"]', '[\"2\"]', 3),
(2564, 7967, 'Portable appliance testing is done to', 'single_choice', 4, '[\"Extend warranty\",\"Confirm equipment is still electrically safe to use, on a set frequency\",\"Increase efficiency\",\"Track assets\"]', '[\"2\"]', 4),
(2565, 7968, 'The first action on a burst pipe in an occupied floor is', 'single_choice', 4, '[\"Call a contractor\",\"Isolate the water supply to that section\",\"Mop the floor\",\"Move the guest\"]', '[\"2\"]', 1),
(2566, 7968, 'A slow draining shower is most often caused by', 'single_choice', 4, '[\"Low water pressure\",\"A blockage of hair and soap in the trap\",\"A faulty valve\",\"Air in the system\"]', '[\"2\"]', 2),
(2567, 7968, 'Backflow prevention protects', 'single_choice', 4, '[\"The drains\",\"The drinking water supply from contamination\",\"The boiler\",\"The pump\"]', '[\"2\"]', 3),
(2568, 7968, 'Hot water delivered to a guest outlet must be', 'single_choice', 4, '[\"As hot as the system allows\",\"Controlled to prevent scalding, while stored hot enough to control bacteria\",\"Below 40°C in storage\",\"Unregulated\"]', '[\"2\"]', 4),
(2569, 7969, 'On discovering a fire, the first action is', 'single_choice', 4, '[\"Fight the fire\",\"Raise the alarm\",\"Open windows to clear smoke\",\"Find the fire marshal\"]', '[\"2\"]', 1),
(2570, 7969, 'A fire door must never be', 'single_choice', 4, '[\"Closed\",\"Wedged or propped open\",\"Signed\",\"Painted\"]', '[\"2\"]', 2),
(2571, 7969, 'A CO2 extinguisher is used on', 'single_choice', 4, '[\"Cooking oil fires\",\"Electrical fires\",\"Paper and wood\",\"Metal fires\"]', '[\"2\"]', 3),
(2572, 7969, 'The assembly point is where', 'single_choice', 4, '[\"Staff wait for instructions to return\",\"Everyone is accounted for after evacuation\",\"The fire panel is\",\"Guests collect belongings\"]', '[\"2\"]', 4),
(2573, 7970, 'A work order should record', 'single_choice', 4, '[\"Only the fault\",\"The asset, the fault, the priority, who did what and when it was closed\",\"The cost only\",\"The reporter\'s name\"]', '[\"2\"]', 1),
(2574, 7970, 'Priority on a work order is set by', 'single_choice', 4, '[\"Who reported it\",\"Impact on guest safety and on sellable rooms\",\"Ease of repair\",\"Age of the asset\"]', '[\"2\"]', 2),
(2575, 7970, 'A work order is closed when', 'single_choice', 4, '[\"The technician leaves\",\"The fault is fixed and verified, with the work recorded\",\"The part is ordered\",\"The shift ends\"]', '[\"2\"]', 3),
(2576, 7970, 'Open work orders are reviewed daily because', 'single_choice', 4, '[\"It fills the morning meeting\",\"Ageing jobs are the ones that become guest complaints and out-of-order rooms\",\"The system requires it\",\"They are not reviewed\"]', '[\"2\"]', 4),
(2577, 7971, 'An asset inspection checks', 'single_choice', 4, '[\"Only whether it runs\",\"Condition, safety, performance against its standard and what needs planning\",\"The purchase price\",\"The warranty\"]', '[\"2\"]', 1),
(2578, 7971, 'A defect found during inspection is', 'single_choice', 4, '[\"Fixed on the spot if possible, otherwise raised as a work order\",\"Noted for the annual review\",\"Reported verbally\",\"Ignored if minor\"]', '[\"1\"]', 2),
(2579, 7971, 'Inspection frequency is based on', 'single_choice', 4, '[\"Convenience\",\"Criticality, usage and manufacturer guidance\",\"Age alone\",\"Budget\"]', '[\"2\"]', 3),
(2580, 7971, 'Photographs on an inspection record help because', 'single_choice', 4, '[\"They look professional\",\"They show condition at a point in time, which makes deterioration visible\",\"They are required\",\"They speed up the inspection\"]', '[\"2\"]', 4),
(2581, 7972, 'In a power failure, the first priority is', 'single_choice', 4, '[\"Restoring the lifts\",\"Life safety systems and emergency lighting, and accounting for anyone trapped\",\"Restarting the kitchen\",\"Informing guests\"]', '[\"2\"]', 1),
(2582, 7972, 'A guest trapped in a lift should be', 'single_choice', 4, '[\"Told to wait quietly\",\"Kept in contact and reassured while trained release is arranged\",\"Released by any available staff member\",\"Left until the engineer arrives\"]', '[\"2\"]', 2),
(2583, 7972, 'Emergency contact lists are checked regularly because', 'single_choice', 4, '[\"Staff change and an out-of-date number costs time in the one moment it matters\",\"It is an audit point\",\"The list is long\",\"They are not checked\"]', '[\"1\"]', 3),
(2584, 7972, 'After any emergency, the hotel should', 'single_choice', 4, '[\"Return to normal quietly\",\"Review what happened, record it and change what did not work\",\"Report only if a guest was hurt\",\"Wait for the insurer\"]', '[\"2\"]', 4),
(2585, 7973, 'A hotel general manager\'s first responsibility is', 'single_choice', 4, '[\"Occupancy\",\"The safety of guests and staff\",\"Profit\",\"Guest satisfaction scores\"]', '[\"2\"]', 1),
(2586, 7973, 'Departments conflict most often over', 'single_choice', 4, '[\"Budget alone\",\"Room readiness, where housekeeping, engineering and front office share one deadline\",\"Staffing\",\"Menus\"]', '[\"2\"]', 2),
(2587, 7973, 'A daily operations meeting exists to', 'single_choice', 4, '[\"Review the previous year\",\"Align departments on today\'s arrivals, events, issues and constraints\",\"Set strategy\",\"Discuss payroll\"]', '[\"2\"]', 3),
(2588, 7973, 'Standard operating procedures matter most when', 'single_choice', 4, '[\"The hotel is quiet\",\"The hotel is busy or short staffed, and judgement alone will not hold the standard\",\"An auditor visits\",\"New staff join\"]', '[\"2\"]', 4),
(2589, 7974, 'A supervisor who only corrects mistakes will usually', 'single_choice', 4, '[\"Raise standards fastest\",\"Lose the team\'s willingness to raise problems early\",\"Be respected\",\"Reduce turnover\"]', '[\"2\"]', 1),
(2590, 7974, 'Delegation means', 'single_choice', 4, '[\"Giving away the difficult work\",\"Assigning responsibility with the authority and information to carry it out\",\"Avoiding accountability\",\"Reducing your workload\"]', '[\"2\"]', 2),
(2591, 7974, 'Feedback is most effective when it is', 'single_choice', 4, '[\"Given in the annual review\",\"Specific, timely and about the work rather than the person\",\"Given publicly\",\"Written only\"]', '[\"2\"]', 3),
(2592, 7974, 'High turnover in a hospitality team is most often driven by', 'single_choice', 4, '[\"Pay alone\",\"The immediate supervisor and the daily working conditions\",\"Guest behaviour\",\"Shift length\"]', '[\"2\"]', 4),
(2593, 7975, 'A rota should be built around', 'single_choice', 4, '[\"Staff preference alone\",\"Forecast demand, with skill mix covered on every shift\",\"Equal hours for everyone\",\"Seniority\"]', '[\"2\"]', 1),
(2594, 7975, 'A new starter\'s first week should include', 'single_choice', 4, '[\"Full independent shifts\",\"Safety, the standards they will be held to, and supervised practice\",\"Only paperwork\",\"Whatever the shift allows\"]', '[\"2\"]', 2),
(2595, 7975, 'Performance problems should be addressed', 'single_choice', 4, '[\"At the annual review\",\"Early and directly, with clear expectations and support\",\"By reassignment\",\"By the HR department only\"]', '[\"2\"]', 3),
(2596, 7975, 'Cross-training helps the operation because', 'single_choice', 4, '[\"It reduces pay\",\"It covers absence and peaks without adding headcount\",\"It simplifies the rota\",\"It reduces training cost\"]', '[\"2\"]', 4),
(2597, 7976, 'In the uniform system of accounts, departmental profit is', 'single_choice', 4, '[\"Revenue less all hotel costs\",\"Departmental revenue less the direct costs of that department\",\"Revenue less payroll\",\"Gross operating profit\"]', '[\"2\"]', 1),
(2598, 7976, 'A flow-through analysis shows', 'single_choice', 4, '[\"Cash movement\",\"How much of a change in revenue reaches profit\",\"Guest numbers\",\"Debt cover\"]', '[\"2\"]', 2),
(2599, 7976, 'Fixed costs in a hotel', 'single_choice', 4, '[\"Vary with occupancy\",\"Continue whether or not rooms are sold\",\"Are only payroll\",\"Are avoidable\"]', '[\"2\"]', 3),
(2600, 7976, 'A budget variance should be explained by', 'single_choice', 4, '[\"The finance team alone\",\"The department head who owns the line, with the reason and the action\",\"The auditor\",\"Nobody, if it is small\"]', '[\"2\"]', 4),
(2601, 7977, 'Revenue management is the practice of selling', 'single_choice', 4, '[\"The most rooms possible\",\"The right room to the right guest at the right time and price\",\"Rooms at the highest rate\",\"Through the most channels\"]', '[\"2\"]', 1),
(2602, 7977, 'Displacement analysis asks', 'single_choice', 4, '[\"How many guests moved rooms\",\"Whether accepting a group displaces higher-value transient business\",\"Which channel performed best\",\"How many cancelled\"]', '[\"2\"]', 2),
(2603, 7977, 'A rate parity failure means', 'single_choice', 4, '[\"Rates differ between room types\",\"The same room is offered at different rates across channels, undermining direct sales\",\"The rate is too low\",\"Rates changed overnight\"]', '[\"2\"]', 3),
(2604, 7977, 'Forecasting accuracy matters most because', 'single_choice', 4, '[\"It satisfies the owner\",\"Staffing, purchasing and pricing decisions are all made from it\",\"It sets the budget\",\"It is reported weekly\"]', '[\"2\"]', 4),
(2605, 7978, 'Cost control means', 'single_choice', 4, '[\"Spending less on everything\",\"Spending to a standard, and finding where spend does not produce value\",\"Cutting payroll\",\"Buying the cheapest option\"]', '[\"2\"]', 1),
(2606, 7978, 'Payroll is best controlled by', 'single_choice', 4, '[\"Cutting hours across the board\",\"Matching rostered hours to forecast demand\",\"Reducing pay rates\",\"Using agency staff\"]', '[\"2\"]', 2),
(2607, 7978, 'Purchasing through agreed suppliers helps because', 'single_choice', 4, '[\"It is faster\",\"It fixes specification and price, which makes variance visible\",\"It reduces paperwork\",\"It is required\"]', '[\"2\"]', 3),
(2608, 7978, 'A stock take that is consistently over should prompt', 'single_choice', 4, '[\"A change of supplier\",\"A check of recording, portioning and waste before assuming theft\",\"Reduced ordering\",\"No action\"]', '[\"2\"]', 4),
(2609, 7979, 'The guest experience is shaped most by', 'single_choice', 4, '[\"The building\",\"The moments where something goes wrong and how they are handled\",\"The rate\",\"The location\"]', '[\"2\"]', 1),
(2610, 7979, 'Service recovery done well often results in', 'single_choice', 4, '[\"A worse impression than if nothing had gone wrong\",\"Loyalty higher than if nothing had gone wrong\",\"No change\",\"A refund request\"]', '[\"2\"]', 2),
(2611, 7979, 'Guest feedback is most useful when', 'single_choice', 4, '[\"It is positive\",\"It is specific enough to act on and is routed to the team who can act\",\"It is anonymous\",\"It is public\"]', '[\"2\"]', 3),
(2612, 7979, 'A guest journey map is used to', 'single_choice', 4, '[\"Plan the building layout\",\"Find the points where the guest\'s experience is decided, and design those\",\"Track room moves\",\"Schedule staff\"]', '[\"2\"]', 4),
(2613, 7980, 'A quality standard is useful only if', 'single_choice', 4, '[\"It is written down\",\"It is measurable, and someone actually checks against it\",\"It is ambitious\",\"It matches competitors\"]', '[\"2\"]', 1),
(2614, 7980, 'Root cause analysis asks', 'single_choice', 4, '[\"Who was responsible\",\"Why the failure was possible, repeatedly, until the underlying cause is reached\",\"How much it cost\",\"When it happened\"]', '[\"2\"]', 2),
(2615, 7980, 'A mystery guest audit is most valuable when', 'single_choice', 4, '[\"The score is high\",\"The findings are acted on and re-checked\",\"It is announced\",\"It is frequent\"]', '[\"2\"]', 3),
(2616, 7980, 'Recurring complaints about the same issue indicate', 'single_choice', 4, '[\"Difficult guests\",\"A process problem rather than an individual one\",\"Bad luck\",\"A training need only\"]', '[\"2\"]', 4),
(2617, 7981, 'The first minutes of a crisis should be spent', 'single_choice', 4, '[\"Drafting a statement\",\"Making people safe and establishing who is in charge\",\"Informing the owner\",\"Investigating the cause\"]', '[\"2\"]', 1),
(2618, 7981, 'A single spokesperson is nominated so that', 'single_choice', 4, '[\"Others can avoid responsibility\",\"The hotel speaks with one accurate voice\",\"It is faster\",\"It is legally required\"]', '[\"2\"]', 2),
(2619, 7981, 'A crisis plan is tested because', 'single_choice', 4, '[\"Regulators require it\",\"An untested plan fails at the point of use, and the gaps are only visible in rehearsal\",\"It reassures staff\",\"It is cheap\"]', '[\"2\"]', 3),
(2620, 7981, 'After a crisis, guests and staff should receive', 'single_choice', 4, '[\"No further contact\",\"Follow-up and, where needed, support, since the effect outlasts the event\",\"A discount\",\"A survey\"]', '[\"2\"]', 4),
(2621, 7982, 'RevPAR is', 'single_choice', 4, '[\"Revenue per available room\",\"Revenue per arriving reservation\",\"Rate per available room\",\"Rooms per available rate\"]', '[\"1\"]', 1),
(2622, 7982, 'ADR measures', 'single_choice', 4, '[\"Total revenue divided by rooms available\",\"Room revenue divided by rooms sold\",\"Occupancy times rate\",\"Revenue per guest\"]', '[\"2\"]', 2),
(2623, 7982, 'A hotel with high occupancy and falling RevPAR is likely', 'single_choice', 4, '[\"Performing well\",\"Discounting too heavily to fill rooms\",\"Losing market share\",\"Understaffed\"]', '[\"2\"]', 3),
(2624, 7982, 'GOPPAR is more useful than RevPAR because it', 'single_choice', 4, '[\"Is easier to calculate\",\"Accounts for the cost of earning the revenue, not just the revenue\",\"Excludes departments\",\"Is reported daily\"]', '[\"2\"]', 4),
(2625, 7983, 'A property management system holds', 'single_choice', 4, '[\"Only room rates\",\"Reservations, guest profiles, room status, folios and the night audit\",\"Only housekeeping schedules\",\"Only the booking engine\"]', '[\"2\"]', 1),
(2626, 7983, 'Room status in the PMS should be updated by housekeeping because', 'single_choice', 4, '[\"The front desk cannot sell a room it believes is dirty\",\"It is a legal requirement\",\"It changes the rate\",\"It is not updated\"]', '[\"1\"]', 2),
(2627, 7983, 'A guest profile merged in error causes', 'single_choice', 4, '[\"No problem\",\"Charges and preferences attached to the wrong person, which is both a service and a data protection failure\",\"Faster check-in\",\"A rate change\"]', '[\"2\"]', 3),
(2628, 7983, 'Before overriding a PMS rate, an agent should', 'single_choice', 4, '[\"Override freely\",\"Follow the authorisation rule, because rate overrides are auditable\",\"Ask the guest\",\"Change it back afterwards\"]', '[\"2\"]', 4),
(2629, 7984, 'A channel manager exists to', 'single_choice', 4, '[\"Choose which OTAs to use\",\"Keep rates and availability consistent across every connected channel\",\"Negotiate commission\",\"Handle guest messages\"]', '[\"2\"]', 1),
(2630, 7984, 'Overbooking most often results from', 'single_choice', 4, '[\"Guest error\",\"Inventory not syncing between channels in time\",\"Rate changes\",\"Cancellations\"]', '[\"2\"]', 2),
(2631, 7984, 'Channel mix should be reviewed because', 'single_choice', 4, '[\"Contracts expire\",\"Each channel has a different cost of acquisition, and the mix decides net revenue\",\"OTAs require it\",\"It changes rarely\"]', '[\"2\"]', 3),
(2632, 7984, 'Closing a channel at short notice risks', 'single_choice', 4, '[\"Nothing\",\"Penalties and loss of ranking, so it is a planned decision rather than a reaction\",\"Lower rates\",\"Higher commission\"]', '[\"2\"]', 4),
(2633, 7985, 'The booking engine\'s main commercial purpose is', 'single_choice', 4, '[\"Displaying photographs\",\"Converting a visitor into a direct booking without commission\",\"Managing inventory\",\"Collecting reviews\"]', '[\"2\"]', 1),
(2634, 7985, 'The most common cause of booking abandonment is', 'single_choice', 4, '[\"Room photographs\",\"Unexpected cost or friction appearing late in the flow\",\"Too few room types\",\"Slow email\"]', '[\"2\"]', 2),
(2635, 7985, 'Mobile conversion matters because', 'single_choice', 4, '[\"It is fashionable\",\"A large share of hotel searches happen on a phone, and a poor mobile flow loses them\",\"Desktop is declining\",\"It affects SEO only\"]', '[\"2\"]', 3),
(2636, 7985, 'Rate parity with OTAs should be maintained so that', 'single_choice', 4, '[\"OTAs rank the hotel higher\",\"The direct channel is never more expensive than the commissioned one\",\"The rate is simple\",\"It is legally required everywhere\"]', '[\"2\"]', 4),
(2637, 7986, 'The strongest reason a guest books direct is usually', 'single_choice', 4, '[\"Loyalty points\",\"Confidence that the direct channel gives the best price and terms\",\"Website design\",\"Email offers\"]', '[\"2\"]', 1),
(2638, 7986, 'A direct booking strategy should begin with', 'single_choice', 4, '[\"Discounting below the OTA rate\",\"Making the direct channel at least as good, then making that visible\",\"Closing OTA channels\",\"Paid search only\"]', '[\"2\"]', 2),
(2639, 7986, 'Undercutting OTA rates publicly usually', 'single_choice', 4, '[\"Increases direct share safely\",\"Breaches parity agreements and can cost ranking or the contract\",\"Has no downside\",\"Is the standard approach\"]', '[\"2\"]', 3),
(2640, 7986, 'Direct booking value is measured by', 'single_choice', 4, '[\"Volume alone\",\"Net revenue after acquisition cost, compared with the same booking through an OTA\",\"Conversion rate\",\"Page views\"]', '[\"2\"]', 4),
(2641, 7987, 'OTA commission is best understood as', 'single_choice', 4, '[\"A marketing cost with a measurable return\",\"An unavoidable tax\",\"A fixed fee\",\"A discount to the guest\"]', '[\"1\"]', 1),
(2642, 7987, 'Content on an OTA listing should be', 'single_choice', 4, '[\"Minimal\",\"Complete and accurate, because it drives both ranking and guest expectation\",\"Copied from competitors\",\"Updated annually\"]', '[\"2\"]', 2),
(2643, 7987, 'A poor OTA review should be', 'single_choice', 4, '[\"Ignored\",\"Answered publicly, factually and without argument\",\"Disputed with the OTA\",\"Removed\"]', '[\"2\"]', 3),
(2644, 7987, 'The billboard effect describes', 'single_choice', 4, '[\"OTA advertising spend\",\"Guests finding a hotel on an OTA and then booking direct\",\"Roadside signage\",\"Rate parity\"]', '[\"2\"]', 4),
(2645, 7988, 'A useful metric is one that', 'single_choice', 4, '[\"Is easy to collect\",\"Changes a decision\",\"Looks good in a report\",\"Is tracked by competitors\"]', '[\"2\"]', 1),
(2646, 7988, 'Comparing this month to last month alone is misleading because', 'single_choice', 4, '[\"Months differ in length\",\"Hotel demand is seasonal, so the right comparison is the same period last year\",\"The data is late\",\"It is not misleading\"]', '[\"2\"]', 2),
(2647, 7988, 'Pace reporting shows', 'single_choice', 4, '[\"How fast the website loads\",\"How bookings for a future date are building compared with the same point last year\",\"Staff productivity\",\"Channel cost\"]', '[\"2\"]', 3),
(2648, 7988, 'A dashboard with fifty metrics usually', 'single_choice', 4, '[\"Gives the fullest picture\",\"Hides the few numbers that actually drive action\",\"Is best practice\",\"Is easier to read\"]', '[\"2\"]', 4),
(2649, 7989, 'Hotel marketing spend should be judged on', 'single_choice', 4, '[\"Impressions\",\"Revenue generated against cost, by channel\",\"Follower growth\",\"Click volume\"]', '[\"2\"]', 1),
(2650, 7989, 'The most valuable owned channel for a hotel is usually', 'single_choice', 4, '[\"Social media\",\"The guest email list, because it is direct and costs nothing per send\",\"Paid search\",\"Display advertising\"]', '[\"2\"]', 2),
(2651, 7989, 'Photography matters commercially because', 'single_choice', 4, '[\"It fills the website\",\"It is the single biggest driver of whether a listing converts\",\"It is cheap\",\"It supports SEO\"]', '[\"2\"]', 3),
(2652, 7989, 'Marketing to past guests works because', 'single_choice', 4, '[\"They are easy to reach\",\"They convert at a far higher rate and cost less to reach than new prospects\",\"They expect discounts\",\"It is required\"]', '[\"2\"]', 4),
(2653, 7990, 'For a hotel, the highest-value organic search terms are usually', 'single_choice', 4, '[\"Generic terms like \\\"hotel\\\"\",\"Location plus intent, such as \\\"hotel near Riyadh airport\\\"\",\"Brand terms only\",\"Competitor names\"]', '[\"2\"]', 1),
(2654, 7990, 'A Google Business Profile matters because', 'single_choice', 4, '[\"It replaces the website\",\"It is often the first and sometimes only result a local searcher sees\",\"It improves rankings directly\",\"It is required\"]', '[\"2\"]', 2),
(2655, 7990, 'Duplicate descriptions copied from an OTA harm the site because', 'single_choice', 4, '[\"The OTA objects\",\"Search engines have no reason to rank a page that adds nothing new\",\"They are too long\",\"They do not harm it\"]', '[\"2\"]', 3),
(2656, 7990, 'Page speed affects hotel SEO mainly through', 'single_choice', 4, '[\"Keyword ranking alone\",\"Users abandoning a slow page, which search engines observe\",\"Image quality\",\"Server cost\"]', '[\"2\"]', 4),
(2657, 7991, 'The most important thing to do with a negative review is', 'single_choice', 4, '[\"Dispute it\",\"Respond factually, and fix the cause if it is real\",\"Ignore it\",\"Ask for its removal\"]', '[\"2\"]', 1),
(2658, 7991, 'Review volume matters alongside score because', 'single_choice', 4, '[\"It affects commission\",\"A high score on very few reviews is not yet evidence\",\"It improves rate\",\"It does not matter\"]', '[\"2\"]', 2),
(2659, 7991, 'Asking every guest for a review is', 'single_choice', 4, '[\"Against policy everywhere\",\"Reasonable, provided it is not selective about who is asked\",\"Only for happy guests\",\"Ineffective\"]', '[\"2\"]', 3),
(2660, 7991, 'A pattern in reviews is more useful than any single review because', 'single_choice', 4, '[\"It is easier to read\",\"It points at a process that is repeatedly failing\",\"It is more recent\",\"It affects ranking more\"]', '[\"2\"]', 4),
(2661, 7992, 'When choosing hotel technology, integration matters because', 'single_choice', 4, '[\"It reduces licence cost\",\"Systems that cannot exchange data create manual work and errors\",\"It is a vendor requirement\",\"It speeds up training\"]', '[\"2\"]', 1),
(2662, 7992, 'Guest data held in a hotel system must be', 'single_choice', 4, '[\"Shared freely with partners\",\"Protected, with access limited to those who need it for their work\",\"Deleted monthly\",\"Stored locally only\"]', '[\"2\"]', 2),
(2663, 7992, 'The main risk in replacing a core system is', 'single_choice', 4, '[\"Cost\",\"Data migration and the period where staff know neither system well\",\"Vendor support\",\"Hardware\"]', '[\"2\"]', 3),
(2664, 7992, 'A technology decision should be led by', 'single_choice', 4, '[\"The IT supplier\",\"The operational problem it is meant to solve\",\"The lowest price\",\"What competitors use\"]', '[\"2\"]', 4),
(2665, 8659, 'A guest arrives at 11:00 and the room is not ready. What does the agent do first?', 'single_choice', 4, '[\"Tell the guest to come back at check-in time\",\"Acknowledge it, offer luggage storage and give a specific time the room will be ready\",\"Upgrade the guest to a suite at no charge\",\"Check the guest in anyway and let them wait in the corridor\"]', '[\"2\"]', 1),
(2666, 8659, 'What does the front office hand over at shift change?', 'single_choice', 4, '[\"Only the cash float\",\"Pending arrivals, guest requests still open, out-of-order rooms and anything unresolved\",\"Nothing, the system holds all of it\",\"Only complaints\"]', '[\"2\"]', 2),
(2667, 8659, 'Which department does the front desk depend on most to sell a clean room?', 'single_choice', 4, '[\"Engineering\",\"Housekeeping\",\"Finance\",\"Sales\"]', '[\"2\"]', 3),
(2668, 8659, 'A guest asks a question the agent cannot answer. The correct response is to', 'single_choice', 4, '[\"Guess, so the guest is not kept waiting\",\"Say it is not your department\",\"Say you will find out, give a time, and come back with the answer\",\"Refer them to the website\"]', '[\"3\"]', 4),
(2669, 8660, 'A walk-in guest arrives when the hotel is full. The agent should', 'single_choice', 4, '[\"Turn them away\",\"Check for cancellations, then help them find a room nearby if there is genuinely nothing\",\"Put them in an out-of-order room\",\"Ask them to wait indefinitely\"]', '[\"2\"]', 1),
(2670, 8660, 'The arrivals list is checked at the start of a shift to', 'single_choice', 4, '[\"Count staff\",\"Know who is coming, what they have asked for and which rooms are committed\",\"Set room rates\",\"Order breakfast\"]', '[\"2\"]', 2),
(2671, 8660, 'A reservation taken by phone must be read back because', 'single_choice', 4, '[\"It is polite\",\"It catches errors in dates, room type and spelling before they become a problem at arrival\",\"The system requires it\",\"It is not read back\"]', '[\"2\"]', 3),
(2672, 8660, 'Which of these is a front desk responsibility at every shift?', 'single_choice', 4, '[\"Counting and signing for the cash float\",\"Cleaning guest rooms\",\"Cooking breakfast\",\"Fixing air conditioning\"]', '[\"1\"]', 4),
(2673, 8661, 'What must be verified before a room key is issued?', 'single_choice', 4, '[\"The guest\'s identity against the reservation\",\"The guest\'s social media\",\"Nothing, the booking is enough\",\"Only the payment card\"]', '[\"1\"]', 1),
(2674, 8661, 'A guest booked a twin room and arrives expecting a double. What is the correct step?', 'single_choice', 4, '[\"Insist the booking is correct and move on\",\"Check availability for a double, explain the options and confirm before moving them\",\"Move them without telling them\",\"Charge a change fee first\"]', '[\"2\"]', 2),
(2675, 8661, 'Rooming a guest means', 'single_choice', 4, '[\"Leaving them to find the room themselves\",\"Escorting them and showing how the room works, then confirming they have what they need\",\"Sending a bellman with the luggage only\",\"Calling the room after ten minutes\"]', '[\"2\"]', 3),
(2676, 8661, 'When should the guest be told the checkout time?', 'single_choice', 4, '[\"Never, it is on the door\",\"At check-in, along with breakfast times and Wi-Fi\",\"Only if they ask\",\"On the morning of departure\"]', '[\"2\"]', 4),
(2677, 8662, 'A guest disputes a minibar charge at checkout. What is the first step?', 'single_choice', 4, '[\"Remove it immediately without checking\",\"Insist the charge stands\",\"Check the posting with housekeeping before deciding, and keep the guest informed\",\"Ask the guest to email the hotel later\"]', '[\"3\"]', 1),
(2678, 8662, 'What should be offered at the end of every checkout?', 'single_choice', 4, '[\"A discount voucher\",\"An itemised folio and help with onward travel or luggage\",\"A review request only\",\"Nothing\"]', '[\"2\"]', 2),
(2679, 8662, 'A late checkout request should be answered by', 'single_choice', 4, '[\"Refusing automatically\",\"Checking the arrivals for that room type before committing\",\"Always agreeing\",\"Charging a full extra night in every case\"]', '[\"2\"]', 3),
(2680, 8662, 'Why does the folio need to be accurate before the guest leaves?', 'single_choice', 4, '[\"It is easier to correct in person than after departure\",\"It is a legal requirement in every country\",\"It changes the room rate\",\"It is not important\"]', '[\"1\"]', 4),
(2681, 8663, 'The guest folio is', 'single_choice', 4, '[\"The room key record\",\"The running account of every charge and payment for that stay\",\"The housekeeping report\",\"The reservation confirmation\"]', '[\"2\"]', 1),
(2682, 8663, 'Which details must be captured at registration in Saudi Arabia?', 'single_choice', 4, '[\"Name only\",\"Identity document details as required by law, plus contact and payment\",\"Nothing, the booking suffices\",\"Social media handle\"]', '[\"2\"]', 2),
(2683, 8663, 'A registration card signed by the guest establishes', 'single_choice', 4, '[\"The guest\'s agreement to the rate and the hotel\'s terms\",\"The housekeeping schedule\",\"The loyalty tier\",\"Nothing legally\"]', '[\"1\"]', 3),
(2684, 8663, 'Where a guest declines to give required identity details, the agent should', 'single_choice', 4, '[\"Check them in anyway\",\"Explain that it is a legal requirement and involve the duty manager if it is refused\",\"Refuse service without explanation\",\"Copy details from a previous stay\"]', '[\"2\"]', 4),
(2685, 8664, 'Which guest should be prioritised when assigning the best available room?', 'single_choice', 4, '[\"The latest booker\",\"Guests with an accessibility requirement, then VIP and repeat guests\",\"Whoever complains most\",\"The cheapest rate\"]', '[\"2\"]', 1),
(2686, 8664, 'An accessible room should be held for', 'single_choice', 4, '[\"Anyone, it is a normal room\",\"A guest who has requested one, until it is clear none is needed\",\"Staff use\",\"Group bookings\"]', '[\"2\"]', 2),
(2687, 8664, 'A room marked out of order should be', 'single_choice', 4, '[\"Sold at a discount\",\"Kept out of inventory until engineering releases it\",\"Assigned to a late arrival\",\"Cleaned and sold\"]', '[\"2\"]', 3),
(2688, 8664, 'Why are connecting rooms held back during a family-heavy arrival day?', 'single_choice', 4, '[\"They are harder to clean\",\"They are the only option for families travelling with children and are quickly exhausted\",\"They cost more\",\"They are not held back\"]', '[\"2\"]', 4),
(2689, 8665, 'A guest asks for a restaurant recommendation. The best answer', 'single_choice', 4, '[\"Names the hotel restaurant only\",\"Asks what they are in the mood for, then gives two or three options with reasons\",\"Hands them a directory\",\"Names the most expensive option\"]', '[\"2\"]', 1),
(2690, 8665, 'The bell desk is responsible for', 'single_choice', 4, '[\"Room cleaning\",\"Luggage handling, storage and delivery, and assisting arrivals and departures\",\"Billing\",\"Reservations\"]', '[\"2\"]', 2),
(2691, 8665, 'When storing luggage, the item must be', 'single_choice', 4, '[\"Left in the lobby\",\"Tagged with a receipt given to the guest, and stored securely\",\"Kept behind the desk untagged\",\"Taken to the guest room\"]', '[\"2\"]', 3),
(2692, 8665, 'A concierge who cannot arrange a request should', 'single_choice', 4, '[\"Say it is impossible\",\"Offer the nearest alternative and be clear about what can and cannot be done\",\"Promise and then not deliver\",\"Refer the guest to reception\"]', '[\"2\"]', 4),
(2693, 8666, 'A guest is angry about noise from the room above. What comes first?', 'single_choice', 4, '[\"Explain the hotel policy\",\"Listen without interrupting, acknowledge the problem and apologise for the effect on them\",\"Offer a free night\",\"Ask them to put it in writing\"]', '[\"2\"]', 1),
(2694, 8666, 'What does LEARN stand for in complaint handling?', 'single_choice', 4, '[\"Listen, Empathise, Apologise, React, Notify\",\"Leave, Escalate, Argue, Refuse, Note\",\"Log, Email, Assign, Review, Notify\",\"Listen, Explain, Argue, Refund, Note\"]', '[\"1\"]', 2),
(2695, 8666, 'When a complaint cannot be resolved by the agent, the correct action is', 'single_choice', 4, '[\"Tell the guest nothing can be done\",\"Escalate to the duty manager with the facts, and tell the guest who will contact them and when\",\"Give the guest the manager\'s mobile number\",\"Wait until the next shift\"]', '[\"2\"]', 3),
(2696, 8666, 'Why is every complaint logged, even one resolved on the spot?', 'single_choice', 4, '[\"To justify refusing a refund later\",\"So repeat causes can be found and fixed\",\"It is not logged if resolved\",\"To record which staff member was at fault\"]', '[\"2\"]', 4),
(2697, 8667, 'A returning guest\'s preferences should be', 'single_choice', 4, '[\"Asked again every stay as if new\",\"Held on the profile and acted on before arrival\",\"Guessed\",\"Ignored\"]', '[\"2\"]', 1),
(2698, 8667, 'A VIP arrival is prepared by', 'single_choice', 4, '[\"Doing nothing different\",\"Checking the room personally, confirming amenities are placed and briefing the team who will meet them\",\"Assigning any available room\",\"Upgrading automatically\"]', '[\"2\"]', 2),
(2699, 8667, 'Recognising a repeat guest by name at arrival matters because', 'single_choice', 4, '[\"It is required by law\",\"It is the clearest signal that the hotel remembers them, and it costs nothing\",\"It speeds up check-in\",\"It does not matter\"]', '[\"2\"]', 3),
(2700, 8667, 'A VIP complaint should be handled', 'single_choice', 4, '[\"The same as any other, with the duty manager informed early\",\"By giving whatever is asked for\",\"By ignoring the normal process\",\"By the general manager only\"]', '[\"1\"]', 4),
(2701, 8668, 'Within how many rings should an internal call be answered as a standard?', 'single_choice', 4, '[\"Three\",\"Eight\",\"Fifteen\",\"It does not matter\"]', '[\"1\"]', 1),
(2702, 8668, 'The correct greeting on answering an external call includes', 'single_choice', 4, '[\"Just \\\"hello\\\"\",\"The hotel name, the department, your name and an offer of help\",\"Only your name\",\"The room number\"]', '[\"2\"]', 2),
(2703, 8668, 'Before placing a caller on hold you should', 'single_choice', 4, '[\"Put them on hold immediately\",\"Ask permission, explain why, and thank them when you return\",\"Transfer them instead\",\"Tell them to call back\"]', '[\"2\"]', 3),
(2704, 8668, 'A caller asks to be put through to a guest room. The agent should', 'single_choice', 4, '[\"Connect without confirming anything\",\"Ask for the guest name, and connect without revealing the room number\",\"Give the room number so the caller can dial direct\",\"Refuse all such calls\"]', '[\"2\"]', 4),
(2705, 8669, 'The best moment to offer a room upgrade is', 'single_choice', 4, '[\"After the guest has paid and left the desk\",\"At check-in, once you know what the guest is here for\",\"By email a week later\",\"At checkout\"]', '[\"2\"]', 1),
(2706, 8669, 'An effective upsell is based on', 'single_choice', 4, '[\"The highest priced room\",\"A benefit that matches what the guest said they need\",\"Pressure\",\"A script read word for word\"]', '[\"2\"]', 2),
(2707, 8669, 'A guest declines the upgrade. The agent should', 'single_choice', 4, '[\"Ask again immediately\",\"Accept it gracefully and continue the check-in normally\",\"Note them as difficult\",\"Offer a discount on the same room\"]', '[\"2\"]', 3),
(2708, 8669, 'Why does upselling fail when the guest is tired and late?', 'single_choice', 4, '[\"It does not fail\",\"The guest wants the room, not a decision, and pressing reads as an obstacle\",\"The system blocks it\",\"Rates change at night\"]', '[\"2\"]', 4),
(2709, 8670, 'The night audit exists to', 'single_choice', 4, '[\"Clean the lobby\",\"Close the financial day, post room and tax charges and reconcile the day\'s revenue\",\"Prepare breakfast\",\"Reset the key system\"]', '[\"2\"]', 1),
(2710, 8670, 'A discrepancy found during the audit should be', 'single_choice', 4, '[\"Corrected silently\",\"Documented with the correction and passed to the accounts team\",\"Left for the morning shift\",\"Ignored if it is small\"]', '[\"2\"]', 2),
(2711, 8670, 'Rooms still showing as occupied after the expected departure should be', 'single_choice', 4, '[\"Charged automatically\",\"Checked against housekeeping status before any charge is raised\",\"Released without checking\",\"Reported to the police\"]', '[\"2\"]', 3),
(2712, 8670, 'Why is the audit run at night?', 'single_choice', 4, '[\"Staff are cheaper\",\"It is the quietest point of the trading day, so the books can be closed against a stable position\",\"It is a legal requirement\",\"The system is faster\"]', '[\"2\"]', 4),
(2713, 8671, 'A caller asks whether a named guest is staying at the hotel. The correct answer is', 'single_choice', 4, '[\"Confirm and put the call through\",\"Neither confirm nor deny that the guest is in house\",\"Confirm but refuse to connect\",\"Give the room number only\"]', '[\"2\"]', 1),
(2714, 8671, 'Under the Saudi Personal Data Protection Law, guest data may be used', 'single_choice', 4, '[\"For any purpose the hotel chooses\",\"Only for the purpose it was collected for, unless the guest consents to more\",\"Freely once the guest has checked out\",\"For marketing by default\"]', '[\"2\"]', 2),
(2715, 8671, 'A printed arrivals list left on the desk is a problem because', 'single_choice', 4, '[\"It wastes paper\",\"It exposes guest names and room numbers to anyone passing\",\"It is out of date quickly\",\"It is not a problem\"]', '[\"2\"]', 3),
(2716, 8671, 'A guest asks what data the hotel holds about them. The correct response is', 'single_choice', 4, '[\"Refuse, it is internal\",\"Follow the hotel\'s data request procedure, which gives the guest a right to know\",\"Read it out from the screen immediately\",\"Tell them no data is held\"]', '[\"2\"]', 4),
(2717, 8672, 'What does a room attendant do before entering a guest room?', 'single_choice', 4, '[\"Enter using the key immediately\",\"Knock, announce \\\"housekeeping\\\", wait, repeat, then enter announcing again\",\"Call the guest from reception\",\"Wait for the guest to leave the floor\"]', '[\"2\"]', 1),
(2718, 8672, 'The housekeeping control desk is responsible for', 'single_choice', 4, '[\"Cooking\",\"Coordinating room status, assignments, keys and guest requests across the floors\",\"Billing guests\",\"Checking guests in\"]', '[\"2\"]', 2),
(2719, 8672, 'A room reported as \"clean\" but not inspected should be', 'single_choice', 4, '[\"Sold immediately\",\"Held until inspected, if the standard requires inspection before release\",\"Reported as out of order\",\"Cleaned again\"]', '[\"2\"]', 3),
(2720, 8672, 'Why is the cleaning sequence fixed rather than left to preference?', 'single_choice', 4, '[\"It is faster to supervise\",\"A fixed order prevents steps being missed and stops clean surfaces being recontaminated\",\"It is not fixed\",\"It saves chemicals\"]', '[\"2\"]', 4),
(2721, 8673, 'In what order should a guest room be cleaned?', 'single_choice', 4, '[\"Bathroom first, then bedroom, then floor\",\"Top to bottom and clean to dirty, finishing with the floor\",\"Floor first\",\"Whatever is quickest\"]', '[\"2\"]', 1),
(2722, 8673, 'Cloths are colour coded so that', 'single_choice', 4, '[\"They look tidy\",\"A cloth used in the toilet is never used on a surface a guest touches\",\"They match the uniform\",\"They are easier to count\"]', '[\"2\"]', 2),
(2723, 8673, 'A guest\'s personal belongings found during cleaning should be', 'single_choice', 4, '[\"Moved to a drawer\",\"Left where they are, tidied around but not handled or moved unnecessarily\",\"Put in lost and found\",\"Photographed\"]', '[\"2\"]', 3),
(2724, 8673, 'A departure room differs from a stayover room mainly because', 'single_choice', 4, '[\"It takes less time\",\"Everything is stripped and replaced, and the room is reset to a sellable standard\",\"Only the bed is made\",\"It needs no inspection\"]', '[\"2\"]', 4),
(2725, 8674, 'Linen should be changed on a stayover', 'single_choice', 4, '[\"Never\",\"According to the hotel standard, and always on request or when soiled\",\"Only at departure\",\"Every third day regardless\"]', '[\"2\"]', 1),
(2726, 8674, 'Stripped linen should be', 'single_choice', 4, '[\"Placed on the floor\",\"Placed directly into the linen bag on the trolley, never on the floor or furniture\",\"Left on the chair\",\"Shaken out in the room\"]', '[\"2\"]', 2),
(2727, 8674, 'Why is bed linen not shaken out in a guest room?', 'single_choice', 4, '[\"It creases\",\"It disperses dust and any contamination into the air the guest will breathe\",\"It takes longer\",\"It is allowed\"]', '[\"2\"]', 3),
(2728, 8674, 'A mattress protector is checked at every departure because', 'single_choice', 4, '[\"It is decorative\",\"A soiled protector means the mattress may be affected and must be dealt with before the room is sold\",\"It is not checked\",\"Guests ask about it\"]', '[\"2\"]', 4),
(2729, 8675, 'Which is cleaned last in a bathroom?', 'single_choice', 4, '[\"The mirror\",\"The toilet\",\"The basin\",\"The shower\"]', '[\"2\"]', 1),
(2730, 8675, 'A cloth used on the toilet may then be used on', 'single_choice', 4, '[\"The basin\",\"The mirror\",\"Nothing else, it is removed from service\",\"The bath\"]', '[\"3\"]', 2),
(2731, 8675, 'Contact time for a disinfectant means', 'single_choice', 4, '[\"How long it takes to apply\",\"The time the surface must stay wet for the product to work\",\"How long the bottle lasts\",\"The drying time\"]', '[\"2\"]', 3),
(2732, 8675, 'Bathroom amenities are replenished', 'single_choice', 4, '[\"Only at departure\",\"To the standard set for the room type, at every service\",\"When the guest asks\",\"Never\"]', '[\"2\"]', 4),
(2733, 8676, 'Room inspection exists to', 'single_choice', 4, '[\"Catch staff out\",\"Confirm the room meets the standard before it is sold, and find what training is needed\",\"Slow the release of rooms\",\"Satisfy the guest\"]', '[\"2\"]', 1),
(2734, 8676, 'An inspector finding a repeated fault across several rooms should', 'single_choice', 4, '[\"Fix it quietly\",\"Record it and raise it as a training or process issue, not just a room issue\",\"Ignore it\",\"Report the attendant\"]', '[\"2\"]', 2),
(2735, 8676, 'A room failing inspection is', 'single_choice', 4, '[\"Sold anyway\",\"Returned for correction and re-inspected before release\",\"Marked out of order\",\"Released with a note\"]', '[\"2\"]', 3),
(2736, 8676, 'Which is checked in an inspection but easily missed in cleaning?', 'single_choice', 4, '[\"The bed\",\"High and low surfaces, behind doors, and the underside of fittings\",\"The floor\",\"The towels\"]', '[\"2\"]', 4),
(2737, 8677, 'An item found in a departed room must be', 'single_choice', 4, '[\"Kept by the finder\",\"Logged with the room, date and finder, and stored securely\",\"Left in the room\",\"Thrown away\"]', '[\"2\"]', 1),
(2738, 8677, 'A guest calls about an item left behind. The correct step is', 'single_choice', 4, '[\"Say nothing was found\",\"Check the log, and arrange return at the guest\'s cost if it is there\",\"Post it immediately without checking\",\"Ask them to return\"]', '[\"2\"]', 2),
(2739, 8677, 'High-value items such as passports and jewellery should be', 'single_choice', 4, '[\"Stored with everything else\",\"Stored in the safe and reported to the duty manager the same day\",\"Returned to the room\",\"Held by the attendant\"]', '[\"2\"]', 3);
INSERT INTO `question` (`id`, `quiz_id`, `title`, `type`, `number_of_options`, `options`, `correct_answers`, `order`) VALUES
(2740, 8677, 'Unclaimed items are disposed of', 'single_choice', 4, '[\"Immediately\",\"After the retention period set by hotel policy, with the disposal recorded\",\"Never\",\"By the finder\"]', '[\"2\"]', 4),
(2741, 8678, 'Clean and soiled linen must be', 'single_choice', 4, '[\"Transported together to save time\",\"Kept separate at every stage, including transport and storage\",\"Stored in the same room\",\"Sorted by the guest\"]', '[\"2\"]', 1),
(2742, 8678, 'Linen stained with blood or bodily fluid is', 'single_choice', 4, '[\"Washed with the normal load\",\"Handled as infectious, bagged separately and washed to the required temperature\",\"Discarded\",\"Soaked in the room\"]', '[\"2\"]', 2),
(2743, 8678, 'Par stock for linen means', 'single_choice', 4, '[\"The cheapest supplier\",\"The quantity needed to keep every bed supplied while other sets are in circulation\",\"The stock in the laundry\",\"One set per bed\"]', '[\"2\"]', 3),
(2744, 8678, 'Overloading a washing machine results in', 'single_choice', 4, '[\"Faster cycles\",\"Linen that is not properly cleaned or rinsed, and more rewashing\",\"Lower cost\",\"No effect\"]', '[\"2\"]', 4),
(2745, 8679, 'A wet floor in a public area requires', 'single_choice', 4, '[\"No action if it is small\",\"A warning sign in place for as long as the floor is wet\",\"Closing the area\",\"Only a verbal warning\"]', '[\"2\"]', 1),
(2746, 8679, 'Public areas are cleaned on a frequency based on', 'single_choice', 4, '[\"Convenience\",\"Traffic and visibility, with high-touch points done most often\",\"Cost\",\"Guest complaints only\"]', '[\"2\"]', 2),
(2747, 8679, 'High-touch points in a lobby include', 'single_choice', 4, '[\"The ceiling\",\"Door handles, lift buttons, handrails and counter edges\",\"The carpet centre\",\"Artwork\"]', '[\"2\"]', 3),
(2748, 8679, 'Cleaning a public area during peak hours should', 'single_choice', 4, '[\"Proceed as normal\",\"Be limited to what can be done without obstructing guests, with the rest rescheduled\",\"Be skipped entirely\",\"Close the area\"]', '[\"2\"]', 4),
(2749, 8680, 'Deep cleaning differs from daily cleaning because it', 'single_choice', 4, '[\"Is faster\",\"Addresses what daily cleaning cannot reach, on a planned cycle\",\"Uses no chemicals\",\"Is done by the front desk\"]', '[\"2\"]', 1),
(2750, 8680, 'A room scheduled for deep cleaning should be', 'single_choice', 4, '[\"Sold as normal\",\"Blocked from sale for the time the work needs\",\"Cleaned around the guest\",\"Left until it is quiet\"]', '[\"2\"]', 2),
(2751, 8680, 'Deep cleaning is planned on a cycle because', 'single_choice', 4, '[\"It is cheaper\",\"Condition declines predictably, and planned work is cheaper than replacement\",\"Guests request it\",\"It is not planned\"]', '[\"2\"]', 3),
(2752, 8680, 'Which is a deep cleaning task rather than a daily one?', 'single_choice', 4, '[\"Making the bed\",\"Shampooing carpet and cleaning behind and under furniture\",\"Emptying the bin\",\"Replacing towels\"]', '[\"2\"]', 4),
(2753, 8681, 'Two cleaning chemicals should never be mixed because', 'single_choice', 4, '[\"It wastes product\",\"Some combinations, such as bleach and acid cleaners, release toxic gas\",\"It changes the colour\",\"It is allowed if diluted\"]', '[\"2\"]', 1),
(2754, 8681, 'Dilution rates are taken from', 'single_choice', 4, '[\"Experience\",\"The manufacturer\'s instructions and the product data sheet\",\"The strongest that works\",\"The supervisor\'s preference\"]', '[\"2\"]', 2),
(2755, 8681, 'A chemical decanted into a second container must be', 'single_choice', 4, '[\"Left unlabelled\",\"Labelled with the product name and its hazards\",\"Marked only with a colour\",\"Used the same day\"]', '[\"2\"]', 3),
(2756, 8681, 'The safety data sheet for a product tells you', 'single_choice', 4, '[\"The price\",\"The hazards, the protective equipment needed and what to do in an exposure\",\"The supplier address only\",\"Nothing useful\"]', '[\"2\"]', 4),
(2757, 8682, 'Room turnaround time is measured from', 'single_choice', 4, '[\"The guest\'s departure to the room being sellable again\",\"Check-in to checkout\",\"The start to the end of a shift\",\"The booking to the arrival\"]', '[\"1\"]', 1),
(2758, 8682, 'The biggest cause of slow turnaround on a busy departure day is usually', 'single_choice', 4, '[\"Slow attendants\",\"Rooms not being reported as vacant promptly, so cleaning starts late\",\"Too much linen\",\"Guests checking out early\"]', '[\"2\"]', 2),
(2759, 8682, 'Priority rooms in the turnaround queue are', 'single_choice', 4, '[\"The nearest to the linen room\",\"Those with a confirmed early arrival or a guest waiting\",\"The largest rooms\",\"The cheapest rooms\"]', '[\"2\"]', 3),
(2760, 8682, 'Rushing a turnaround typically costs the hotel more because', 'single_choice', 4, '[\"It uses more chemicals\",\"A room released below standard generates a complaint, a move and a refund\",\"It does not cost more\",\"Staff work overtime\"]', '[\"2\"]', 4),
(2761, 8683, 'A trolley is stocked before the shift so that', 'single_choice', 4, '[\"It looks tidy\",\"The attendant does not lose time returning to the store mid-room\",\"It is easier to push\",\"The supervisor can check it\"]', '[\"2\"]', 1),
(2762, 8683, 'Productivity in housekeeping is measured against', 'single_choice', 4, '[\"Rooms per hour alone\",\"Rooms cleaned to standard per hour, since a fast room that fails inspection is not done\",\"Chemicals used\",\"Hours worked\"]', '[\"2\"]', 2),
(2763, 8683, 'Which change most reliably improves productivity?', 'single_choice', 4, '[\"Working faster\",\"Removing interruptions and having the right supplies to hand\",\"Shorter breaks\",\"More staff\"]', '[\"2\"]', 3),
(2764, 8683, 'A room attendant consistently over time should first be', 'single_choice', 4, '[\"Disciplined\",\"Observed, to find whether the cause is method, supplies or the rooms assigned\",\"Reassigned\",\"Given fewer rooms\"]', '[\"2\"]', 4),
(2765, 8684, 'From which side is a plated dish normally served?', 'single_choice', 4, '[\"The guest\'s left, and cleared from the right\",\"The guest\'s right always\",\"Whichever is convenient\",\"Over the guest\'s shoulder\"]', '[\"1\"]', 1),
(2766, 8684, 'A guest at the table has not received their dish while others are eating. The server should', 'single_choice', 4, '[\"Say nothing\",\"Acknowledge it at once, check with the kitchen and give the guest a time\",\"Offer a free dessert\",\"Remove the other plates\"]', '[\"2\"]', 2),
(2767, 8684, 'Plates are cleared when', 'single_choice', 4, '[\"The first guest finishes\",\"Everyone at the table has finished\",\"The kitchen asks\",\"After thirty minutes\"]', '[\"2\"]', 3),
(2768, 8684, 'Carrying a tray, the server should', 'single_choice', 4, '[\"Hold it at chest height across the body\",\"Balance it on the flat palm and forearm, away from the body, loaded heaviest in the centre\",\"Carry it with both hands in front\",\"Rest it on the hip\"]', '[\"2\"]', 4),
(2769, 8685, 'A guest arriving without a reservation at a full restaurant should be', 'single_choice', 4, '[\"Turned away\",\"Given a realistic wait time and the option to wait or book another time\",\"Seated at a reserved table\",\"Asked to come back\"]', '[\"2\"]', 1),
(2770, 8685, 'Within how long should an arriving guest be acknowledged?', 'single_choice', 4, '[\"Thirty seconds, even if the host cannot seat them yet\",\"Five minutes\",\"When a table is free\",\"It does not matter\"]', '[\"1\"]', 2),
(2771, 8685, 'Seating a guest includes', 'single_choice', 4, '[\"Pointing to a table\",\"Escorting them, presenting the menu and telling them who will serve them\",\"Nothing more than showing the table\",\"Taking the order\"]', '[\"2\"]', 3),
(2772, 8685, 'A guest with a mobility aid should be seated', 'single_choice', 4, '[\"Wherever is free\",\"Where they can reach the table without obstruction, asked rather than assumed\",\"Near the door always\",\"At the back\"]', '[\"2\"]', 4),
(2773, 8686, 'In American style service, the food is', 'single_choice', 4, '[\"Carved at the table\",\"Plated in the kitchen and brought to the guest\",\"Served from a platter to the guest\'s plate\",\"Placed in the centre to share\"]', '[\"2\"]', 1),
(2774, 8686, 'Silver service differs in that the server', 'single_choice', 4, '[\"Plates in the kitchen\",\"Transfers food from a platter to the guest\'s plate at the table\",\"Leaves the platter with the guest\",\"Does not serve at all\"]', '[\"2\"]', 2),
(2775, 8686, 'Cutlery is laid', 'single_choice', 4, '[\"In any order\",\"From the outside in, in the order the courses will be eaten\",\"All on the right\",\"After the guest sits\"]', '[\"2\"]', 3),
(2776, 8686, 'The cover is checked before service to confirm', 'single_choice', 4, '[\"The bill is ready\",\"Everything is clean, matched, correctly spaced and free of marks\",\"The guest has arrived\",\"The menu is printed\"]', '[\"2\"]', 4),
(2777, 8687, 'Hot food held for service must be kept at or above', 'single_choice', 4, '[\"50°C\",\"60°C\",\"45°C\",\"37°C\"]', '[\"2\"]', 1),
(2778, 8687, 'A server notices a dish has been on the pass for twenty minutes. They should', 'single_choice', 4, '[\"Serve it quickly\",\"Not serve it, and tell the kitchen so it is replaced\",\"Reheat it under the lamp\",\"Serve it with an apology\"]', '[\"2\"]', 2),
(2779, 8687, 'A guest declares a nut allergy. The server must', 'single_choice', 4, '[\"Suggest dishes they think are safe\",\"Inform the kitchen, confirm with them, and not guess about any ingredient\",\"Say all food is safe\",\"Ask the guest to choose carefully\"]', '[\"2\"]', 3),
(2780, 8687, 'Cross-contamination in the service area most often happens through', 'single_choice', 4, '[\"The menu\",\"Hands, cloths and shared utensils moving between raw and ready-to-eat items\",\"The floor\",\"The till\"]', '[\"2\"]', 4),
(2781, 8688, 'HACCP stands for', 'single_choice', 4, '[\"Hotel and Catering Cleaning Procedure\",\"Hazard Analysis and Critical Control Points\",\"Health and Catering Control Plan\",\"Hygiene Assessment of Cooking and Chilling Practice\"]', '[\"2\"]', 1),
(2782, 8688, 'A critical control point is', 'single_choice', 4, '[\"Any step in the process\",\"A step where control is essential to prevent or eliminate a hazard\",\"The final inspection\",\"The delivery point\"]', '[\"2\"]', 2),
(2783, 8688, 'A critical limit is', 'single_choice', 4, '[\"The maximum number of guests\",\"The measurable boundary, such as a temperature, that separates safe from unsafe\",\"The budget\",\"The shelf life\"]', '[\"2\"]', 3),
(2784, 8688, 'When monitoring shows a critical limit has been breached,', 'single_choice', 4, '[\"Note it and continue\",\"Take the corrective action set out in the plan and record what was done\",\"Discard the record\",\"Inform the guest\"]', '[\"2\"]', 4),
(2785, 8689, 'Hands must be washed', 'single_choice', 4, '[\"At the start of the shift only\",\"After any task that could contaminate them, and between handling different foods\",\"Once an hour\",\"Only after the toilet\"]', '[\"2\"]', 1),
(2786, 8689, 'A server with vomiting or diarrhoea must', 'single_choice', 4, '[\"Work with gloves\",\"Report it and stay away from food handling until clear for the required period\",\"Work away from the kitchen\",\"Take medication and continue\"]', '[\"2\"]', 2),
(2787, 8689, 'A cut on the hand must be', 'single_choice', 4, '[\"Left uncovered\",\"Covered with a coloured waterproof dressing, and a glove worn over it\",\"Covered with any plaster\",\"Reason to go home\"]', '[\"2\"]', 3),
(2788, 8689, 'Jewellery is restricted in food areas because', 'single_choice', 4, '[\"It looks unprofessional\",\"It harbours bacteria and can fall into food\",\"It is expensive\",\"It is not restricted\"]', '[\"2\"]', 4),
(2789, 8690, 'Beverages are served', 'single_choice', 4, '[\"Before the guest orders\",\"From the guest\'s right, without reaching across\",\"From the left always\",\"By placing the tray on the table\"]', '[\"2\"]', 1),
(2790, 8690, 'A guest orders an alcoholic drink in a venue that does not serve alcohol. The server should', 'single_choice', 4, '[\"Argue\",\"Explain politely that it is not served and offer the alternatives available\",\"Ignore the request\",\"Send them elsewhere\"]', '[\"2\"]', 2),
(2791, 8690, 'Glassware is handled', 'single_choice', 4, '[\"By the rim\",\"By the stem or the base, never the rim\",\"With a cloth over the top\",\"However is fastest\"]', '[\"2\"]', 3),
(2792, 8690, 'A drink is checked before it leaves the bar for', 'single_choice', 4, '[\"Price\",\"Correct glass, correct garnish, correct level and a clean exterior\",\"Temperature only\",\"Nothing\"]', '[\"2\"]', 4),
(2793, 8691, 'The banquet event order exists to', 'single_choice', 4, '[\"Price the event\",\"Tell every department exactly what is required, when and where\",\"Record complaints\",\"Book the room\"]', '[\"2\"]', 1),
(2794, 8691, 'A last-minute increase in guest numbers should be', 'single_choice', 4, '[\"Refused\",\"Confirmed in writing and communicated to kitchen, service and stewarding at once\",\"Handled on the day\",\"Accepted verbally only\"]', '[\"2\"]', 2),
(2795, 8691, 'In buffet service, food safety depends most on', 'single_choice', 4, '[\"Presentation\",\"Holding temperature and the time food has been on display\",\"The number of dishes\",\"Staff numbers\"]', '[\"2\"]', 3),
(2796, 8691, 'Room set-up should be completed', 'single_choice', 4, '[\"As guests arrive\",\"Before the agreed time, allowing for a final check\",\"Whenever the room is free\",\"By the client\"]', '[\"2\"]', 4),
(2797, 8692, 'An order entered incorrectly into the point of sale should be', 'single_choice', 4, '[\"Left and corrected on the bill\",\"Voided following the authorisation rule, with the reason recorded\",\"Deleted quietly\",\"Ignored if small\"]', '[\"2\"]', 1),
(2798, 8692, 'Voids and discounts are authorised because', 'single_choice', 4, '[\"It slows service\",\"They are the most common route for revenue loss and must be traceable\",\"The system requires it\",\"Guests expect it\"]', '[\"2\"]', 2),
(2799, 8692, 'Splitting a bill should be offered', 'single_choice', 4, '[\"Never\",\"When the table asks, and handled before payment begins\",\"Only for large groups\",\"After payment\"]', '[\"2\"]', 3),
(2800, 8692, 'The till is reconciled at the end of a shift to', 'single_choice', 4, '[\"Count staff\",\"Match takings against recorded sales and find differences while they can still be traced\",\"Set prices\",\"Order stock\"]', '[\"2\"]', 4),
(2801, 8693, 'An effective suggestion at the table is', 'single_choice', 4, '[\"The most expensive item\",\"A specific item that fits what the guest has already chosen\",\"Everything on the menu\",\"A discount\"]', '[\"2\"]', 1),
(2802, 8693, 'Order taking should begin with', 'single_choice', 4, '[\"The nearest guest\",\"A logical order the table can follow, noting seat positions so dishes reach the right person\",\"Whoever speaks first\",\"The host only\"]', '[\"2\"]', 2),
(2803, 8693, 'Repeating the order back to the table', 'single_choice', 4, '[\"Wastes time\",\"Catches errors before they reach the kitchen\",\"Is only for large tables\",\"Is unnecessary with a handheld device\"]', '[\"2\"]', 3),
(2804, 8693, 'Suggesting a dessert works best', 'single_choice', 4, '[\"With the main course order\",\"When the main plates are cleared and the guest is deciding whether to stay\",\"At arrival\",\"With the bill\"]', '[\"2\"]', 4),
(2805, 8694, 'Mise en place means', 'single_choice', 4, '[\"Cleaning down\",\"Everything prepared and in position before service begins\",\"The menu order\",\"The kitchen brigade\"]', '[\"2\"]', 1),
(2806, 8694, 'The brigade system exists to', 'single_choice', 4, '[\"Create hierarchy\",\"Divide the kitchen into sections with clear responsibility so service flows\",\"Reduce staff\",\"Set pay grades\"]', '[\"2\"]', 2),
(2807, 8694, 'A recipe specification is followed exactly because', 'single_choice', 4, '[\"The chef says so\",\"It controls cost, portion and consistency, which the guest and the margin both depend on\",\"It is faster\",\"It is not followed exactly\"]', '[\"2\"]', 3),
(2808, 8694, 'The pass is where', 'single_choice', 4, '[\"Deliveries arrive\",\"Finished dishes are checked before they leave the kitchen\",\"Waste is sorted\",\"Staff eat\"]', '[\"2\"]', 4),
(2809, 8695, 'The temperature danger zone is', 'single_choice', 4, '[\"0°C to 4°C\",\"5°C to 63°C\",\"63°C to 100°C\",\"Below 0°C\"]', '[\"2\"]', 1),
(2810, 8695, 'Cooked food to be cooled must pass through the danger zone', 'single_choice', 4, '[\"Slowly, at room temperature\",\"As quickly as possible, within the time the standard allows\",\"Overnight\",\"It does not matter\"]', '[\"2\"]', 2),
(2811, 8695, 'Raw meat is stored', 'single_choice', 4, '[\"Above ready-to-eat food\",\"Below ready-to-eat food, to prevent drips contaminating it\",\"Anywhere in the fridge\",\"At room temperature\"]', '[\"2\"]', 3),
(2812, 8695, 'Reheated food must reach a core temperature of at least', 'single_choice', 4, '[\"63°C\",\"75°C\",\"50°C\",\"100°C\"]', '[\"2\"]', 4),
(2813, 8696, 'A chef changes their apron', 'single_choice', 4, '[\"Once a week\",\"Whenever it is soiled, and between raw and ready-to-eat work\",\"At the end of the shift\",\"Never\"]', '[\"2\"]', 1),
(2814, 8696, 'Colour-coded boards are used so that', 'single_choice', 4, '[\"They look organised\",\"Raw and ready-to-eat foods never share a preparation surface\",\"They are easier to replace\",\"Chefs can find them\"]', '[\"2\"]', 2),
(2815, 8696, 'Hand contact with ready-to-eat food should be', 'single_choice', 4, '[\"Normal practice\",\"Minimised by using tongs, utensils or single-use gloves\",\"Avoided by washing hands only\",\"Unrestricted with gloves\"]', '[\"2\"]', 3),
(2816, 8696, 'A damaged chopping board must be', 'single_choice', 4, '[\"Cleaned more often\",\"Taken out of service, because cuts and cracks hold bacteria that cannot be cleaned out\",\"Turned over\",\"Sanded down\"]', '[\"2\"]', 4),
(2817, 8697, 'A sharp knife is safer than a blunt one because', 'single_choice', 4, '[\"It cuts less deeply\",\"It needs less force, so it is less likely to slip\",\"It is lighter\",\"It is not safer\"]', '[\"2\"]', 1),
(2818, 8697, 'A knife should be carried', 'single_choice', 4, '[\"Point up\",\"Point down, close to the body, blade turned away\",\"On a tray\",\"In a pocket\"]', '[\"2\"]', 2),
(2819, 8697, 'A falling knife should be', 'single_choice', 4, '[\"Caught\",\"Allowed to fall, with feet moved clear\",\"Kicked aside\",\"Caught by the handle\"]', '[\"2\"]', 3),
(2820, 8697, 'Knives are cleaned', 'single_choice', 4, '[\"In the dishwasher\",\"By hand, immediately, and never left in a sink of water\",\"At the end of service\",\"With the pans\"]', '[\"2\"]', 4),
(2821, 8698, 'FIFO means', 'single_choice', 4, '[\"Fresh In, Frozen Out\",\"First In, First Out, so older stock is used first\",\"Food Inspection For Operations\",\"Fast In, Fast Out\"]', '[\"2\"]', 1),
(2822, 8698, 'Dry goods are stored', 'single_choice', 4, '[\"On the floor\",\"Off the floor on shelving, in sealed containers, away from damp\",\"In the walkway\",\"Next to chemicals\"]', '[\"2\"]', 2),
(2823, 8698, 'An opened product must be', 'single_choice', 4, '[\"Used the same day\",\"Labelled with the date it was opened and its use-by date\",\"Returned to the supplier\",\"Left as delivered\"]', '[\"2\"]', 3),
(2824, 8698, 'Chemicals are stored', 'single_choice', 4, '[\"With the food\",\"In a separate, marked area away from all food\",\"Above the preparation surface\",\"In the fridge\"]', '[\"2\"]', 4),
(2825, 8699, 'A chilled delivery should be checked for temperature', 'single_choice', 4, '[\"After it is put away\",\"On arrival, before it is accepted\",\"The next day\",\"Only if it looks warm\"]', '[\"2\"]', 1),
(2826, 8699, 'A delivery that fails the check should be', 'single_choice', 4, '[\"Accepted and used quickly\",\"Rejected and recorded, with the supplier informed\",\"Accepted and frozen\",\"Accepted at a discount\"]', '[\"2\"]', 2),
(2827, 8699, 'Goods are checked against', 'single_choice', 4, '[\"Memory\",\"The purchase order and the delivery note, for quantity, quality and price\",\"The invoice only\",\"Nothing\"]', '[\"2\"]', 3),
(2828, 8699, 'Damaged packaging matters because', 'single_choice', 4, '[\"It looks poor\",\"The contents may be contaminated and the seal can no longer be relied on\",\"It is harder to store\",\"It does not matter\"]', '[\"2\"]', 4),
(2829, 8700, 'A fridge should run at', 'single_choice', 4, '[\"0°C to 5°C\",\"8°C to 12°C\",\"−18°C\",\"10°C\"]', '[\"1\"]', 1),
(2830, 8700, 'A freezer should run at or below', 'single_choice', 4, '[\"0°C\",\"−18°C\",\"−5°C\",\"4°C\"]', '[\"2\"]', 2),
(2831, 8700, 'Temperature checks are recorded because', 'single_choice', 4, '[\"It is a habit\",\"The record is the evidence that control was maintained, and shows trends before a failure\",\"The supplier asks\",\"They are not recorded\"]', '[\"2\"]', 3),
(2832, 8700, 'A probe thermometer is sanitised', 'single_choice', 4, '[\"Once a day\",\"Before and after every use, and between different foods\",\"Weekly\",\"Never\"]', '[\"2\"]', 4),
(2833, 8701, 'A guest asks whether a dish contains sesame. The correct response is', 'single_choice', 4, '[\"Say you think not\",\"Check the recipe specification and allergen record, and answer from that\",\"Say all dishes are safe\",\"Suggest they avoid it\"]', '[\"2\"]', 1),
(2834, 8701, 'The safest way to prepare an allergen-free dish is', 'single_choice', 4, '[\"Remove the ingredient at the end\",\"Prepare it separately with clean equipment and clean hands\",\"Cook it hotter\",\"Serve it first\"]', '[\"2\"]', 2),
(2835, 8701, 'Allergen information must be', 'single_choice', 4, '[\"Given only if asked\",\"Available and accurate for every dish served\",\"Kept in the office\",\"Estimated\"]', '[\"2\"]', 3),
(2836, 8701, 'A recipe change affecting allergens must be', 'single_choice', 4, '[\"Made quietly\",\"Recorded and communicated to service before the dish is sold\",\"Made only by the head chef\",\"Tested on staff first\"]', '[\"2\"]', 4),
(2837, 8702, 'Food waste is separated because', 'single_choice', 4, '[\"It is required by the landlord\",\"It can be measured and reduced, and it must be disposed of correctly\",\"It smells\",\"It is not separated\"]', '[\"2\"]', 1),
(2838, 8702, 'The largest avoidable source of kitchen waste is usually', 'single_choice', 4, '[\"Trimmings\",\"Over-production and spoilage from poor stock rotation\",\"Packaging\",\"Guest plates\"]', '[\"2\"]', 2),
(2839, 8702, 'Waste oil must be', 'single_choice', 4, '[\"Poured down the drain\",\"Collected and removed by an approved contractor\",\"Mixed with food waste\",\"Reused indefinitely\"]', '[\"2\"]', 3),
(2840, 8702, 'Recording waste is useful because', 'single_choice', 4, '[\"It satisfies the auditor\",\"It shows where product and money are actually being lost, so it can be fixed\",\"It is not useful\",\"It reduces cost directly\"]', '[\"2\"]', 4),
(2841, 8703, 'A cleaning schedule sets out', 'single_choice', 4, '[\"Who is on shift\",\"What is cleaned, how, how often, with what, and by whom\",\"The menu\",\"Delivery times\"]', '[\"2\"]', 1),
(2842, 8703, 'Clean as you go matters because', 'single_choice', 4, '[\"It looks better\",\"It stops contamination building up and keeps the workspace safe during service\",\"It saves chemicals\",\"It is not required\"]', '[\"2\"]', 2),
(2843, 8703, 'Equipment is dismantled for cleaning when', 'single_choice', 4, '[\"It is broken\",\"The manufacturer\'s instructions require it to reach food contact surfaces\",\"Once a year\",\"Never\"]', '[\"2\"]', 3),
(2844, 8703, 'Cleaning is signed off so that', 'single_choice', 4, '[\"Staff can be blamed\",\"There is a record that the task was done, by whom and when\",\"It takes longer\",\"The schedule is met\"]', '[\"2\"]', 4),
(2845, 8704, 'Engineering\'s main contribution to revenue is', 'single_choice', 4, '[\"Reducing the electricity bill\",\"Keeping rooms sellable, because an out-of-order room earns nothing\",\"Buying equipment cheaply\",\"Staffing levels\"]', '[\"2\"]', 1),
(2846, 8704, 'A fault reported by housekeeping should be', 'single_choice', 4, '[\"Fixed when convenient\",\"Logged as a work order, prioritised and tracked to completion\",\"Reported to the guest\",\"Fixed without record\"]', '[\"2\"]', 2),
(2847, 8704, 'Planned maintenance is preferred to reactive repair because', 'single_choice', 4, '[\"It is more interesting\",\"It is cheaper, and it fails at a time you choose rather than during a full house\",\"It uses fewer parts\",\"It is required by law\"]', '[\"2\"]', 3),
(2848, 8704, 'Which record tells you whether a recurring fault is really fixed?', 'single_choice', 4, '[\"The invoice\",\"The work order history for that asset\",\"The guest comment\",\"The duty log\"]', '[\"2\"]', 4),
(2849, 8705, 'Preventive maintenance is scheduled by', 'single_choice', 4, '[\"When something breaks\",\"Time or usage intervals set for each asset\",\"Guest complaints\",\"Budget availability\"]', '[\"2\"]', 1),
(2850, 8705, 'The cost of preventive maintenance is justified by', 'single_choice', 4, '[\"Longer asset life and fewer out-of-order rooms\",\"A lower headcount\",\"Cheaper parts\",\"Insurance discounts\"]', '[\"1\"]', 2),
(2851, 8705, 'A preventive task that is repeatedly skipped should be', 'single_choice', 4, '[\"Removed from the schedule\",\"Investigated, since either the interval is wrong or the resource is not there\",\"Done twice next time\",\"Ignored\"]', '[\"2\"]', 3),
(2852, 8705, 'Asset history is kept so that', 'single_choice', 4, '[\"The auditor is satisfied\",\"Replace-or-repair decisions are made on evidence rather than impression\",\"Staff can be assessed\",\"Warranty is valid\"]', '[\"2\"]', 4),
(2853, 8706, 'A guest reports the room will not cool. The first check is', 'single_choice', 4, '[\"Replace the unit\",\"The set point, the filter and whether a window or balcony door is open\",\"The chiller plant\",\"The thermostat wiring\"]', '[\"2\"]', 1),
(2854, 8706, 'Dirty air filters cause', 'single_choice', 4, '[\"Better filtration\",\"Reduced airflow, higher energy use and poorer cooling\",\"No change\",\"Lower running cost\"]', '[\"2\"]', 2),
(2855, 8706, 'Legionella risk in a building system is managed mainly by', 'single_choice', 4, '[\"Cleaning the ducts\",\"Controlling water temperature and avoiding stagnation\",\"Changing filters\",\"Running the system harder\"]', '[\"2\"]', 3),
(2856, 8706, 'Condensate drains are checked because', 'single_choice', 4, '[\"They are noisy\",\"A blocked drain causes water damage to ceilings and rooms below\",\"They affect temperature\",\"They do not need checking\"]', '[\"2\"]', 4),
(2857, 8707, 'Work on live electrical equipment is', 'single_choice', 4, '[\"Normal for small jobs\",\"Done only by a competent person, with the circuit isolated wherever possible\",\"Allowed with gloves\",\"Done by any technician\"]', '[\"2\"]', 1),
(2858, 8707, 'Lock-out tag-out exists to', 'single_choice', 4, '[\"Record who did the work\",\"Make sure isolated equipment cannot be re-energised while someone is working on it\",\"Prevent theft\",\"Satisfy the insurer\"]', '[\"2\"]', 2),
(2859, 8707, 'A damaged power cable in a guest room should be', 'single_choice', 4, '[\"Taped up\",\"Taken out of service immediately and the item replaced or repaired\",\"Left if it still works\",\"Reported next week\"]', '[\"2\"]', 3),
(2860, 8707, 'Portable appliance testing is done to', 'single_choice', 4, '[\"Extend warranty\",\"Confirm equipment is still electrically safe to use, on a set frequency\",\"Increase efficiency\",\"Track assets\"]', '[\"2\"]', 4),
(2861, 8708, 'The first action on a burst pipe in an occupied floor is', 'single_choice', 4, '[\"Call a contractor\",\"Isolate the water supply to that section\",\"Mop the floor\",\"Move the guest\"]', '[\"2\"]', 1),
(2862, 8708, 'A slow draining shower is most often caused by', 'single_choice', 4, '[\"Low water pressure\",\"A blockage of hair and soap in the trap\",\"A faulty valve\",\"Air in the system\"]', '[\"2\"]', 2),
(2863, 8708, 'Backflow prevention protects', 'single_choice', 4, '[\"The drains\",\"The drinking water supply from contamination\",\"The boiler\",\"The pump\"]', '[\"2\"]', 3),
(2864, 8708, 'Hot water delivered to a guest outlet must be', 'single_choice', 4, '[\"As hot as the system allows\",\"Controlled to prevent scalding, while stored hot enough to control bacteria\",\"Below 40°C in storage\",\"Unregulated\"]', '[\"2\"]', 4),
(2865, 8709, 'On discovering a fire, the first action is', 'single_choice', 4, '[\"Fight the fire\",\"Raise the alarm\",\"Open windows to clear smoke\",\"Find the fire marshal\"]', '[\"2\"]', 1),
(2866, 8709, 'A fire door must never be', 'single_choice', 4, '[\"Closed\",\"Wedged or propped open\",\"Signed\",\"Painted\"]', '[\"2\"]', 2),
(2867, 8709, 'A CO2 extinguisher is used on', 'single_choice', 4, '[\"Cooking oil fires\",\"Electrical fires\",\"Paper and wood\",\"Metal fires\"]', '[\"2\"]', 3),
(2868, 8709, 'The assembly point is where', 'single_choice', 4, '[\"Staff wait for instructions to return\",\"Everyone is accounted for after evacuation\",\"The fire panel is\",\"Guests collect belongings\"]', '[\"2\"]', 4),
(2869, 8710, 'A work order should record', 'single_choice', 4, '[\"Only the fault\",\"The asset, the fault, the priority, who did what and when it was closed\",\"The cost only\",\"The reporter\'s name\"]', '[\"2\"]', 1),
(2870, 8710, 'Priority on a work order is set by', 'single_choice', 4, '[\"Who reported it\",\"Impact on guest safety and on sellable rooms\",\"Ease of repair\",\"Age of the asset\"]', '[\"2\"]', 2),
(2871, 8710, 'A work order is closed when', 'single_choice', 4, '[\"The technician leaves\",\"The fault is fixed and verified, with the work recorded\",\"The part is ordered\",\"The shift ends\"]', '[\"2\"]', 3),
(2872, 8710, 'Open work orders are reviewed daily because', 'single_choice', 4, '[\"It fills the morning meeting\",\"Ageing jobs are the ones that become guest complaints and out-of-order rooms\",\"The system requires it\",\"They are not reviewed\"]', '[\"2\"]', 4),
(2873, 8711, 'An asset inspection checks', 'single_choice', 4, '[\"Only whether it runs\",\"Condition, safety, performance against its standard and what needs planning\",\"The purchase price\",\"The warranty\"]', '[\"2\"]', 1),
(2874, 8711, 'A defect found during inspection is', 'single_choice', 4, '[\"Fixed on the spot if possible, otherwise raised as a work order\",\"Noted for the annual review\",\"Reported verbally\",\"Ignored if minor\"]', '[\"1\"]', 2),
(2875, 8711, 'Inspection frequency is based on', 'single_choice', 4, '[\"Convenience\",\"Criticality, usage and manufacturer guidance\",\"Age alone\",\"Budget\"]', '[\"2\"]', 3),
(2876, 8711, 'Photographs on an inspection record help because', 'single_choice', 4, '[\"They look professional\",\"They show condition at a point in time, which makes deterioration visible\",\"They are required\",\"They speed up the inspection\"]', '[\"2\"]', 4),
(2877, 8712, 'In a power failure, the first priority is', 'single_choice', 4, '[\"Restoring the lifts\",\"Life safety systems and emergency lighting, and accounting for anyone trapped\",\"Restarting the kitchen\",\"Informing guests\"]', '[\"2\"]', 1),
(2878, 8712, 'A guest trapped in a lift should be', 'single_choice', 4, '[\"Told to wait quietly\",\"Kept in contact and reassured while trained release is arranged\",\"Released by any available staff member\",\"Left until the engineer arrives\"]', '[\"2\"]', 2),
(2879, 8712, 'Emergency contact lists are checked regularly because', 'single_choice', 4, '[\"Staff change and an out-of-date number costs time in the one moment it matters\",\"It is an audit point\",\"The list is long\",\"They are not checked\"]', '[\"1\"]', 3),
(2880, 8712, 'After any emergency, the hotel should', 'single_choice', 4, '[\"Return to normal quietly\",\"Review what happened, record it and change what did not work\",\"Report only if a guest was hurt\",\"Wait for the insurer\"]', '[\"2\"]', 4),
(2881, 8713, 'A hotel general manager\'s first responsibility is', 'single_choice', 4, '[\"Occupancy\",\"The safety of guests and staff\",\"Profit\",\"Guest satisfaction scores\"]', '[\"2\"]', 1),
(2882, 8713, 'Departments conflict most often over', 'single_choice', 4, '[\"Budget alone\",\"Room readiness, where housekeeping, engineering and front office share one deadline\",\"Staffing\",\"Menus\"]', '[\"2\"]', 2),
(2883, 8713, 'A daily operations meeting exists to', 'single_choice', 4, '[\"Review the previous year\",\"Align departments on today\'s arrivals, events, issues and constraints\",\"Set strategy\",\"Discuss payroll\"]', '[\"2\"]', 3),
(2884, 8713, 'Standard operating procedures matter most when', 'single_choice', 4, '[\"The hotel is quiet\",\"The hotel is busy or short staffed, and judgement alone will not hold the standard\",\"An auditor visits\",\"New staff join\"]', '[\"2\"]', 4),
(2885, 8714, 'A supervisor who only corrects mistakes will usually', 'single_choice', 4, '[\"Raise standards fastest\",\"Lose the team\'s willingness to raise problems early\",\"Be respected\",\"Reduce turnover\"]', '[\"2\"]', 1),
(2886, 8714, 'Delegation means', 'single_choice', 4, '[\"Giving away the difficult work\",\"Assigning responsibility with the authority and information to carry it out\",\"Avoiding accountability\",\"Reducing your workload\"]', '[\"2\"]', 2),
(2887, 8714, 'Feedback is most effective when it is', 'single_choice', 4, '[\"Given in the annual review\",\"Specific, timely and about the work rather than the person\",\"Given publicly\",\"Written only\"]', '[\"2\"]', 3),
(2888, 8714, 'High turnover in a hospitality team is most often driven by', 'single_choice', 4, '[\"Pay alone\",\"The immediate supervisor and the daily working conditions\",\"Guest behaviour\",\"Shift length\"]', '[\"2\"]', 4),
(2889, 8715, 'A rota should be built around', 'single_choice', 4, '[\"Staff preference alone\",\"Forecast demand, with skill mix covered on every shift\",\"Equal hours for everyone\",\"Seniority\"]', '[\"2\"]', 1),
(2890, 8715, 'A new starter\'s first week should include', 'single_choice', 4, '[\"Full independent shifts\",\"Safety, the standards they will be held to, and supervised practice\",\"Only paperwork\",\"Whatever the shift allows\"]', '[\"2\"]', 2),
(2891, 8715, 'Performance problems should be addressed', 'single_choice', 4, '[\"At the annual review\",\"Early and directly, with clear expectations and support\",\"By reassignment\",\"By the HR department only\"]', '[\"2\"]', 3),
(2892, 8715, 'Cross-training helps the operation because', 'single_choice', 4, '[\"It reduces pay\",\"It covers absence and peaks without adding headcount\",\"It simplifies the rota\",\"It reduces training cost\"]', '[\"2\"]', 4),
(2893, 8716, 'In the uniform system of accounts, departmental profit is', 'single_choice', 4, '[\"Revenue less all hotel costs\",\"Departmental revenue less the direct costs of that department\",\"Revenue less payroll\",\"Gross operating profit\"]', '[\"2\"]', 1),
(2894, 8716, 'A flow-through analysis shows', 'single_choice', 4, '[\"Cash movement\",\"How much of a change in revenue reaches profit\",\"Guest numbers\",\"Debt cover\"]', '[\"2\"]', 2),
(2895, 8716, 'Fixed costs in a hotel', 'single_choice', 4, '[\"Vary with occupancy\",\"Continue whether or not rooms are sold\",\"Are only payroll\",\"Are avoidable\"]', '[\"2\"]', 3),
(2896, 8716, 'A budget variance should be explained by', 'single_choice', 4, '[\"The finance team alone\",\"The department head who owns the line, with the reason and the action\",\"The auditor\",\"Nobody, if it is small\"]', '[\"2\"]', 4),
(2897, 8717, 'Revenue management is the practice of selling', 'single_choice', 4, '[\"The most rooms possible\",\"The right room to the right guest at the right time and price\",\"Rooms at the highest rate\",\"Through the most channels\"]', '[\"2\"]', 1),
(2898, 8717, 'Displacement analysis asks', 'single_choice', 4, '[\"How many guests moved rooms\",\"Whether accepting a group displaces higher-value transient business\",\"Which channel performed best\",\"How many cancelled\"]', '[\"2\"]', 2),
(2899, 8717, 'A rate parity failure means', 'single_choice', 4, '[\"Rates differ between room types\",\"The same room is offered at different rates across channels, undermining direct sales\",\"The rate is too low\",\"Rates changed overnight\"]', '[\"2\"]', 3),
(2900, 8717, 'Forecasting accuracy matters most because', 'single_choice', 4, '[\"It satisfies the owner\",\"Staffing, purchasing and pricing decisions are all made from it\",\"It sets the budget\",\"It is reported weekly\"]', '[\"2\"]', 4),
(2901, 8718, 'Cost control means', 'single_choice', 4, '[\"Spending less on everything\",\"Spending to a standard, and finding where spend does not produce value\",\"Cutting payroll\",\"Buying the cheapest option\"]', '[\"2\"]', 1),
(2902, 8718, 'Payroll is best controlled by', 'single_choice', 4, '[\"Cutting hours across the board\",\"Matching rostered hours to forecast demand\",\"Reducing pay rates\",\"Using agency staff\"]', '[\"2\"]', 2),
(2903, 8718, 'Purchasing through agreed suppliers helps because', 'single_choice', 4, '[\"It is faster\",\"It fixes specification and price, which makes variance visible\",\"It reduces paperwork\",\"It is required\"]', '[\"2\"]', 3),
(2904, 8718, 'A stock take that is consistently over should prompt', 'single_choice', 4, '[\"A change of supplier\",\"A check of recording, portioning and waste before assuming theft\",\"Reduced ordering\",\"No action\"]', '[\"2\"]', 4),
(2905, 8719, 'The guest experience is shaped most by', 'single_choice', 4, '[\"The building\",\"The moments where something goes wrong and how they are handled\",\"The rate\",\"The location\"]', '[\"2\"]', 1),
(2906, 8719, 'Service recovery done well often results in', 'single_choice', 4, '[\"A worse impression than if nothing had gone wrong\",\"Loyalty higher than if nothing had gone wrong\",\"No change\",\"A refund request\"]', '[\"2\"]', 2),
(2907, 8719, 'Guest feedback is most useful when', 'single_choice', 4, '[\"It is positive\",\"It is specific enough to act on and is routed to the team who can act\",\"It is anonymous\",\"It is public\"]', '[\"2\"]', 3),
(2908, 8719, 'A guest journey map is used to', 'single_choice', 4, '[\"Plan the building layout\",\"Find the points where the guest\'s experience is decided, and design those\",\"Track room moves\",\"Schedule staff\"]', '[\"2\"]', 4),
(2909, 8720, 'A quality standard is useful only if', 'single_choice', 4, '[\"It is written down\",\"It is measurable, and someone actually checks against it\",\"It is ambitious\",\"It matches competitors\"]', '[\"2\"]', 1),
(2910, 8720, 'Root cause analysis asks', 'single_choice', 4, '[\"Who was responsible\",\"Why the failure was possible, repeatedly, until the underlying cause is reached\",\"How much it cost\",\"When it happened\"]', '[\"2\"]', 2),
(2911, 8720, 'A mystery guest audit is most valuable when', 'single_choice', 4, '[\"The score is high\",\"The findings are acted on and re-checked\",\"It is announced\",\"It is frequent\"]', '[\"2\"]', 3),
(2912, 8720, 'Recurring complaints about the same issue indicate', 'single_choice', 4, '[\"Difficult guests\",\"A process problem rather than an individual one\",\"Bad luck\",\"A training need only\"]', '[\"2\"]', 4),
(2913, 8721, 'The first minutes of a crisis should be spent', 'single_choice', 4, '[\"Drafting a statement\",\"Making people safe and establishing who is in charge\",\"Informing the owner\",\"Investigating the cause\"]', '[\"2\"]', 1),
(2914, 8721, 'A single spokesperson is nominated so that', 'single_choice', 4, '[\"Others can avoid responsibility\",\"The hotel speaks with one accurate voice\",\"It is faster\",\"It is legally required\"]', '[\"2\"]', 2),
(2915, 8721, 'A crisis plan is tested because', 'single_choice', 4, '[\"Regulators require it\",\"An untested plan fails at the point of use, and the gaps are only visible in rehearsal\",\"It reassures staff\",\"It is cheap\"]', '[\"2\"]', 3),
(2916, 8721, 'After a crisis, guests and staff should receive', 'single_choice', 4, '[\"No further contact\",\"Follow-up and, where needed, support, since the effect outlasts the event\",\"A discount\",\"A survey\"]', '[\"2\"]', 4),
(2917, 8722, 'RevPAR is', 'single_choice', 4, '[\"Revenue per available room\",\"Revenue per arriving reservation\",\"Rate per available room\",\"Rooms per available rate\"]', '[\"1\"]', 1),
(2918, 8722, 'ADR measures', 'single_choice', 4, '[\"Total revenue divided by rooms available\",\"Room revenue divided by rooms sold\",\"Occupancy times rate\",\"Revenue per guest\"]', '[\"2\"]', 2),
(2919, 8722, 'A hotel with high occupancy and falling RevPAR is likely', 'single_choice', 4, '[\"Performing well\",\"Discounting too heavily to fill rooms\",\"Losing market share\",\"Understaffed\"]', '[\"2\"]', 3),
(2920, 8722, 'GOPPAR is more useful than RevPAR because it', 'single_choice', 4, '[\"Is easier to calculate\",\"Accounts for the cost of earning the revenue, not just the revenue\",\"Excludes departments\",\"Is reported daily\"]', '[\"2\"]', 4),
(2921, 8723, 'A property management system holds', 'single_choice', 4, '[\"Only room rates\",\"Reservations, guest profiles, room status, folios and the night audit\",\"Only housekeeping schedules\",\"Only the booking engine\"]', '[\"2\"]', 1),
(2922, 8723, 'Room status in the PMS should be updated by housekeeping because', 'single_choice', 4, '[\"The front desk cannot sell a room it believes is dirty\",\"It is a legal requirement\",\"It changes the rate\",\"It is not updated\"]', '[\"1\"]', 2),
(2923, 8723, 'A guest profile merged in error causes', 'single_choice', 4, '[\"No problem\",\"Charges and preferences attached to the wrong person, which is both a service and a data protection failure\",\"Faster check-in\",\"A rate change\"]', '[\"2\"]', 3),
(2924, 8723, 'Before overriding a PMS rate, an agent should', 'single_choice', 4, '[\"Override freely\",\"Follow the authorisation rule, because rate overrides are auditable\",\"Ask the guest\",\"Change it back afterwards\"]', '[\"2\"]', 4),
(2925, 8724, 'A channel manager exists to', 'single_choice', 4, '[\"Choose which OTAs to use\",\"Keep rates and availability consistent across every connected channel\",\"Negotiate commission\",\"Handle guest messages\"]', '[\"2\"]', 1),
(2926, 8724, 'Overbooking most often results from', 'single_choice', 4, '[\"Guest error\",\"Inventory not syncing between channels in time\",\"Rate changes\",\"Cancellations\"]', '[\"2\"]', 2),
(2927, 8724, 'Channel mix should be reviewed because', 'single_choice', 4, '[\"Contracts expire\",\"Each channel has a different cost of acquisition, and the mix decides net revenue\",\"OTAs require it\",\"It changes rarely\"]', '[\"2\"]', 3),
(2928, 8724, 'Closing a channel at short notice risks', 'single_choice', 4, '[\"Nothing\",\"Penalties and loss of ranking, so it is a planned decision rather than a reaction\",\"Lower rates\",\"Higher commission\"]', '[\"2\"]', 4),
(2929, 8725, 'The booking engine\'s main commercial purpose is', 'single_choice', 4, '[\"Displaying photographs\",\"Converting a visitor into a direct booking without commission\",\"Managing inventory\",\"Collecting reviews\"]', '[\"2\"]', 1),
(2930, 8725, 'The most common cause of booking abandonment is', 'single_choice', 4, '[\"Room photographs\",\"Unexpected cost or friction appearing late in the flow\",\"Too few room types\",\"Slow email\"]', '[\"2\"]', 2),
(2931, 8725, 'Mobile conversion matters because', 'single_choice', 4, '[\"It is fashionable\",\"A large share of hotel searches happen on a phone, and a poor mobile flow loses them\",\"Desktop is declining\",\"It affects SEO only\"]', '[\"2\"]', 3),
(2932, 8725, 'Rate parity with OTAs should be maintained so that', 'single_choice', 4, '[\"OTAs rank the hotel higher\",\"The direct channel is never more expensive than the commissioned one\",\"The rate is simple\",\"It is legally required everywhere\"]', '[\"2\"]', 4),
(2933, 8726, 'The strongest reason a guest books direct is usually', 'single_choice', 4, '[\"Loyalty points\",\"Confidence that the direct channel gives the best price and terms\",\"Website design\",\"Email offers\"]', '[\"2\"]', 1),
(2934, 8726, 'A direct booking strategy should begin with', 'single_choice', 4, '[\"Discounting below the OTA rate\",\"Making the direct channel at least as good, then making that visible\",\"Closing OTA channels\",\"Paid search only\"]', '[\"2\"]', 2),
(2935, 8726, 'Undercutting OTA rates publicly usually', 'single_choice', 4, '[\"Increases direct share safely\",\"Breaches parity agreements and can cost ranking or the contract\",\"Has no downside\",\"Is the standard approach\"]', '[\"2\"]', 3),
(2936, 8726, 'Direct booking value is measured by', 'single_choice', 4, '[\"Volume alone\",\"Net revenue after acquisition cost, compared with the same booking through an OTA\",\"Conversion rate\",\"Page views\"]', '[\"2\"]', 4),
(2937, 8727, 'OTA commission is best understood as', 'single_choice', 4, '[\"A marketing cost with a measurable return\",\"An unavoidable tax\",\"A fixed fee\",\"A discount to the guest\"]', '[\"1\"]', 1),
(2938, 8727, 'Content on an OTA listing should be', 'single_choice', 4, '[\"Minimal\",\"Complete and accurate, because it drives both ranking and guest expectation\",\"Copied from competitors\",\"Updated annually\"]', '[\"2\"]', 2),
(2939, 8727, 'A poor OTA review should be', 'single_choice', 4, '[\"Ignored\",\"Answered publicly, factually and without argument\",\"Disputed with the OTA\",\"Removed\"]', '[\"2\"]', 3),
(2940, 8727, 'The billboard effect describes', 'single_choice', 4, '[\"OTA advertising spend\",\"Guests finding a hotel on an OTA and then booking direct\",\"Roadside signage\",\"Rate parity\"]', '[\"2\"]', 4),
(2941, 8728, 'A useful metric is one that', 'single_choice', 4, '[\"Is easy to collect\",\"Changes a decision\",\"Looks good in a report\",\"Is tracked by competitors\"]', '[\"2\"]', 1),
(2942, 8728, 'Comparing this month to last month alone is misleading because', 'single_choice', 4, '[\"Months differ in length\",\"Hotel demand is seasonal, so the right comparison is the same period last year\",\"The data is late\",\"It is not misleading\"]', '[\"2\"]', 2),
(2943, 8728, 'Pace reporting shows', 'single_choice', 4, '[\"How fast the website loads\",\"How bookings for a future date are building compared with the same point last year\",\"Staff productivity\",\"Channel cost\"]', '[\"2\"]', 3),
(2944, 8728, 'A dashboard with fifty metrics usually', 'single_choice', 4, '[\"Gives the fullest picture\",\"Hides the few numbers that actually drive action\",\"Is best practice\",\"Is easier to read\"]', '[\"2\"]', 4),
(2945, 8729, 'Hotel marketing spend should be judged on', 'single_choice', 4, '[\"Impressions\",\"Revenue generated against cost, by channel\",\"Follower growth\",\"Click volume\"]', '[\"2\"]', 1),
(2946, 8729, 'The most valuable owned channel for a hotel is usually', 'single_choice', 4, '[\"Social media\",\"The guest email list, because it is direct and costs nothing per send\",\"Paid search\",\"Display advertising\"]', '[\"2\"]', 2),
(2947, 8729, 'Photography matters commercially because', 'single_choice', 4, '[\"It fills the website\",\"It is the single biggest driver of whether a listing converts\",\"It is cheap\",\"It supports SEO\"]', '[\"2\"]', 3),
(2948, 8729, 'Marketing to past guests works because', 'single_choice', 4, '[\"They are easy to reach\",\"They convert at a far higher rate and cost less to reach than new prospects\",\"They expect discounts\",\"It is required\"]', '[\"2\"]', 4),
(2949, 8730, 'For a hotel, the highest-value organic search terms are usually', 'single_choice', 4, '[\"Generic terms like \\\"hotel\\\"\",\"Location plus intent, such as \\\"hotel near Riyadh airport\\\"\",\"Brand terms only\",\"Competitor names\"]', '[\"2\"]', 1),
(2950, 8730, 'A Google Business Profile matters because', 'single_choice', 4, '[\"It replaces the website\",\"It is often the first and sometimes only result a local searcher sees\",\"It improves rankings directly\",\"It is required\"]', '[\"2\"]', 2),
(2951, 8730, 'Duplicate descriptions copied from an OTA harm the site because', 'single_choice', 4, '[\"The OTA objects\",\"Search engines have no reason to rank a page that adds nothing new\",\"They are too long\",\"They do not harm it\"]', '[\"2\"]', 3),
(2952, 8730, 'Page speed affects hotel SEO mainly through', 'single_choice', 4, '[\"Keyword ranking alone\",\"Users abandoning a slow page, which search engines observe\",\"Image quality\",\"Server cost\"]', '[\"2\"]', 4),
(2953, 8731, 'The most important thing to do with a negative review is', 'single_choice', 4, '[\"Dispute it\",\"Respond factually, and fix the cause if it is real\",\"Ignore it\",\"Ask for its removal\"]', '[\"2\"]', 1),
(2954, 8731, 'Review volume matters alongside score because', 'single_choice', 4, '[\"It affects commission\",\"A high score on very few reviews is not yet evidence\",\"It improves rate\",\"It does not matter\"]', '[\"2\"]', 2),
(2955, 8731, 'Asking every guest for a review is', 'single_choice', 4, '[\"Against policy everywhere\",\"Reasonable, provided it is not selective about who is asked\",\"Only for happy guests\",\"Ineffective\"]', '[\"2\"]', 3),
(2956, 8731, 'A pattern in reviews is more useful than any single review because', 'single_choice', 4, '[\"It is easier to read\",\"It points at a process that is repeatedly failing\",\"It is more recent\",\"It affects ranking more\"]', '[\"2\"]', 4),
(2957, 8732, 'When choosing hotel technology, integration matters because', 'single_choice', 4, '[\"It reduces licence cost\",\"Systems that cannot exchange data create manual work and errors\",\"It is a vendor requirement\",\"It speeds up training\"]', '[\"2\"]', 1);
INSERT INTO `question` (`id`, `quiz_id`, `title`, `type`, `number_of_options`, `options`, `correct_answers`, `order`) VALUES
(2958, 8732, 'Guest data held in a hotel system must be', 'single_choice', 4, '[\"Shared freely with partners\",\"Protected, with access limited to those who need it for their work\",\"Deleted monthly\",\"Stored locally only\"]', '[\"2\"]', 2),
(2959, 8732, 'The main risk in replacing a core system is', 'single_choice', 4, '[\"Cost\",\"Data migration and the period where staff know neither system well\",\"Vendor support\",\"Hardware\"]', '[\"2\"]', 3),
(2960, 8732, 'A technology decision should be led by', 'single_choice', 4, '[\"The IT supplier\",\"The operational problem it is meant to solve\",\"The lowest price\",\"What competitors use\"]', '[\"2\"]', 4);
